		end
		timeout = tonumber(timeout) or config.get("agent.toolTimeout", 25)

		-- The call's id travels with the context so a tool that emits events of its own
		-- can address the row it belongs to. dispatch_agent needs it: its subagent's
		-- live feed has to appear under the call that started it. Shallow, deliberately:
		-- ctx carries the session and the module env, and a deep copy of either would be
		-- both enormous and wrong.
		local scoped = ctx
		if type(ctx) == "table" then
			scoped = util.copy(ctx)
			scoped.callId = call.id
		end
		local finished, ok, value = clock.timeout(timeout, function()
			return tool.run(coerced, scoped)
		end)

		if not finished then
			result.text = string.format(
				"%s did not finish within %ds. It may still be running, but nothing will collect its result, so treat it as lost. Do not retry the same call.",
				name, timeout)
			result.error = "timeout"
			result.ms = clock.since(started)
			return result
		end

		if not ok then
			result.text = string.format("%s failed: %s", name, util.ellipsis(tostring(value), 400))
			result.error = "error"
			result.ms = clock.since(started)
			log.warn("tools", name .. " raised", value)
			return result
		end

		local text, data, handlerOk
		if type(value) == "table" then
			text = tostring(value.text or "")
			data = value.data
			-- A handler may report a semantic failure -- a path that does not exist,
			-- a host that cannot do the thing -- without raising. That is not an
			-- error in the tool, but it is not a success either, and the transcript
			-- should say so.
			handlerOk = value.ok ~= false
		else
			text = tostring(value == nil and "Done." or value)
			handlerOk = true
		end

		local after = { tool = tool, args = coerced, text = text, data = data, ctx = ctx }
		hooks.run("postTool", after)
		text = tostring(after.text or text)

		local cap = config.get("agent.resultCap", 4000)
		local capped, truncated = util.truncate(text, cap, "ask for a narrower slice if you need the rest")
		result.ok = handlerOk
		if not handlerOk then result.error = "tool reported a failure" end
		result.text = capped
		result.full = truncated and text or nil
		result.truncated = truncated
		result.data = after.data
		result.ms = clock.since(started)
		return result
	end

	-- Runs a batch with a concurrency cap.
	--
	-- The model is told parallel calls are executed together, and they are: each
	-- runs on its own thread, up to `agent.toolConcurrency` at a time. Dispatch
	-- carries its own timeout, so the batch cannot outlive the slowest permitted
	-- call by more than a poll interval.
	function M.runAll(calls, ctx)
		local total = #calls
		local results = {}
		if total == 0 then return results end

		local cap = math.max(config.get("agent.toolConcurrency", 4), 1)
		local launched, completed = 0, 0

		while completed < total do
			while launched < total and (launched - completed) < cap do
				launched = launched + 1
				local index = launched
				task.spawn(function()
					local ok, value = pcall(M.dispatch, calls[index], ctx)
					if ok then
						results[index] = value
					else
						results[index] = {
							id = calls[index].id,
							name = (calls[index]["function"] or {}).name or "unknown",
							ok = false,
							error = "dispatch failed",
							text = "Internal error running the tool: " .. tostring(value),
							ms = 0,
						}
						log.error("tools", "dispatch crashed", value)
					end
					completed = completed + 1
				end)
			end
			if completed < total then clock.wait() end
		end

		return results
	end

	return M
end
end)()

-- ==========================================================================
-- agent/schema
-- ==========================================================================
__UAI_MODULES["agent/schema"] = (function()
-- JSON-schema validation, argument coercion, and repair of malformed tool
-- arguments.
--
-- Models emit arguments as a JSON string, and that string is sometimes wrong: cut
-- off mid-object when the completion hit its token limit, wrapped in a code
-- fence, carrying a trailing comma, or using a number where the schema says
-- string. Rejecting those outright wastes a whole turn, so each is repaired where
-- the repair is unambiguous and reported where it is not.
return function(env)
	local util = env.require("runtime/util")

	local M = {}

	-- Repair -----------------------------------------------------------------

	-- Walks the text tracking string state, so a brace inside a string literal
	-- does not count towards the balance. Returns the closers needed, and whether
	-- a string was left open.
	local function scanBalance(text)
		local stack, inString, escaped = {}, false, false
		for index = 1, #text do
			local char = text:sub(index, index)
			if inString then
				if escaped then
					escaped = false
				elseif char == "\\" then
					escaped = true
				elseif char == '"' then
					inString = false
				end
			else
				if char == '"' then
					inString = true
				elseif char == "{" or char == "[" then
					stack[#stack + 1] = char
				elseif char == "}" or char == "]" then
					table.remove(stack)
				end
			end
		end
		local closers = {}
		for index = #stack, 1, -1 do
			closers[#closers + 1] = (stack[index] == "{") and "}" or "]"
		end
		return table.concat(closers), inString
	end

	function M.repairJson(raw)
		local text = util.trim(raw)
		if text == "" then return {}, "empty arguments treated as {}" end

		-- Fenced output happens when a model narrates its tool call.
		text = text:gsub("^```%a*%s*", ""):gsub("```%s*$", "")
		text = util.trim(text)

		local direct = util.decode(text)
		if type(direct) == "table" then return direct, nil end

		-- Prose around the object is common; take the outermost bracketed span.
		local first = text:find("[%{%[]")
		local last = text:match(".*()[%}%]]")
		if first and last and last > first then
			local slice = text:sub(first, last)
			local attempt = util.decode(slice)
			if type(attempt) == "table" then return attempt, "stripped text around the JSON object" end
			text = slice
		end

		local noTrailing = text:gsub(",%s*([%}%]])", "%1")
		local attempt = util.decode(noTrailing)
		if type(attempt) == "table" then return attempt, "removed a trailing comma" end
		text = noTrailing

		-- Python-flavoured literals show up from some fine-tunes.
		local pythonic = text:gsub("%f[%w]None%f[%W]", "null")
			:gsub("%f[%w]True%f[%W]", "true")
			:gsub("%f[%w]False%f[%W]", "false")
		if pythonic ~= text then
			attempt = util.decode(pythonic)
			if type(attempt) == "table" then return attempt, "converted Python literals" end
			text = pythonic
		end

		local closers, openString = scanBalance(text)
		if openString or closers ~= "" then
			local patched = text
			if openString then patched = patched .. '"' end
			-- A truncated object usually ends mid-value; dropping the dangling
			-- key-value pair is more likely to parse than closing around it.
			local candidates = {
				patched .. closers,
				(patched:gsub(",%s*\"[^\"]*\"%s*:%s*$", "") .. closers),
				(patched:gsub(",[^,]*$", "") .. closers),
			}
			for _, candidate in ipairs(candidates) do
				local repaired = util.decode(candidate)
				if type(repaired) == "table" then
					return repaired, "completed a truncated JSON object"
				end
			end
		end

		return nil, "arguments were not valid JSON"
	end

	-- Validation -------------------------------------------------------------

	local function typeOf(value)
		if type(value) == "table" then
			return util.isArray(value) and "array" or "object"
		end
		return type(value)
	end

	-- Coercion is one-directional and lossless-ish: a model that answers "5" for a
	-- number, or 5 for a string, meant the obvious thing. Anything ambiguous is a
	-- validation error instead.
	local function coerce(value, wanted)
		local actual = typeOf(value)
		if wanted == nil or wanted == actual then return value, false end
		if wanted == "number" or wanted == "integer" then
			local number = tonumber(value)
			if number == nil then return value, false end
			if wanted == "integer" then number = math.floor(number) end
			return number, true
		end
		if wanted == "string" then
			if actual == "number" or actual == "boolean" then return tostring(value), true end
			return value, false
		end
		if wanted == "boolean" then
			if value == "true" or value == 1 then return true, true end
			if value == "false" or value == 0 then return false, true end
			return value, false
		end
		if wanted == "array" and actual ~= "table" then
			return { value }, true
		end
		if wanted == "object" and actual == "array" and #value == 0 then
			return {}, true
		end
		return value, false
	end

	local function checkValue(schema, value, path, out)
		if type(schema) ~= "table" then return value end
		local wanted = schema.type
		if type(wanted) == "table" then wanted = wanted[1] end

		local coerced, didCoerce = coerce(value, wanted)
		if didCoerce then out.coercions[#out.coercions + 1] = path end
		value = coerced

		local actual = typeOf(value)
		-- An empty Lua table is both an empty array and an empty object, and a model
		-- that sends `[]` for a tool with no arguments is common enough that
		-- rejecting it would waste a turn on nothing.
		if wanted == "object" and actual == "array" and next(value) == nil then
			actual = "object"
		end
		if wanted and actual ~= wanted then
			if not (wanted == "integer" and actual == "number") then
				out.errors[#out.errors + 1] = string.format("%s should be %s, got %s", path, wanted, actual)
				return value
			end
		end

		if schema.enum then
			local allowed = false
			for _, option in ipairs(schema.enum) do
				if option == value then allowed = true end
			end
			if not allowed then
				out.errors[#out.errors + 1] = string.format("%s must be one of: %s",
					path, table.concat(util.map(schema.enum, tostring), ", "))
			end
		end

		if wanted == "number" or wanted == "integer" then
			if schema.minimum and value < schema.minimum then
				out.errors[#out.errors + 1] = string.format("%s must be at least %s", path, tostring(schema.minimum))
			end
			if schema.maximum and value > schema.maximum then
				out.errors[#out.errors + 1] = string.format("%s must be at most %s", path, tostring(schema.maximum))
			end
		end

		if wanted == "string" and schema.maxLength and #value > schema.maxLength then
			out.errors[#out.errors + 1] = string.format("%s is longer than %d characters", path, schema.maxLength)
		end

		if actual == "object" and type(schema.properties) == "table" then
			for _, key in ipairs(schema.required or {}) do
				if value[key] == nil then
					out.errors[#out.errors + 1] = string.format("%s is required", path .. "." .. key)
				end
			end
			for key, child in pairs(schema.properties) do
				if value[key] ~= nil then
					value[key] = checkValue(child, value[key], path .. "." .. key, out)
				end
			end
		end

		if actual == "array" and type(schema.items) == "table" then
			for index, item in ipairs(value) do
				value[index] = checkValue(schema.items, item, string.format("%s[%d]", path, index), out)
			end
		end

		return value
	end

	-- Returns coerced, errors, notes. The caller decides whether a non-empty error
	-- list is fatal; for a tool call it is, and the message goes back to the model
	-- as a tool error so it can correct itself on the next turn.
	function M.validate(schema, value)
		local out = { errors = {}, coercions = {} }
		local coerced = checkValue(schema or {}, value, "arguments", out)
		return coerced, out.errors, out.coercions
	end

	-- Human-readable parameter list, for the tools panel.
	function M.describe(schema)
		if type(schema) ~= "table" or type(schema.properties) ~= "table" then return "no parameters" end
		-- A schema marked as an intentionally empty object has no fields; the marker
		-- is a wire-encoding detail and must not be rendered as one.
		if util.isEmptyObject(schema.properties) then return "no parameters" end
		local required = {}
		for _, key in ipairs(schema.required or {}) do required[key] = true end
		local parts = {}
		for _, key in ipairs(util.keys(schema.properties, true)) do
			local field = schema.properties[key]
			parts[#parts + 1] = string.format("%s%s: %s", key, required[key] and "" or "?",
				(type(field) == "table" and field.type) or "any")
		end
		if #parts == 0 then return "no parameters" end
		return table.concat(parts, ", ")
	end

	return M
end
end)()

-- ==========================================================================
-- agent/session
-- ==========================================================================
__UAI_MODULES["agent/session"] = (function()
-- Sessions: the object the interface talks to, and the thread list behind it.
--
-- A session owns a conversation, an event stream and a busy flag. The loop is a
-- pure function over a session, so a subagent is just another session with a
-- smaller tool set and no interface attached -- which is why this module, not the
-- loop, is where threads and persistence live.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local clock = env.require("runtime/clock")
	local fsx = env.require("runtime/fsx")
	local log = env.require("runtime/log")
	local signal = env.require("runtime/signal")
	local context = env.require("agent/context")
	local hooks = env.require("agent/hooks")
	local permissions = env.require("agent/permissions")
	local state = env.require("agent/state")

	local THREAD_DIR = "sessions"
	local THREAD_LIMIT = 20

	local M = {
		threads = {},
		activeId = nil,
		listChanged = signal.new("threads"),
	}

	function M.create(opts)
		opts = opts or {}
		local session = {
			id = opts.id or util.uid("s"),
			title = opts.title or "New chat",
			ctx = context.new(),
			events = signal.new("session"),
			status = "Ready",
			busy = false,
			depth = opts.depth or 0,
			maxTurns = opts.maxTurns,
			toolFilter = opts.toolFilter,
			toolGroups = opts.toolGroups,
			budgetSeconds = opts.budgetSeconds,
			stream = opts.stream,
			headless = opts.headless == true,
			createdAt = clock.ms(),
			updatedAt = clock.ms(),
			turns = 0,
			abortFlag = false,
			log = {},
		}

		-- Every event is mirrored into a bounded per-session log so a panel opened
		-- mid-turn can render what it missed, and so the transcript survives a
		-- switch away and back.
		function session.emit(kind, payload)
			payload = payload or {}
			payload.kind = kind
			payload.at = clock.ms()
			session.updatedAt = payload.at
			if kind == "status" then session.status = payload.text or session.status end
			if not session.headless then
				session.log[#session.log + 1] = payload
				if #session.log > 400 then table.remove(session.log, 1) end
			end
			hooks.run("onEvent", { session = session, event = payload })
			session.events:fire(payload)
		end

		function session.aborted()
			return session.abortFlag == true
		end

		function session.toolContext()
			return {
				env = env,
				session = session,
				depth = session.depth,
				emit = function(kind, text)
					session.emit(kind, type(text) == "table" and text or { text = text })
				end,
				progress = function(text)
					session.emit("tool:progress", { text = tostring(text) })
				end,
				aborted = session.aborted,
			}
		end

		-- Runs on its own thread so the interface stays responsive, and guards
		-- against re-entry: two prompts in flight would interleave tool results
		-- into one transcript.
		function session.send(text, onDone)
			local clean = util.trim(text)
			if clean == "" then return false, "nothing to send" end
			if session.busy then return false, "already working" end

			session.busy = true
			session.abortFlag = false
			session.turns = session.turns + 1
			if session.title == "New chat" then
				session.title = util.ellipsis(clean, 42)
				M.listChanged:fire()
			end
			session.emit("user", { text = clean })

			task.spawn(function()
				local loop = env.require("agent/loop")
				local ok, reply = pcall(loop.run, session, clean)
				session.busy = false
				permissions.denyAll()
				if not ok then
					log.error("session", "loop crashed", reply)
					session.emit("error", { message = "Internal error: " .. tostring(reply), fatal = true })
					session.emit("status", { text = "Ready" })
					reply = "Something went wrong inside the agent: " .. tostring(reply)
				end
				M.persist(session)
				if onDone then pcall(onDone, reply) end
			end)
			return true
		end

		function session.abort()
			if not session.busy then return false end
			session.abortFlag = true
			session.emit("status", { text = "Stopping" })
			permissions.denyAll("aborted")
			return true
		end

		function session.clear()
			session.ctx.clear()
			session.log = {}
			session.turns = 0
			session.title = "New chat"
			session.emit("cleared", {})
			session.emit("status", { text = "Ready" })
			M.persist(session)
		end

		function session.stats()
			local stats = session.ctx.stats()
			stats.busy = session.busy
			stats.turns = session.turns
			stats.todos = state.todoCounts()
			return stats
		end

		return session
	end

	-- Threads ---------------------------------------------------------------

	function M.current()
		if M.activeId and M.threads[M.activeId] then return M.threads[M.activeId] end
		return M.newThread()
	end

	function M.newThread(opts)
		local session = M.create(opts)
		M.threads[session.id] = session
		M.activeId = session.id
		M.trimThreads()
		M.listChanged:fire()
		return session
	end

	function M.switch(id)
		if not M.threads[id] then return false end
		M.activeId = id
		M.listChanged:fire()
		return true
	end

	function M.list()
		local out = {}
		for _, session in pairs(M.threads) do out[#out + 1] = session end
		table.sort(out, function(a, b) return (a.updatedAt or 0) > (b.updatedAt or 0) end)
		return out
	end

	function M.remove(id)
		local session = M.threads[id]
		if not session then return false end
		if session.busy then session.abort() end
		M.threads[id] = nil
		if fsx.enabled then fsx.delete(THREAD_DIR .. "/" .. id .. ".json") end
		if M.activeId == id then
			local remaining = M.list()
			M.activeId = remaining[1] and remaining[1].id or nil
			if not M.activeId then M.newThread() end
		end
		M.listChanged:fire()
		return true
	end

	function M.trimThreads()
		local ordered = M.list()
		for index = THREAD_LIMIT + 1, #ordered do
			local victim = ordered[index]
			if not victim.busy and victim.id ~= M.activeId then M.remove(victim.id) end
		end
	end

	-- Persistence is best-effort by design: a host with no filesystem simply keeps
	-- everything in memory for the session, and nothing above here cares.
	function M.persist(session)
		if not fsx.enabled or session.headless then return false end
		if session.depth and session.depth > 0 then return false end
		return fsx.writeJson(THREAD_DIR .. "/" .. session.id .. ".json", {
			id = session.id,
			title = session.title,
			updatedAt = session.updatedAt,
			createdAt = session.createdAt,
			turns = session.turns,
			context = session.ctx.serialise(),
		})
	end

	function M.restore()
		if not fsx.enabled then return 0 end
		local restored = 0
		for _, entry in ipairs(fsx.list(THREAD_DIR)) do
			if entry.name:match("%.json$") then
				local data = fsx.readJson(entry.path, nil)
				if type(data) == "table" and data.id then
					local session = M.create({ id = data.id, title = data.title })
					session.createdAt = data.createdAt or session.createdAt
					session.updatedAt = data.updatedAt or session.updatedAt
					session.turns = data.turns or 0
					session.ctx.restore(data.context)
					M.threads[session.id] = session
					restored = restored + 1
				end
			end
		end
		if restored > 0 then
			local ordered = M.list()
			M.activeId = ordered[1] and ordered[1].id or nil
			log.info("session", util.pluralise(restored, "conversation") .. " restored")
			M.listChanged:fire()
		end
		return restored
	end

	return M
end
end)()

-- ==========================================================================
-- agent/state
-- ==========================================================================
__UAI_MODULES["agent/state"] = (function()
-- Agent-owned state that outlives a single turn: the task list the model keeps,
-- and the memory it writes to.
--
-- Both are model-writable, which is the point -- a long task survives context
-- compaction because the plan is not in the transcript -- and both are bounded,
-- because a model given an unbounded store will fill it.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local clock = env.require("runtime/clock")
	local signal = env.require("runtime/signal")

	local TODO_LIMIT = 24
	local MEMORY_LIMIT = 60
	local MEMORY_VALUE_CAP = 600

	local M = {
		todos = {},
		todosChanged = signal.new("todos"),
		memoryChanged = signal.new("memory"),
	}

	-- Todos -----------------------------------------------------------------

	local STATUS = { pending = true, active = true, done = true, dropped = true }

	-- The whole list is replaced rather than patched. A model that edits one item
	-- at a time drifts out of sync with its own plan; handing back the full list
	-- every time keeps the transcript and the panel identical.
	function M.setTodos(items)
		local out = {}
		for index, item in ipairs(items or {}) do
			if index > TODO_LIMIT then break end
			local text = util.trim(type(item) == "table" and (item.text or item.title) or item)
			if text ~= "" then
				local status = type(item) == "table" and tostring(item.status or "pending"):lower() or "pending"
				if not STATUS[status] then status = "pending" end
				out[#out + 1] = {
					id = index,
					text = util.ellipsis(text, 160),
					status = status,
					note = type(item) == "table" and item.note or nil,
				}
			end
		end
		M.todos = out
		M.todosChanged:fire(out)
		return out
	end

	function M.todoCounts()
		local counts = { pending = 0, active = 0, done = 0, dropped = 0, total = #M.todos }
		for _, item in ipairs(M.todos) do
			counts[item.status] = (counts[item.status] or 0) + 1
		end
		return counts
	end

	function M.clearTodos()
		M.todos = {}
		M.todosChanged:fire({})
	end

	-- Rendered into the system prompt each turn so the plan cannot be forgotten,
	-- and into the transcript panel for the user.
	function M.todoBlock()
		if #M.todos == 0 then return nil end
		local marks = { pending = "[ ]", active = "[>]", done = "[x]", dropped = "[-]" }
		local lines = {}
		for _, item in ipairs(M.todos) do
			lines[#lines + 1] = string.format("%s %s", marks[item.status] or "[ ]", item.text)
		end
		return table.concat(lines, "\n")
	end

	-- Memory ----------------------------------------------------------------

	local function entries()
		local stored = config.get("memory.entries", {})
		if type(stored) ~= "table" then return {} end
		return stored
	end

	function M.memoryEnabled()
		return config.get("memory.enabled", true) ~= false
	end

	function M.remember(key, value)
		local cleanKey = util.trim(key):gsub("%s+", "_")
		if cleanKey == "" then return false, "a memory needs a key" end
		if not M.memoryEnabled() then return false, "memory is disabled in settings" end
		local list = entries()
		local text = util.ellipsis(util.trim(value), MEMORY_VALUE_CAP)
		if text == "" then return false, "a memory needs a value" end

		local replaced = false
		for _, entry in ipairs(list) do
			if entry.key == cleanKey then
				entry.value = text
				entry.at = clock.ms()
				replaced = true
			end
		end
		if not replaced then
			if #list >= MEMORY_LIMIT then
				-- Oldest out. A model that keeps writing should lose its earliest
				-- notes rather than start failing.
				table.sort(list, function(a, b) return (a.at or 0) < (b.at or 0) end)
				table.remove(list, 1)
			end
			list[#list + 1] = { key = cleanKey, value = text, at = clock.ms() }
		end
		config.set("memory.entries", list)
		M.memoryChanged:fire(list)
		return true, (replaced and "updated " or "saved ") .. cleanKey
	end

	function M.recall(key)
		for _, entry in ipairs(entries()) do
			if entry.key == util.trim(key) then return entry.value end
		end
		return nil
	end

	function M.forget(key)
		local list = entries()
		local kept = {}
		local removed = 0
		for _, entry in ipairs(list) do
			if entry.key == util.trim(key) then
				removed = removed + 1
			else
				kept[#kept + 1] = entry
			end
		end
		config.set("memory.entries", kept)
		M.memoryChanged:fire(kept)
		return removed > 0
	end

	function M.memoryList()
		local list = entries()
		table.sort(list, function(a, b) return tostring(a.key) < tostring(b.key) end)
		return list
	end

	function M.clearMemory()
		config.set("memory.entries", {})
		M.memoryChanged:fire({})
	end

	function M.memoryBlock()
		if not M.memoryEnabled() then return nil end
		local list = M.memoryList()
		if #list == 0 then return nil end
		local lines = {}
		for _, entry in ipairs(list) do
			lines[#lines + 1] = "- " .. entry.key .. ": " .. entry.value
		end
		return table.concat(lines, "\n")
	end

	return M
end
end)()

-- ==========================================================================
-- agent/subagent
-- ==========================================================================
__UAI_MODULES["agent/subagent"] = (function()
-- Subagent dispatch.
--
-- A subagent is a full session with a smaller tool set, its own context and no
-- interface. It exists to keep long or repetitive work out of the main
-- conversation: the parent pays for one paragraph of report instead of forty tool
-- results, and a search that goes nowhere costs the main context nothing.
--
-- Depth is capped because a subagent that can spawn subagents indefinitely is a
-- fork bomb with a token bill.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local clock = env.require("runtime/clock")
	local log = env.require("runtime/log")
	local prompt = env.require("agent/prompt")
	local session = env.require("agent/session")

	local M = {}

	-- Groups a subagent may be given. Anything that changes the world is absent
	-- from the read-only preset, which is the default: the point of a subagent is
	-- usually to go and find out, and a delegated write is hard for the user to
	-- attribute afterwards.
	M.PRESETS = {
		read = { instance = true, world = true, players = true, perf = true, meta = true, web = true, net = true, fs = true },
		web = { web = true, net = true },
		game = { instance = true, world = true, players = true, gui = true, remotes = true, meta = true },
		full = nil,
	}

	function M.available(depth)
		local limit = config.get("agent.subagentDepth", 2)
		return (depth or 0) < limit
	end

	-- How long a subagent may run, and how long the tool that started it waits.
	--
	-- Both come from one number on purpose. They used to be independent: the child was
	-- given four minutes and the call that started it was bounded by the generic
	-- `agent.toolTimeout` of twenty-five seconds, so nearly every dispatch was reported
	-- to the model as "did not finish within 25s and was left running in the
	-- background" -- and it was, against a caller that had stopped listening. The
	-- report arrived a minute later with nowhere to go, and the model, asked what its
	-- subagents found, could only say it never heard back.
	--
	-- The slack covers one request. A child notices its own deadline between steps, so
	-- it returns a moment after the budget expires rather than exactly on it, and the
	-- tool has to still be there to take the answer.
	local SLACK_SECONDS = 60

	function M.budgetSeconds()
		return math.max(tonumber(config.get("agent.subagentBudget", 240)) or 240, 15)
	end

	function M.toolTimeout()
		return M.budgetSeconds() + SLACK_SECONDS
	end

	-- The card in the transcript is titled with the task, so the first line of it is
	-- what the user reads to tell three concurrent subagents apart.
	local function labelFor(task)
		local first = tostring(task):match("^%s*([^\n]*)") or ""
		first = util.trim(first)
		if first == "" then first = "task" end
		return util.ellipsis(first, 64)
	end

	-- Blocks until the subagent finishes. The caller is already on a tool thread, so
	-- yielding here is correct; the tool timeout above it comes from M.toolTimeout so
	-- it outlasts the child rather than the other way round, and `turns` bounds the
	-- token spend.
	function M.dispatch(opts)
		local parent = opts.parent
		local depth = (parent and parent.depth or 0) + 1

		if not M.available(depth - 1) then
			return nil, "subagent depth limit reached (" .. tostring(config.get("agent.subagentDepth", 2)) .. ")"
		end

		local task_text = util.trim(opts.task)
		if task_text == "" then return nil, "a subagent needs a task" end

		local id = util.uid("agent")
		local label = labelFor(task_text)
		local groups = M.PRESETS[opts.preset or "read"]
		local child = session.create({
			title = "subagent",
			depth = depth,
			headless = true,
			maxTurns = opts.turns or config.get("agent.subagentTurns", 14),
			toolGroups = groups,
			budgetSeconds = opts.budgetSeconds or M.budgetSeconds(),
			stream = false,
		})

		-- Live view.
		--
		-- The transcript renders the parent's event stream and nothing else, so a
		-- subagent that wants to be watched has to speak through it. Every event carries
		-- the child's id, which keys the card, and the id of the tool call that started
		-- it, which tells the view what to nest the card under.
		--
		-- Tool RESULTS are summarised to one line rather than forwarded: absorbing that
		-- volume is the entire point of a subagent, and the parent's log is bounded. What
		-- does go across is names, outcomes and timings, because that is the difference
		-- between watching work happen and watching a spinner.
		local function announce(kind, payload)
			if not parent then return end
			payload = payload or {}
			payload.id = id
			payload.call = opts.callId
			payload.label = label
			parent.emit(kind, payload)
		end

		if parent then
			-- Stop has to reach the child. Without this, aborting the turn left every
			-- dispatched subagent running out its full budget against a conversation
			-- that had already moved on -- billed, invisible, and unstoppable.
			local parentAborted = parent.aborted
			child.aborted = function()
				return child.abortFlag == true or parentAborted() == true
			end

			local calls = 0
			child.events:connect(function(event)
				if event.kind == "tool:call" then
					calls = calls + 1
					announce("subagent:tool", {
						callId = event.id,
						name = event.name,
						risk = event.risk,
						arguments = util.ellipsis(tostring(event.arguments or ""):gsub("%s+", " "), 160),
						index = calls,
					})
				elseif event.kind == "tool:result" or event.kind == "tool:error" then
					announce("subagent:tool:done", {
						callId = event.id,
						name = event.name,
						ok = event.kind == "tool:result",
						ms = event.ms,
						summary = util.ellipsis(tostring(event.text or ""):gsub("%s+", " "), 140),
					})
				elseif event.kind == "assistant:text" then
					if util.trim(tostring(event.text or "")) ~= "" then
						announce("subagent:text", { text = util.ellipsis(util.trim(event.text), 400) })
					end
				elseif event.kind == "status" then
					-- "Ready" is the child's own idle text and means nothing on a card that
					-- reports its finish separately. Dropping it here rather than in the
					-- view keeps one entry per turn out of the parent's bounded log.
					if tostring(event.text) ~= "Ready" then
						announce("subagent:status", { text = tostring(event.text) })
					end
				elseif event.kind == "error" then
					announce("subagent:status", { text = tostring(event.message), bad = true })
				elseif event.kind == "permission:ask" then
					-- Nothing is subscribed to a headless session, so a prompt raised
					-- inside a subagent has to surface on the parent's stream or it
					-- would sit unanswered until its own deadline.
					parent.emit("permission:ask", event)
				end
			end)
		end

		local started = clock.ms()
		local loop = env.require("agent/loop")

		-- The brief replaces the main system prompt rather than appending to it.
		-- Carrying it on the session (instead of swapping the prompt module's
		-- builder) is what makes two subagents dispatched in the same batch safe.
		child.systemPrompt = prompt.subagent(task_text, { extra = opts.extra })

		announce("subagent:start", {
			task = util.ellipsis(task_text, 400),
			preset = opts.preset or "read",
			turns = child.maxTurns,
			budget = child.budgetSeconds,
			depth = depth,
		})

		local ok, reply = pcall(loop.run, child, task_text)

		local elapsed = clock.since(started)
		if not ok then
			log.warn("subagent", "failed", reply)
			local note = "the subagent failed: " .. util.ellipsis(tostring(reply), 200)
			announce("subagent:done", { ms = elapsed, ok = false, text = note })
			return nil, note
		end

		local stats = child.ctx.stats()
		local aborted = child.aborted() == true
		log.info("subagent", string.format("finished in %s over %d messages%s",
			util.formatDuration(elapsed), stats.messages, aborted and " (stopped)" or ""))

		announce("subagent:done", {
			ms = elapsed,
			ok = not aborted,
			aborted = aborted,
			messages = stats.messages,
			turns = stats.turns,
			text = util.ellipsis(tostring(reply), 600),
		})

		return {
			text = tostring(reply),
			ms = elapsed,
			messages = stats.messages,
			turns = stats.turns,
			aborted = aborted,
		}
	end

	return M
end
end)()

-- ==========================================================================
-- agent/usage
-- ==========================================================================
__UAI_MODULES["agent/usage"] = (function()
-- Token and cost accounting.
--
-- Providers report usage inconsistently -- some only in a streamed final chunk,
-- some not at all -- so counts are taken from the response when present and
-- estimated when not, and an estimated figure is always labelled as one. Prices
-- are a convenience, not an invoice: they are per million tokens, they date from
-- when this was written, and the panel says so.
return function(env)
	local util = env.require("runtime/util")
	local signal = env.require("runtime/signal")

	local M = {
		session = { prompt = 0, completion = 0, total = 0, cost = 0, requests = 0, estimated = false },
		turn = { prompt = 0, completion = 0, total = 0, cost = 0 },
		changed = signal.new("usage"),
	}

	-- input, output per million tokens. Matched longest-prefix, so a dated model
	-- id still resolves.
	--
	-- The current Claude generations are listed individually because the family
	-- names no longer predict the price: an Opus has cost $5/$25 since 4.6, a third
	-- of what the 4.5-and-earlier line did, and reporting the old number made every
	-- turn in this client look three times more expensive than it was.
	local PRICES = {
		["gpt-4o-mini"] = { 0.15, 0.60 },
		["gpt-4o"] = { 2.50, 10.00 },
		["gpt-4.1-mini"] = { 0.40, 1.60 },
		["gpt-4.1"] = { 2.00, 8.00 },
		["o4-mini"] = { 1.10, 4.40 },
		["claude-haiku"] = { 1.00, 5.00 },
		["claude-sonnet"] = { 3.00, 15.00 },
		["claude-sonnet-5"] = { 2.00, 10.00 },
		["claude-opus"] = { 15.00, 75.00 },
		["claude-opus-4-6"] = { 5.00, 25.00 },
		["claude-opus-4-7"] = { 5.00, 25.00 },
		["claude-opus-4-8"] = { 5.00, 25.00 },
		["claude-opus-5"] = { 5.00, 25.00 },
		-- Covers the .1 revisions too: the id is a superstring of this prefix.
		["claude-fable-5"] = { 10.00, 50.00 },
		["claude-mythos-5"] = { 10.00, 50.00 },
		["deepseek-reasoner"] = { 0.55, 2.19 },
		["deepseek-chat"] = { 0.27, 1.10 },
		["llama-3.3-70b"] = { 0.59, 0.79 },
		["llama-3.1-8b"] = { 0.05, 0.08 },
		["mistral-large"] = { 2.00, 6.00 },
		["mistral-small"] = { 0.20, 0.60 },
		["grok-4"] = { 3.00, 15.00 },
		["grok-3-mini"] = { 0.30, 0.50 },
		["qwen"] = { 0.40, 0.80 },
		["gemini-2.5-flash"] = { 0.30, 2.50 },
	}

	function M.priceFor(model)
		local id = tostring(model or ""):lower()
		local best, bestLength = nil, 0
		for prefix, price in pairs(PRICES) do
			if id:find(prefix, 1, true) and #prefix > bestLength then
				best, bestLength = price, #prefix
			end
		end
		return best
	end

	-- Four characters per token is the usual English approximation; it is within
	-- about ten percent for prose and pessimistic for code, which is the right
	-- direction for a context budget.
	function M.estimateText(text)
		if type(text) ~= "string" then return 0 end
		return math.ceil(#text / 4)
	end

	function M.estimateMessages(messages)
		local total = 0
		for _, message in ipairs(messages or {}) do
			-- Per-message framing overhead, plus the role name.
			total = total + 4 + M.estimateText(message.content)
			-- Internal messages carry toolCalls; wire messages carry tool_calls, and
			-- the loop estimates over the wire form.
			for _, call in ipairs(message.toolCalls or message.tool_calls or {}) do
				local fn = call["function"] or {}
				total = total + 8 + M.estimateText(fn.name) + M.estimateText(fn.arguments)
			end
		end
		return total
	end

	function M.startTurn()
		M.turn = { prompt = 0, completion = 0, total = 0, cost = 0 }
	end

	-- `usage` is the provider block when it exists. `fallback` supplies estimates
	-- so a provider that reports nothing still moves the counters.
	function M.record(usage, model, fallback)
		local prompt, completion, estimated
		if type(usage) == "table" and (usage.prompt_tokens or usage.completion_tokens) then
			prompt = tonumber(usage.prompt_tokens) or 0
			completion = tonumber(usage.completion_tokens) or 0
			estimated = false
		else
			prompt = (fallback and fallback.prompt) or 0
			completion = (fallback and fallback.completion) or 0
			estimated = true
		end

		local price = M.priceFor(model)
		local cost = 0
		if price then
			cost = (prompt / 1000000) * price[1] + (completion / 1000000) * price[2]
		end

		M.turn.prompt = M.turn.prompt + prompt
		M.turn.completion = M.turn.completion + completion
		M.turn.total = M.turn.prompt + M.turn.completion
		M.turn.cost = M.turn.cost + cost

		M.session.prompt = M.session.prompt + prompt
		M.session.completion = M.session.completion + completion
		M.session.total = M.session.prompt + M.session.completion
		M.session.cost = M.session.cost + cost
		M.session.requests = M.session.requests + 1
		if estimated then M.session.estimated = true end

		local cached = util.get(usage or {}, "prompt_tokens_details.cached_tokens", 0)
		local reasoning = util.get(usage or {}, "completion_tokens_details.reasoning_tokens", 0)
		M.session.cached = (M.session.cached or 0) + (tonumber(cached) or 0)
		M.session.reasoning = (M.session.reasoning or 0) + (tonumber(reasoning) or 0)

		M.changed:fire(M.session, M.turn)
		return { prompt = prompt, completion = completion, cost = cost, estimated = estimated }
	end

	function M.reset()
		M.session = { prompt = 0, completion = 0, total = 0, cost = 0, requests = 0, estimated = false }
		M.turn = { prompt = 0, completion = 0, total = 0, cost = 0 }
		M.changed:fire(M.session, M.turn)
	end

	function M.formatCost(value)
		if value <= 0 then return "" end
		if value < 0.01 then return string.format("$%.4f", value) end
		return string.format("$%.3f", value)
	end

	function M.line()
		local parts = {
			util.formatNumber(M.session.total) .. " tokens",
			util.formatNumber(M.session.prompt) .. " in",
			util.formatNumber(M.session.completion) .. " out",
		}
		local cost = M.formatCost(M.session.cost)
		if cost ~= "" then parts[#parts + 1] = cost .. (M.session.estimated and " est." or "") end
		return table.concat(parts, "  ")
	end

	return M
end
end)()

-- ==========================================================================
-- net/http
-- ==========================================================================
__UAI_MODULES["net/http"] = (function()
-- The only module that performs an HTTP request.
--
-- Centralising it buys three things the client depends on: the Claude Code
-- identity cannot be omitted by a forgetful caller, every request lands in one
-- redacted history the Logs panel reads, and retry policy is written once rather
-- than per call site.
return function(env)
	local util = env.require("runtime/util")
	local caps = env.require("runtime/caps")
	local clock = env.require("runtime/clock")
	local log = env.require("runtime/log")
	local ua = env.require("net/ua")
	local signal = env.require("runtime/signal")

	local HISTORY_LIMIT = 60

	-- A browser agent for the public web: search engines and CDNs answer 403 to
	-- anything else, so the web tools opt into this explicitly. Everything else,
	-- inference included, carries the Claude Code identity.
	local BROWSER_UA = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36"

	-- Statuses that are always worth another attempt, regardless of what the body
	-- says. Everything in 5xx joins them by range below.
	local RETRY_STATUS = {
		[408] = true, [409] = true, [425] = true, [429] = true, [499] = true,
	}

	-- How long an attempt has to run before "nothing came back" reads as a deadline
	-- rather than a decision, in milliseconds.
	--
	-- A refusal arrives in milliseconds: an edge filter and an exhausted quota both
	-- answer immediately. Only a transport that ran out of time takes tens of seconds
	-- to produce nothing at all, and by then the gateway has accepted the request and
	-- billed the whole prompt. Retrying that re-sends every token to arrive at the same
	-- wall, so above this an empty answer ends the sequence instead of extending it.
	local DEADLINE_FLOOR = 10000

	-- Substrings that mean "transient", wherever they appear in a response body.
	--
	-- These gateways report an overloaded or rate-limited upstream in the body and
	-- pick the status code almost at random, so the text is the more reliable signal.
	-- The list is taken from the reference proxy that sits in front of them, which
	-- sees the upstream errors this client only ever sees second-hand -- including the
	-- Chinese quota wording, which arrives under a 403.
	local TRANSIENT_MARKERS = {
		"rate_limit", "chatratelimited",
		"upstream_provider_rate_limit", "server_is_overloaded",
		"service_unavailable_error", "server_error", "overloaded_error",
		"internal_server_error", "temporarily unavailable", "please try again",
		"用户额度不足", "剩余额度",
	}

	local function transient(body)
		if type(body) ~= "string" or body == "" then return false end
		local lowered = body:lower()
		for _, marker in ipairs(TRANSIENT_MARKERS) do
			if lowered:find(marker, 1, true) then return true end
		end
		return false
	end

	-- A gateway that answers 200 and then puts the failure in the body. Detected
	-- structurally -- a decodable object carrying an `error`, or an SSE frame whose
	-- type is "error" -- and never by substring, because a reply that happens to
	-- discuss rate limits must not be mistaken for one.
	local function errorPayload(body)
		if type(body) ~= "string" or body == "" then return nil end
		local function check(text)
			local decoded = util.decode(text)
			if type(decoded) ~= "table" then return nil end
			if decoded.type == "error" then return decoded end
			if decoded.error ~= nil then return decoded end
			return nil
		end
		local direct = check(body)
		if direct then return direct end
		for line in body:gmatch("[^\r\n]+") do
			local data = line:match("^data:%s*(.+)$")
			if data and data ~= "[DONE]" then
				local hit = check(data)
				if hit then return hit end
			end
		end
		return nil
	end

	local M = {
		history = {},
		changed = signal.new("http"),
		count = 0,
	}

	function M.header(res, name)
		local headers = res and res.headers
		if type(headers) ~= "table" then return nil end
		local wanted = tostring(name):lower()
		for key, value in pairs(headers) do
			if type(key) == "string" and key:lower() == wanted then
				-- Some transports hand back a list of values for one header.
				if type(value) == "table" then return value[1] end
				return value
			end
		end
		return nil
	end

	local function record(entry)
		M.count = M.count + 1
		entry.id = M.count
		M.history[#M.history + 1] = entry
		if #M.history > HISTORY_LIMIT then table.remove(M.history, 1) end
		M.changed:fire(entry)
		return entry
	end

	local function identityHeaders(kind, attempt, timeout)
		if kind == "none" then return {} end
		if kind == "browser" then
			return {
				["User-Agent"] = BROWSER_UA,
				["Accept"] = "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
				["Accept-Language"] = "en-US,en;q=0.9",
			}
		end
		if not ua.enabled() then return {} end
		return ua.headers({ attempt = attempt, timeout = timeout })
	end

	-- Header merge order: identity first, then the caller's, so a caller can
	-- deliberately override one value without losing the rest of the set.
	local function buildHeaders(spec, attempt)
		local headers = identityHeaders(spec.identity or "claude", attempt, spec.timeout)
		for key, value in pairs(spec.headers or {}) do
			if value ~= nil then headers[key] = tostring(value) end
		end
		if spec.body and not headers["Content-Type"] and not headers["content-type"] then
			headers["Content-Type"] = "application/json"
		end
		return headers
	end

	-- What a transport hands back when it never got an answer varies: some set
	-- Success = false, some invent a status code. What they share is that nothing came
	-- off the wire -- no body and no headers -- and a real HTTP reply always carries at
	-- least one header. Reporting that as a status writes a number into the log no
	-- server ever sent, and the retry policy then reasons about a refusal nobody
	-- issued: the gateway had already accepted the request and billed the prompt.
	local function normalise(res, via)
		local headers = res.Headers or res.ResponseHeaders or {}
		if type(headers) ~= "table" then headers = {} end
		local body = res.Body or res.ResponseData or ""
		if body == "" and next(headers) == nil then
			local said = util.trim(tostring(res.StatusMessage or ""))
			return nil, said ~= "" and said or "the transport returned no response"
		end
		return {
			status = tonumber(res.StatusCode or res.Status) or 0,
			body = body,
			headers = headers,
			message = res.StatusMessage,
			via = via,
		}
	end

	local function send(url, method, headers, body, timeout)
		local options = { Url = url, Method = method, Headers = headers }
		if body and body ~= "" and method ~= "GET" and method ~= "HEAD" then
			options.Body = body
		end

		if caps.fn.request then
			-- Set only on this path: RequestAsync accepts a fixed set of keys. Not every
			-- executor honours it either, which is why an attempt that runs long is also
			-- recognised after the fact rather than only prevented here.
			if timeout and timeout > 0 then options.Timeout = math.floor(timeout) end
			local ok, res = pcall(caps.fn.request, options)
			if not ok then return nil, tostring(res) end
			if type(res) ~= "table" then return nil, "empty executor response" end
			return normalise(res, "executor")
		end

		if caps.http == "none" then return nil, caps.reason("http") end
		local ok, res = pcall(function() return env.hs:RequestAsync(options) end)
		if not ok then return nil, tostring(res) end
		if type(res) ~= "table" then return nil, "empty HttpService response" end
		return normalise(res, "roblox")
	end

	-- One attempt. Returns res (with .ok) or nil plus a transport error string.
	function M.request(spec)
		local url = tostring(spec.url or "")
		if url == "" then return nil, "no url" end
		local method = (spec.method or "GET"):upper()
		local attempt = spec.attempt or 1
		local headers = buildHeaders(spec, attempt)
		local started = clock.ms()

		local res, err = send(url, method, headers, spec.body, spec.timeout)
		local elapsed = clock.since(started)

		local entry = record({
			at = started,
			stamp = clock.stamp(),
			method = method,
			url = log.redact(url),
			tag = spec.tag or "http",
			ms = elapsed,
			status = res and res.status or 0,
			bytes = res and #tostring(res.body or "") or 0,
			via = res and res.via or (caps.fn.request and "executor" or "roblox"),
			identity = spec.identity or "claude",
			uaSent = (spec.identity ~= "none") and caps.uaSupported or false,
			error = err,
			attempt = attempt,
			-- A refusal with an empty body cannot be diagnosed from a status code
			-- alone, and until now nothing about the response was kept at all. These
			-- four are what distinguish an API decision from an edge filter: a
			-- Cloudflare 403 carries `server` and `cf-ray` and usually `cf-mitigated`,
			-- and the API's own 403 carries a JSON body. Kept short -- this is what the
			-- Requests view shows, not an archive.
			response = res and util.ellipsis(res.body, 400) or nil,
			server = res and M.header(res, "server") or nil,
			trace = res and (M.header(res, "cf-ray") or M.header(res, "x-request-id")) or nil,
			mitigated = res and M.header(res, "cf-mitigated") or nil,
		})

		if not res then
			-- How long it ran is the whole diagnosis: a transport that refuses fails at
			-- once, one that ran out of time fails slowly, and only the second is a
			-- deadline. The caller needs the number to tell them apart.
			log.warn("http", string.format("%s %s failed after %s", method, entry.url,
				util.formatDuration(elapsed)), err)
			return nil, err or "request failed", elapsed
		end

		res.ms = elapsed
		res.ok = res.status >= 200 and res.status < 300
		res.entry = entry
		if not res.ok then
			log.warn("http", string.format("%s %s -> %d", method, entry.url, res.status),
				util.ellipsis(res.body, 240))
		else
			log.debug("http", string.format("%s %s -> %d in %s", method, entry.url, res.status,
				util.formatDuration(elapsed)))
		end
		return res
	end

	-- Retry-After is seconds or an HTTP date. Only the numeric form is honoured:
	-- parsing an RFC date to save a couple of seconds is not worth the code, and
	-- the backoff curve is a sane fallback.
	local function retryDelay(res, attempt, opts)
		if res then
			local header = M.header(res, "retry-after")
			local seconds = tonumber(header)
			if seconds and seconds > 0 then return math.min(seconds, 60), "retry-after" end
		end
		return clock.backoff(attempt, opts), "backoff"
	end

	-- Whether an attempt is worth repeating, and why -- the reason is reported to the
	-- transcript so a slow turn explains itself rather than just being slow. `info`
	-- carries what the response cannot: how long the attempt took, which is the only
	-- way to tell a refusal apart from a deadline when neither carries a body.
	function M.shouldRetry(res, err, info)
		local elapsed = tonumber(info and info.elapsed) or 0
		local status = res and res.status or 0
		local body = tostring(res and res.body or "")

		-- An attempt that ran this long and returned nothing hit a deadline, whatever
		-- status was attached to it -- most often none at all, because the transport gave
		-- up rather than the server answering. The next attempt re-sends the entire
		-- prompt to reach the same wall, and the gateway bills it on arrival, so the
		-- sequence ends here and says why instead of paying three times over.
		--
		-- Retry-After is the exception, and the only one: a server naming a moment to
		-- come back has told us the request will work later, which is precisely what a
		-- deadline cannot promise.
		local told = res and tonumber(M.header(res, "retry-after"))
		if elapsed >= DEADLINE_FLOOR and util.trim(body) == "" and not told then
			return false, string.format("nothing returned after %s", util.formatDuration(elapsed))
		end

		-- The transport itself failed. Nothing was decided upstream, so try again.
		if err then return true, "transport error" end
		if not res then return true, "no response" end

		if RETRY_STATUS[status] then return true, "status " .. tostring(status) end
		if status >= 500 and status <= 599 then return true, "status " .. tostring(status) end

		-- A 403 from these gateways is usually an edge filter or an exhausted shared
		-- quota pool rather than a decision about this key: in the log that prompted
		-- this they arrive interleaved with 200s on the same endpoint, seconds apart.
		-- A genuine permission refusal explains itself in the body, so one that
		-- explains nothing gets another attempt and one that does is reported.
		if status == 403 then
			if util.trim(body) == "" then return true, "403 with no explanation" end
			if transient(body) then return true, "403, upstream busy" end
			return false
		end

		if res.ok then
			local payload = errorPayload(body)
			if payload then
				local text = type(payload.error) == "table" and tostring(payload.error.message or "")
					or tostring(payload.error or payload.message or "")
				if transient(text) or transient(body) then return true, "error inside a 200" end
			end
			return false
		end

		if transient(body) then return true, "upstream busy" end
		return false
	end

	-- Retries the whole attempt sequence. `spec.attempts` caps it; `spec.onRetry`
	-- lets the caller report the wait to the interface, and `spec.aborted` lets a
	-- user cancel during the sleep rather than after it.
	function M.send(spec)
		local attempts = math.max(spec.attempts or 1, 1)
		local lastRes, lastErr
		for attempt = 1, attempts do
			if spec.aborted and spec.aborted() then return nil, "aborted" end
			local copy = util.copy(spec)
			copy.attempt = attempt
			local res, err, failedMs = M.request(copy)
			lastRes, lastErr = res, err
			-- Asked before the success check, because a 200 can carry the failure in
			-- its body and returning that as a reply is worse than retrying it.
			local retry, why = M.shouldRetry(res, err, { elapsed = res and res.ms or failedMs })
			if not retry then
				-- A deadline is the one outcome the caller cannot read off the response,
				-- because there is no response to read. The transport's own words for it
				-- stay in the log entry rather than the message: they are usually a raise
				-- from inside the executor ("Argument 1 missing or nil") and say nothing
				-- a reader can act on, where the wait and its cause do.
				if why and not res then
					return nil, why .. " -- the transport gave up while the request was still " ..
						"running. A smaller context budget or reply ceiling fits inside it."
				end
				return res, err
			end
			if attempt >= attempts then return res, err end
			local wait, source = retryDelay(res, attempt, spec.backoff)
			if spec.onRetry then
				spec.onRetry({
					attempt = attempt,
					attempts = attempts,
					wait = wait,
					reason = why or source,
					status = res and res.status or 0,
					error = err,
				})
			end
			-- Slice the sleep so an abort lands promptly instead of after the full
			-- backoff, which at the top of the curve is twenty seconds.
			local slept = 0
			while slept < wait do
				if spec.aborted and spec.aborted() then return nil, "aborted" end
				local step = math.min(0.25, wait - slept)
				clock.wait(step)
				slept = slept + step
			end
		end
		return lastRes, lastErr
	end

	function M.json(spec)
		local res, err = M.send(spec)
		if not res then return nil, err, nil end
		local decoded, decodeErr = util.decode(res.body)
		if decoded == nil then return nil, decodeErr or "invalid json", res end
		return decoded, nil, res
	end

	function M.clearHistory()
		M.history = {}
		M.changed:fire(nil)
	end

	M.BROWSER_UA = BROWSER_UA

	return M
end
end)()

