				end
			end
		end
		return out
	end

	function M.clear()
		M.entries = {}
		M.changed:fire(nil)
	end

	function M.export()
		local lines = {}
		for _, entry in ipairs(M.entries) do
			lines[#lines + 1] = string.format("%s %-5s %-14s %s%s",
				entry.stamp, entry.level:upper(), entry.source, entry.message,
				entry.detail and ("  " .. entry.detail) or "")
		end
		return table.concat(lines, "\n")
	end

	return M
end
end)()

