__UAI_MODULES["tools/gui"] = (function()
-- On-screen interfaces: read them, press them, mark things up, and tell the user
-- something.
return function(env)
	local util = env.require("runtime/util")
	local caps = env.require("runtime/caps")
	local clock = env.require("runtime/clock")
	local H = env.require("tools/helpers")

	local function guiRoots()
		local roots = {}
		local playerGui = env.plr and env.plr:FindFirstChild("PlayerGui")
		if playerGui then roots[#roots + 1] = playerGui end
		local okCore, coreGui = pcall(function() return env.services.CoreGui end)
		if okCore and coreGui then roots[#roots + 1] = coreGui end
		return roots
	end

	return {
		{
			name = "gui_tree",
			risk = "read",
			description = "List the on-screen interfaces: every ScreenGui in PlayerGui and CoreGui, with whether it is enabled.",
			parameters = {
				type = "object",
				properties = {
					limit = { type = "integer", minimum = 1, maximum = 80 },
				},
				required = {},
			},
			run = function(args)
				local found = {}
				for _, root in ipairs(guiRoots()) do
					for _, child in ipairs(root:GetChildren()) do
						local ok, isGui = pcall(function() return child:IsA("LayerCollector") end)
						if ok and isGui then found[#found + 1] = child end
					end
				end
				if #found == 0 then return "No screen interfaces are present." end
				return string.format("%d interface(s):\n%s", #found,
					H.list(found, H.limit(args.limit, 40, 80), function(gui)
						local okCount, descendants = pcall(function() return #gui:GetDescendants() end)
						return string.format("%s [%s] %s, %s",
							H.pathOf(gui), gui.ClassName,
							gui.Enabled and "enabled" or "disabled",
							okCount and util.pluralise(descendants, "element") or "unknown size")
					end))
			end,
		},
		{
			name = "gui_text",
			risk = "read",
			description = "Read the visible text under a GUI element, in layout order. Use it to find out what is actually on screen.",
			parameters = {
				type = "object",
				properties = {
					path = { type = "string", description = "Dotted path to a ScreenGui or frame. Defaults to every screen interface." },
					limit = { type = "integer", minimum = 1, maximum = 120 },
				},
				required = {},
			},
			run = function(args)
				local targets = {}
				if args.path and util.trim(args.path) ~= "" then
					local instance, err = H.resolve(args.path)
					if not instance then return H.fail(err) end
					targets[1] = instance
				else
					targets = guiRoots()
				end

				local rows = {}
				for _, root in ipairs(targets) do
					local ok, descendants = pcall(function() return root:GetDescendants() end)
					if ok then
						for _, node in ipairs(descendants) do
							local okText, text = pcall(function() return node.Text end)
							if okText and type(text) == "string" and util.trim(text) ~= "" then
								local visible = true
								pcall(function() visible = node.Visible end)
								rows[#rows + 1] = {
									text = util.ellipsis(text, 90),
									path = H.pathOf(node),
									class = node.ClassName,
									visible = visible,
								}
							end
						end
					end
				end

				if #rows == 0 then return "No text elements found." end
				return string.format("%d text element(s):\n%s", #rows,
					H.list(rows, H.limit(args.limit, 50, 120), function(row)
						return string.format("%q %s[%s] %s", row.text,
							row.visible and "" or "(hidden) ", row.class, row.path)
					end))
			end,
		},
		{
			name = "gui_click",
			risk = "write",
			needs = { "hooks" },
			description = "Press a GUI button by firing the handlers connected to it. Needs a host that exposes signal introspection.",
			parameters = {
				type = "object",
				properties = {
					path = { type = "string", description = "Dotted path to a TextButton or ImageButton." },
					signal = {
						type = "string",
						enum = { "Activated", "MouseButton1Click", "MouseButton1Down" },
						description = "Which signal to fire. Default Activated, which most modern interfaces use.",
					},
				},
				required = { "path" },
			},
			run = function(args)
				local button, err = H.resolve(args.path)
				if not button then return H.fail(err) end
				local okA, isButton = pcall(function() return button:IsA("GuiButton") end)
				if not okA or not isButton then
					return H.fail(button.ClassName .. " is not a button")
				end

				local signalName = args.signal or "Activated"
				local okSignal, signal = pcall(function() return button[signalName] end)
				if not okSignal or not signal then return H.fail("no signal named " .. signalName) end

				local okConn, connections = pcall(caps.fn.getconnections, signal)
				if not okConn or type(connections) ~= "table" then
					return H.fail("could not read the connections on that signal")
				end
				if #connections == 0 then
					return string.format("%s has no %s handlers, so pressing it would do nothing.",
						H.pathOf(button), signalName)
				end

				local fired = 0
				for _, connection in ipairs(connections) do
					local okFire = pcall(function() connection:Fire() end)
					if okFire then fired = fired + 1 end
				end
				return string.format("Fired %d of %d %s handler(s) on %s",
					fired, #connections, signalName, H.pathOf(button))
			end,
		},
		{
			name = "click_detector_fire",
			risk = "danger",
			needs = { "hooks" },
			description = "Trigger a ClickDetector or a part's TouchInterest as if the player had interacted with it. This reaches the server.",
			parameters = {
				type = "object",
				properties = {
					path = { type = "string", description = "Path to the ClickDetector, or to a part containing one." },
					distance = { type = "number", description = "Reported click distance. Default 0." },
				},
				required = { "path" },
			},
			run = function(args)
				local instance, err = H.resolve(args.path)
				if not instance then return H.fail(err) end

				local detector = instance
				local okA, isDetector = pcall(function() return instance:IsA("ClickDetector") end)
				if not (okA and isDetector) then
					detector = instance:FindFirstChildOfClass("ClickDetector")
				end

				if detector and caps.fn.fireclickdetector then
					local ok, fireErr = pcall(caps.fn.fireclickdetector, detector, tonumber(args.distance) or 0)
					if not ok then return H.fail(tostring(fireErr)) end
					return "Clicked " .. H.pathOf(detector)
				end

				local prompt = instance:FindFirstChildOfClass("ProximityPrompt")
				if prompt then
					local ok = pcall(function() prompt:InputHoldBegin() end)
					if ok then
						clock.wait(math.min(prompt.HoldDuration or 0, 2) + 0.05)
						pcall(function() prompt:InputHoldEnd() end)
						return "Triggered the ProximityPrompt on " .. H.pathOf(prompt)
					end
				end

				if caps.fn.firetouchinterest then
					local root = env.plr and env.plr.Character
						and (env.plr.Character:FindFirstChild("HumanoidRootPart") or env.plr.Character.PrimaryPart)
					local okPart, isPart = pcall(function() return instance:IsA("BasePart") end)
					if root and okPart and isPart then
						pcall(caps.fn.firetouchinterest, root, instance, 0)
						clock.wait(0.05)
						pcall(caps.fn.firetouchinterest, root, instance, 1)
						return "Simulated a touch on " .. H.pathOf(instance)
					end
				end

				return H.fail("nothing interactable found at that path, or the host lacks the function to trigger it")
			end,
		},
		{
			name = "highlight",
			risk = "write",
			description = "Outline an instance on screen for a few seconds so the user can see which one you mean.",
			parameters = {
				type = "object",
				properties = {
					path = { type = "string" },
					seconds = { type = "number", description = "1-30. Default 6.", minimum = 1, maximum = 30 },
					colour = { type = "string", description = "Outline colour as 'r, g, b' or '#rrggbb'." },
				},
				required = { "path" },
			},
			run = function(args)
				local instance, err = H.resolve(args.path)
				if not instance then return H.fail(err) end

				local okNew, highlight = pcall(function() return Instance.new("Highlight") end)
				if not okNew or not highlight then return H.fail("this host has no Highlight class") end

				local colour = Color3.fromRGB(0, 225, 190)
				if args.colour and util.trim(args.colour) ~= "" then
					local parsed = H.coerce(args.colour, colour)
					if parsed then colour = parsed end
				end

				highlight.Name = "UAI_Highlight"
				highlight.FillColor = colour
				highlight.OutlineColor = colour
				highlight.FillTransparency = 0.65
				highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
				highlight.Adornee = instance
				highlight.Parent = instance

				local seconds = util.clamp(tonumber(args.seconds) or 6, 1, 30)
				clock.delay(seconds, function()
					pcall(function() highlight:Destroy() end)
				end)
				return string.format("Highlighted %s for %.0f seconds", H.pathOf(instance), seconds)
			end,
		},
		{
			name = "notify",
			risk = "read",
			description = "Show a short message to the user as a toast in the agent's own interface. Use it for something worth noticing, not for your reply.",
			parameters = {
				type = "object",
				properties = {
					text = { type = "string", description = "One line, under about 90 characters." },
					tone = { type = "string", enum = { "info", "good", "warn", "bad" } },
				},
				required = { "text" },
			},
			run = function(args)
				local overlay = env.require("ui/overlay")
				local text = util.ellipsis(args.text, 140)
				overlay.toast(text, args.tone or "info")
				return "Shown to the user: " .. text
			end,
		},
		{
			name = "clipboard_set",
			risk = "write",
			needs = { "clipboard" },
			description = "Put text on the user's clipboard.",
			parameters = {
				type = "object",
				properties = { text = { type = "string" } },
				required = { "text" },
			},
			run = function(args)
				local text = tostring(args.text or "")
				if text == "" then return "Nothing to copy." end
				local ok, err = pcall(caps.fn.clipboard, text)
				if not ok then return H.fail(tostring(err)) end
				return string.format("Copied %d characters to the clipboard.", #text)
			end,
		},
	}
end
end)()

-- ==========================================================================
-- tools/helpers
-- ==========================================================================
__UAI_MODULES["tools/helpers"] = (function()
-- Shared machinery for the tool groups: path resolution, value conversion in both
-- directions, and the formatting conventions every tool result follows.
--
-- Two rules drive the design. Model output is untrusted text, so a path or a
-- property value is parsed rather than trusted. And a tool result is read by a
-- model, not a person, so it is dense, labelled, and bounded -- a wall of
-- unlabelled values costs tokens and teaches nothing.
return function(env)
	local util = env.require("runtime/util")

	local H = {}

	-- Paths ------------------------------------------------------------------

	local ROOTS = {
		game = function() return game end,
		workspace = function() return env.services.Workspace end,
		players = function() return env.services.Players end,
		lighting = function() return env.services.Lighting end,
		replicatedstorage = function() return env.services.ReplicatedStorage end,
		replicatedfirst = function() return env.services.ReplicatedFirst end,
		starterplayer = function() return env.services.StarterPlayer end,
		startergui = function() return env.services.StarterGui end,
		soundservice = function() return env.services.SoundService end,
		teams = function() return env.services.Teams end,
		me = function() return env.plr end,
		localplayer = function() return env.plr end,
		character = function() return env.plr and env.plr.Character end,
		playergui = function() return env.plr and env.plr:FindFirstChild("PlayerGui") end,
		camera = function() return env.services.Workspace.CurrentCamera end,
	}

	H.ROOT_NAMES = { "game", "workspace", "players", "lighting", "me", "character", "playergui", "camera" }

	-- "Workspace.Folder.Part", "game.Players.Someone", "me.Character.Humanoid".
	--
	-- A leading `game.` is optional, service names resolve through GetService (so a
	-- renamed service instance still works), and a segment that is not a child is
	-- reported with the path that did resolve -- which is the difference between a
	-- model fixing its own typo and a model guessing again.
	function H.resolve(path)
		local text = util.trim(path)
		if text == "" then return nil, "no path given" end

		local segments = util.split(text:gsub("^game%.", ""), ".")
		if #segments == 0 then return nil, "no path given" end

		local first = tostring(segments[1]):lower()
		local node
		if ROOTS[first] then
			node = ROOTS[first]()
			if not node then return nil, "'" .. segments[1] .. "' does not exist right now" end
			table.remove(segments, 1)
		else
			-- Try it as a service name before giving up.
			local ok, service = pcall(function() return game:GetService(segments[1]) end)
			if ok and service then
				node = service
				table.remove(segments, 1)
			else
				node = env.services.Workspace
			end
		end

		local walked = { node.Name }
		for _, segment in ipairs(segments) do
			local child = node:FindFirstChild(segment)
			if not child then
				return nil, string.format("'%s' has no child named '%s'",
					table.concat(walked, "."), segment)
			end
			node = child
			walked[#walked + 1] = segment
		end
		return node
	end

	function H.pathOf(instance)
		if not instance then return "nil" end
		local ok, name = pcall(function() return instance:GetFullName() end)
		return ok and name or tostring(instance)
	end

	-- Values -----------------------------------------------------------------

	-- Roblox value -> compact text a model can read and, importantly, feed back in.
	function H.show(value)
		local kind = typeof(value)
		if value == nil then return "nil" end
		if kind == "Vector3" then
			return string.format("%.2f, %.2f, %.2f", value.X, value.Y, value.Z)
		end
		if kind == "Vector2" then
			return string.format("%.2f, %.2f", value.X, value.Y)
		end
		if kind == "CFrame" then
			local p = value.Position
			return string.format("%.2f, %.2f, %.2f", p.X, p.Y, p.Z)
		end
		if kind == "Color3" then
			return string.format("%d, %d, %d",
				math.floor(value.R * 255 + 0.5), math.floor(value.G * 255 + 0.5), math.floor(value.B * 255 + 0.5))
		end
		if kind == "UDim2" then
			return string.format("%.3g, %d, %.3g, %d", value.X.Scale, value.X.Offset, value.Y.Scale, value.Y.Offset)
		end
		if kind == "UDim" then
			return string.format("%.3g, %d", value.Scale, value.Offset)
		end
		if kind == "NumberRange" then
			return string.format("%.3g..%.3g", value.Min, value.Max)
		end
		if kind == "EnumItem" then
			return "Enum." .. tostring(value.EnumType) .. "." .. tostring(value.Name)
		end
		if kind == "Instance" then
			return H.pathOf(value) .. " [" .. tostring(value.ClassName) .. "]"
		end
		if kind == "BrickColor" then return tostring(value.Name) end
		if kind == "number" then
			if value == math.floor(value) and math.abs(value) < 1e12 then return string.format("%d", value) end
			return string.format("%.4g", value)
		end
		if kind == "boolean" then return value and "true" or "false" end
		if kind == "string" then return value end
		if kind == "table" then return "{table}" end
		return tostring(value)
	end

	local function numbers(text, count)
		local out = {}
		for piece in tostring(text):gmatch("%-?%d+%.?%d*") do
			out[#out + 1] = tonumber(piece)
		end
		if count and #out < count then return nil end
		return out
	end

	-- Text (or a JSON object) -> a Roblox value of the same type as `current`.
	--
	-- Typing off the existing value is what makes one set_property tool work for
	-- both a Part's Vector3 Size and a Frame's UDim2 Size without the model having
	-- to know which it is looking at.
	function H.coerce(input, current)
		local wanted = typeof(current)

		if type(input) == "table" and not (wanted == "table") then
			-- JSON object form: { x = 1, y = 2, z = 3 } or { r = 255, ... }.
			local parts = input
			if wanted == "Vector3" then
				return Vector3.new(tonumber(parts.x or parts.X) or 0, tonumber(parts.y or parts.Y) or 0, tonumber(parts.z or parts.Z) or 0)
			end
			if wanted == "Vector2" then
				return Vector2.new(tonumber(parts.x or parts.X) or 0, tonumber(parts.y or parts.Y) or 0)
			end
			if wanted == "Color3" then
				local r = tonumber(parts.r or parts.R) or 0
				local g = tonumber(parts.g or parts.G) or 0
				local b = tonumber(parts.b or parts.B) or 0
				if r <= 1 and g <= 1 and b <= 1 then return Color3.new(r, g, b) end
				return Color3.fromRGB(r, g, b)
			end
			if wanted == "UDim2" then
				return UDim2.new(
					tonumber(parts.xScale or parts.sx) or 0, tonumber(parts.xOffset or parts.ox) or 0,
					tonumber(parts.yScale or parts.sy) or 0, tonumber(parts.yOffset or parts.oy) or 0)
			end
			return nil, "cannot build a " .. tostring(wanted) .. " from an object"
		end

		local text = util.trim(input)

		if wanted == "number" then
			local value = tonumber(text)
			if not value then return nil, "expected a number" end
			return value
		end
		if wanted == "boolean" then
			local lowered = text:lower()
			if lowered == "true" or lowered == "1" or lowered == "yes" then return true end
			if lowered == "false" or lowered == "0" or lowered == "no" then return false end
			return nil, "expected true or false"
		end
		if wanted == "string" then return text end
		if wanted == "Vector3" then
			local list = numbers(text, 3)
			if not list then return nil, "expected three numbers, e.g. '0, 10, 0'" end
			return Vector3.new(list[1], list[2], list[3])
		end
		if wanted == "Vector2" then
			local list = numbers(text, 2)
			if not list then return nil, "expected two numbers" end
			return Vector2.new(list[1], list[2])
		end
		if wanted == "CFrame" then
			local list = numbers(text, 3)
			if not list then return nil, "expected three numbers for a position" end
			return CFrame.new(list[1], list[2], list[3])
		end
		if wanted == "Color3" then
			local hex = text:match("^#?(%x%x%x%x%x%x)$")
			if hex then return Color3.fromHex(hex) end
			local list = numbers(text, 3)
			if not list then return nil, "expected 'r, g, b' or a hex colour" end
			if list[1] <= 1 and list[2] <= 1 and list[3] <= 1 then
				return Color3.new(list[1], list[2], list[3])
			end
			return Color3.fromRGB(list[1], list[2], list[3])
		end
		if wanted == "UDim2" then
			local list = numbers(text, 4)
			if not list then return nil, "expected four numbers: xScale, xOffset, yScale, yOffset" end
			return UDim2.new(list[1], list[2], list[3], list[4])
		end
		if wanted == "UDim" then
			local list = numbers(text, 2)
			if not list then return nil, "expected two numbers: scale, offset" end
			return UDim.new(list[1], list[2])
		end
		if wanted == "NumberRange" then
			local list = numbers(text, 1)
			if not list then return nil, "expected one or two numbers" end
			return NumberRange.new(list[1], list[2] or list[1])
		end
		if wanted == "EnumItem" then
			local enumType = tostring(current.EnumType)
			local wantedName = text:match("([%w_]+)$") or text
			local ok, items = pcall(function() return Enum[enumType]:GetEnumItems() end)
			if ok and type(items) == "table" then
				for _, item in ipairs(items) do
					if tostring(item.Name):lower() == wantedName:lower() then return item end
				end
				local names = {}
				for _, item in ipairs(items) do names[#names + 1] = item.Name end
				return nil, "expected one of: " .. table.concat(names, ", ")
			end
			return nil, "unknown enum " .. enumType
		end
		if wanted == "Instance" or current == nil then
			local instance, err = H.resolve(text)
			if instance then return instance end
			if current == nil then return text end
			return nil, err
		end
		if wanted == "BrickColor" then
			local ok, colour = pcall(function() return BrickColor.new(text) end)
			if ok then return colour end
			return nil, "unknown BrickColor"
		end
		return nil, "setting a " .. tostring(wanted) .. " is not supported"
	end

	-- Formatting -------------------------------------------------------------

	function H.describe(instance)
		if not instance then return "nil" end
		local extra = {}
		local ok = pcall(function()
			if instance:IsA("BasePart") then
				extra[#extra + 1] = "at " .. H.show(instance.Position)
			elseif instance:IsA("GuiObject") then
				extra[#extra + 1] = "size " .. H.show(instance.Size)
			elseif instance:IsA("Humanoid") then
				extra[#extra + 1] = string.format("health %s/%s", H.show(instance.Health), H.show(instance.MaxHealth))
			end
		end)
		local childCount = 0
		pcall(function() childCount = #instance:GetChildren() end)
		if childCount > 0 then extra[#extra + 1] = util.pluralise(childCount, "child") end
		return string.format("%s [%s]%s", instance.Name, instance.ClassName,
			(ok and #extra > 0) and (" " .. table.concat(extra, ", ")) or "")
	end

	-- Numbered list with an explicit note when it was cut short, so a model can
	-- tell "that is everything" from "there is more".
	function H.list(items, limit, render)
		local lines = {}
		local shown = math.min(#items, limit or #items)
		for index = 1, shown do
			lines[#lines + 1] = string.format("%d. %s", index, render and render(items[index], index) or tostring(items[index]))
		end
		if #items > shown then
			lines[#lines + 1] = string.format("... %d more (narrow the query to see them)", #items - shown)
		end
		if #lines == 0 then return "(none)" end
		return table.concat(lines, "\n")
	end

	function H.keyValues(pairsList)
		local lines = {}
		for _, entry in ipairs(pairsList) do
			lines[#lines + 1] = entry[1] .. ": " .. tostring(entry[2])
		end
		return table.concat(lines, "\n")
	end

	function H.limit(value, fallback, ceiling)
		local number = tonumber(value) or fallback
		return math.floor(util.clamp(number, 1, ceiling or 200))
	end

	-- A tool that could not do what was asked returns this rather than a bare
	-- string, so the registry can mark the call as failed and the transcript can
	-- colour it. The model sees the same sentence either way.
	function H.fail(message)
		return { ok = false, text = "Failed: " .. tostring(message) }
	end

	-- A tool that changed something says what it changed and where, because the
	-- next turn often needs the path again.
	function H.changed(what, where, detail)
		return string.format("%s on %s%s", what, where, detail and (" -> " .. detail) or "")
	end

	return H
end
end)()

-- ==========================================================================
-- tools/init
-- ==========================================================================
__UAI_MODULES["tools/init"] = (function()
-- Collects the tool groups.
--
-- Adding a group is one entry in GROUPS. Each group module returns a flat list of
-- tool definitions; the registry above turns them into a name map and the wire
-- format. A group that fails to load is skipped with a warning rather than taking
-- the client down -- a broken tool should cost one capability, not the session.
local GROUPS = {
	"agentself",
	"instance",
	"script",
	"fs",
	"net",
	"web",
	"players",
	"character",
	"world",
	"remotes",
	"gui",
	"perf",
	"meta",
}

return function(env)
	local log = env.require("runtime/log")

	local M = { groups = GROUPS }

	function M.all()
		local out = {}
		for _, group in ipairs(GROUPS) do
			local ok, tools = pcall(env.require, "tools/" .. group)
			if not ok then
				log.error("tools", "group '" .. group .. "' failed to load", tools)
			elseif type(tools) ~= "table" then
				log.warn("tools", "group '" .. group .. "' returned no tools")
			else
				for _, tool in ipairs(tools) do
					tool.group = tool.group or group
					out[#out + 1] = tool
				end
			end
		end
		return out
	end

	return M
end
end)()

-- ==========================================================================
-- tools/instance
-- ==========================================================================
__UAI_MODULES["tools/instance"] = (function()
-- Instance tree: inspection, property access, creation and removal.
--
-- Luau cannot enumerate an instance's properties, so reads work from a curated
-- list per class family plus whatever the caller names explicitly. That is a
-- deliberate trade: a short labelled block the model can act on beats a reflection
-- trick that returns four hundred fields.
return function(env)
	local util = env.require("runtime/util")
	local H = env.require("tools/helpers")

	local SCAN_CAP = 20000

	local COMMON = { "Name", "ClassName" }

	local BY_CLASS = {
		{ "BasePart", { "Position", "Size", "Orientation", "Anchored", "CanCollide", "CanTouch", "Transparency", "Color", "Material", "Massless", "Shape", "Reflectance" } },
		{ "Model", { "PrimaryPart", "WorldPivot" } },
		{ "GuiObject", { "Position", "Size", "AnchorPoint", "Visible", "BackgroundColor3", "BackgroundTransparency", "ZIndex", "LayoutOrder", "Rotation", "ClipsDescendants", "AutomaticSize", "AbsolutePosition", "AbsoluteSize" } },
		{ "TextLabel", { "Text", "TextColor3", "TextSize", "Font", "TextWrapped", "RichText", "TextXAlignment", "TextYAlignment", "TextTransparency" } },
		{ "TextButton", { "Text", "TextColor3", "TextSize", "Font", "AutoButtonColor" } },
		{ "TextBox", { "Text", "PlaceholderText", "TextColor3", "TextSize", "ClearTextOnFocus", "MultiLine" } },
		{ "ImageLabel", { "Image", "ImageColor3", "ImageTransparency", "ScaleType" } },
		{ "ScrollingFrame", { "CanvasSize", "CanvasPosition", "ScrollBarThickness", "AutomaticCanvasSize", "ScrollingEnabled" } },
		{ "ScreenGui", { "Enabled", "DisplayOrder", "IgnoreGuiInset", "ResetOnSpawn", "ZIndexBehavior" } },
		{ "Humanoid", { "Health", "MaxHealth", "WalkSpeed", "JumpPower", "JumpHeight", "HipHeight", "Sit", "PlatformStand", "MoveDirection", "RigType" } },
		{ "Player", { "DisplayName", "UserId", "AccountAge", "Team", "TeamColor", "CharacterAppearanceId" } },
		{ "Camera", { "CFrame", "FieldOfView", "CameraType", "CameraSubject", "Focus" } },
		{ "Sound", { "SoundId", "Volume", "Playing", "Looped", "TimePosition", "PlaybackSpeed" } },
		{ "Light", { "Brightness", "Color", "Range", "Enabled", "Shadows" } },
		{ "Lighting", { "ClockTime", "Brightness", "Ambient", "OutdoorAmbient", "FogColor", "FogStart", "FogEnd", "GlobalShadows", "ExposureCompensation" } },
		{ "ValueBase", { "Value" } },
		{ "Decal", { "Texture", "Transparency", "Face" } },
		{ "Tool", { "RequiresHandle", "CanBeDropped", "Enabled", "ToolTip" } },
		{ "ProximityPrompt", { "ActionText", "ObjectText", "HoldDuration", "MaxActivationDistance", "Enabled" } },
		{ "Attachment", { "Position", "WorldPosition", "Axis" } },
		{ "UIListLayout", { "FillDirection", "Padding", "SortOrder", "HorizontalAlignment", "VerticalAlignment", "Wraps" } },
		{ "UIPadding", { "PaddingTop", "PaddingBottom", "PaddingLeft", "PaddingRight" } },
		{ "UIStroke", { "Color", "Thickness", "Transparency", "ApplyStrokeMode" } },
		{ "UICorner", { "CornerRadius" } },
		{ "UIScale", { "Scale" } },
		{ "CanvasGroup", { "GroupTransparency", "GroupColor3" } },
		{ "Script", { "Enabled", "RunContext" } },
		{ "LuaSourceContainer", { "Source" } },
		{ "Terrain", { "WaterColor", "WaterTransparency", "WaterWaveSize" } },
		{ "SpawnLocation", { "Enabled", "Neutral", "TeamColor", "Duration" } },
		{ "Seat", { "Occupant", "Disabled" } },
	}

	local function propertyNames(instance, extra)
		local names, seen = {}, {}
		local function add(name)
			if type(name) == "string" and name ~= "" and not seen[name] then
				seen[name] = true
				names[#names + 1] = name
			end
		end
		for _, name in ipairs(COMMON) do add(name) end
		for _, entry in ipairs(BY_CLASS) do
			local ok, isA = pcall(function() return instance:IsA(entry[1]) end)
			if ok and isA then
				for _, name in ipairs(entry[2]) do add(name) end
			end
		end
		for _, name in ipairs(extra or {}) do add(name) end
		return names
	end

	local function readProperties(instance, extra)
		local rows = {}
		for _, name in ipairs(propertyNames(instance, extra)) do
			local ok, value = pcall(function() return instance[name] end)
			if ok and value ~= nil and typeof(value) ~= "function" then
				local shown = H.show(value)
				-- Source can be enormous; it has its own tool.
				if name == "Source" then shown = string.format("<%d characters, use script_source>", #tostring(value)) end
				rows[#rows + 1] = { name, shown }
			end
		end
		return rows
	end

	-- Depth-limited walk. The cap is on nodes visited rather than depth alone,
	-- because one folder with nine thousand parts is the common shape and a depth
	-- limit alone would not save us from it.
	local function walk(root, maxDepth, perLevel)
		local lines = {}
		local visited = 0
		local function recurse(node, depth, prefix)
			if depth > maxDepth then return end
			local ok, children = pcall(function() return node:GetChildren() end)
			if not ok then return end
			local shown = math.min(#children, perLevel)
			for index = 1, shown do
				local child = children[index]
				visited = visited + 1
				if visited > SCAN_CAP then return end
				lines[#lines + 1] = prefix .. H.describe(child)
				recurse(child, depth + 1, prefix .. "  ")
			end
			if #children > shown then
				lines[#lines + 1] = prefix .. string.format("... %d more children", #children - shown)
			end
		end
		recurse(root, 1, "")
		return lines, visited
	end

	return {
		{
			name = "instance_tree",
			risk = "read",
			description = "List the children of an instance as an indented tree. Start here when exploring an unfamiliar game.",
			parameters = {
				type = "object",
				properties = {
					path = { type = "string", description = "Dotted path, e.g. 'Workspace.Map' or 'me.Character'. Defaults to Workspace." },
					depth = { type = "integer", description = "Levels to descend, 1-6. Default 2.", minimum = 1, maximum = 6 },
					limit = { type = "integer", description = "Children shown per level, 1-80. Default 30.", minimum = 1, maximum = 80 },
				},
				required = {},
			},
			run = function(args)
				local root, err = H.resolve(args.path or "Workspace")
				if not root then return H.fail(err) end
				local lines, visited = walk(root, H.limit(args.depth, 2, 6), H.limit(args.limit, 30, 80))
				if #lines == 0 then
					return H.pathOf(root) .. " [" .. root.ClassName .. "] has no children."
				end
				return string.format("%s [%s], %d nodes shown:\n%s",
					H.pathOf(root), root.ClassName, visited, table.concat(lines, "\n"))
			end,
		},
		{
			name = "instance_find",
			risk = "read",
			description = "Search a subtree for instances by name and/or class. Name matching is a case-insensitive substring.",
			parameters = {
				type = "object",
				properties = {
					name = { type = "string", description = "Substring of the instance name." },
					class = { type = "string", description = "Class name, matched with IsA, e.g. 'BasePart' or 'RemoteEvent'." },
					root = { type = "string", description = "Where to search. Defaults to Workspace; use 'game' to search everything." },
					limit = { type = "integer", description = "Maximum results, 1-100. Default 25.", minimum = 1, maximum = 100 },
				},
				required = {},
			},
			run = function(args)
				local needle = util.trim(args.name):lower()
				local class = util.trim(args.class)
				if needle == "" and class == "" then
					return "Give a name, a class, or both."
				end
				local root, err = H.resolve(args.root or "Workspace")
				if not root then return H.fail(err) end

				local ok, descendants = pcall(function() return root:GetDescendants() end)
				if not ok then return H.fail("could not read that subtree") end

				local limit = H.limit(args.limit, 25, 100)
				local hits, scanned = {}, 0
				for _, node in ipairs(descendants) do
					scanned = scanned + 1
					if scanned > SCAN_CAP then break end
					local matches = true
					if needle ~= "" and not tostring(node.Name):lower():find(needle, 1, true) then matches = false end
					if matches and class ~= "" then
						local okA, isA = pcall(function() return node:IsA(class) end)
						matches = okA and isA
					end
					if matches then hits[#hits + 1] = node end
				end

				if #hits == 0 then
					return string.format("No match under %s (%d instances scanned).", H.pathOf(root), scanned)
				end
				return string.format("%d match(es) under %s:\n%s", #hits, H.pathOf(root),
					H.list(hits, limit, function(node)
						return H.pathOf(node) .. " [" .. node.ClassName .. "]"
					end))
			end,
		},
		{
			name = "instance_get",
			risk = "read",
			description = "Read an instance's properties, attributes and tags. Do this before setting anything.",
			parameters = {
				type = "object",
				properties = {
					path = { type = "string", description = "Dotted path to the instance." },
					properties = {
						type = "array",
						description = "Extra property names to read beyond the usual set for this class.",
						items = { type = "string" },
					},
				},
				required = { "path" },
			},
			run = function(args)
				local instance, err = H.resolve(args.path)
				if not instance then return H.fail(err) end

				local blocks = { H.pathOf(instance) .. " [" .. instance.ClassName .. "]" }
				blocks[#blocks + 1] = H.keyValues(readProperties(instance, args.properties))

				local okAttrs, attributes = pcall(function() return instance:GetAttributes() end)
				if okAttrs and type(attributes) == "table" and util.count(attributes) > 0 then
					local rows = {}
					for _, key in ipairs(util.keys(attributes, true)) do
						rows[#rows + 1] = { key, H.show(attributes[key]) }
					end
					blocks[#blocks + 1] = "Attributes:\n" .. H.keyValues(rows)
				end

				local okTags, tags = pcall(function() return instance:GetTags() end)
				if okTags and type(tags) == "table" and #tags > 0 then
					blocks[#blocks + 1] = "Tags: " .. table.concat(tags, ", ")
				end

				local okChildren, children = pcall(function() return instance:GetChildren() end)
				if okChildren then
					blocks[#blocks + 1] = util.pluralise(#children, "child")
				end

				return table.concat(blocks, "\n")
			end,
		},
		{
			name = "instance_set",
			risk = "write",
			description = "Set one property on one instance. The value is converted to the property's existing type, so 'Size' takes '4, 1, 2' on a part and '0, 200, 0, 40' on a GUI frame.",
			parameters = {
				type = "object",
				properties = {
					path = { type = "string" },
					property = { type = "string" },
					value = { type = "string", description = "Text form of the value. Numbers comma-separated; colours as 'r, g, b' or '#rrggbb'; enums by name." },
				},
				required = { "path", "property", "value" },
			},
			run = function(args)
				local instance, err = H.resolve(args.path)
				if not instance then return H.fail(err) end
				local name = util.trim(args.property)

				local okRead, current = pcall(function() return instance[name] end)
				if not okRead then
					return H.fail(string.format("%s has no property '%s'", instance.ClassName, name))
				end

				local value, convertErr = H.coerce(args.value, current)
				if value == nil then return H.fail(convertErr or "could not convert that value") end

				local before = H.show(current)
				local okWrite, writeErr = pcall(function() instance[name] = value end)
				if not okWrite then
					return H.fail(string.format("%s.%s could not be set: %s", instance.ClassName, name, tostring(writeErr)))
				end

				local after = H.show(select(2, pcall(function() return instance[name] end)))
				return H.changed(name .. " = " .. after, H.pathOf(instance), "was " .. before)
			end,
		},
		{
			name = "instance_create",
			risk = "write",
			description = "Create an instance and parent it. Properties are applied after creation, in the order given.",
			parameters = {
				type = "object",
				properties = {
					class = { type = "string", description = "Class name, e.g. 'Part', 'Folder', 'Highlight'." },
					parent = { type = "string", description = "Dotted path for the parent. Defaults to Workspace." },
					name = { type = "string", description = "Name for the new instance." },
					properties = {
						type = "object",
						description = "Property name to text value, applied after creation.",
					},
				},
				required = { "class" },
			},
			run = function(args)
				local okNew, instance = pcall(function() return Instance.new(tostring(args.class)) end)
				if not okNew or not instance then
					return H.fail("'" .. tostring(args.class) .. "' is not a creatable class")
				end

				if args.name and util.trim(args.name) ~= "" then instance.Name = util.trim(args.name) end

				local applied, failed = {}, {}
				for key, raw in pairs(args.properties or {}) do
					local okRead, current = pcall(function() return instance[key] end)
					if okRead then
						local value, convertErr = H.coerce(raw, current)
						if value ~= nil then
							local okWrite = pcall(function() instance[key] = value end)
							if okWrite then
								applied[#applied + 1] = key
							else
								failed[#failed + 1] = key
							end
						else
							failed[#failed + 1] = key .. " (" .. tostring(convertErr) .. ")"
						end
					else
						failed[#failed + 1] = key .. " (no such property)"
					end
				end

				local parent, parentErr = H.resolve(args.parent or "Workspace")
				if not parent then
					instance:Destroy()
					return H.fail("parent not found: " .. tostring(parentErr))
				end
				instance.Parent = parent

				local note = string.format("Created %s at %s", instance.ClassName, H.pathOf(instance))
				if #applied > 0 then note = note .. "\nSet: " .. table.concat(applied, ", ") end
				if #failed > 0 then note = note .. "\nCould not set: " .. table.concat(failed, ", ") end
				return note
			end,
		},
		{
			name = "instance_clone",
			risk = "write",
			description = "Clone an instance. The copy keeps its children.",
			parameters = {
				type = "object",
				properties = {
					path = { type = "string" },
					parent = { type = "string", description = "Where the copy goes. Defaults to the original's parent." },
					name = { type = "string", description = "Name for the copy." },
				},
				required = { "path" },
			},
			run = function(args)
				local instance, err = H.resolve(args.path)
				if not instance then return H.fail(err) end
				local okClone, copy = pcall(function() return instance:Clone() end)
				if not okClone or not copy then
					return H.fail("that instance cannot be cloned (Archivable may be false)")
				end
				if args.name and util.trim(args.name) ~= "" then copy.Name = util.trim(args.name) end
				local parent = instance.Parent
				if args.parent and util.trim(args.parent) ~= "" then
					local resolved, parentErr = H.resolve(args.parent)
					if not resolved then
						copy:Destroy()
						return H.fail("parent not found: " .. tostring(parentErr))
					end
					parent = resolved
				end
				copy.Parent = parent
				return "Cloned to " .. H.pathOf(copy)
			end,
		},
		{
			name = "instance_destroy",
			risk = "danger",
			description = "Destroy an instance and everything under it. This cannot be undone.",
			parameters = {
				type = "object",
				properties = { path = { type = "string" } },
				required = { "path" },
			},
			run = function(args)
				local instance, err = H.resolve(args.path)
				if not instance then return H.fail(err) end
				local full = H.pathOf(instance)
				local okCount, children = pcall(function() return #instance:GetDescendants() end)
				local okDestroy, destroyErr = pcall(function() instance:Destroy() end)
				if not okDestroy then return H.fail(tostring(destroyErr)) end
				return string.format("Destroyed %s%s", full,
					okCount and (" and " .. util.pluralise(children, "descendant")) or "")
			end,
		},
		{
			name = "instance_parent",
			risk = "write",
			description = "Reparent an instance.",
			parameters = {
				type = "object",
				properties = {
					path = { type = "string" },
					parent = { type = "string", description = "New parent path, or 'nil' to detach it." },
				},
				required = { "path", "parent" },
			},
			run = function(args)
				local instance, err = H.resolve(args.path)
				if not instance then return H.fail(err) end
				local was = H.pathOf(instance)
				if util.trim(args.parent):lower() == "nil" then
					local ok, setErr = pcall(function() instance.Parent = nil end)
					if not ok then return H.fail(tostring(setErr)) end
					return "Detached " .. was
				end
				local parent, parentErr = H.resolve(args.parent)
				if not parent then return H.fail(parentErr) end
				local ok, setErr = pcall(function() instance.Parent = parent end)
				if not ok then return H.fail(tostring(setErr)) end
				return string.format("Moved %s to %s", was, H.pathOf(instance))
			end,
		},
		{
			name = "instance_attribute",
			risk = "write",
			description = "Read or write an attribute on an instance. Omit value to read.",
			parameters = {
				type = "object",
				properties = {
					path = { type = "string" },
					name = { type = "string" },
					value = { type = "string", description = "Omit to read. Numbers, booleans and strings are detected automatically." },
				},
				required = { "path", "name" },
			},
			run = function(args)
				local instance, err = H.resolve(args.path)
				if not instance then return H.fail(err) end
				if args.value == nil then
					local ok, value = pcall(function() return instance:GetAttribute(args.name) end)
					if not ok then return H.fail("could not read that attribute") end
					if value == nil then return "Attribute '" .. tostring(args.name) .. "' is not set." end
					return tostring(args.name) .. " = " .. H.show(value)
				end
				local text = util.trim(args.value)
				local value = tonumber(text)
				if value == nil then
					if text:lower() == "true" then value = true
					elseif text:lower() == "false" then value = false
					else value = text end
				end
				local ok, setErr = pcall(function() instance:SetAttribute(args.name, value) end)
				if not ok then return H.fail(tostring(setErr)) end
				return H.changed("attribute " .. tostring(args.name) .. " = " .. H.show(value), H.pathOf(instance))
			end,
		},
		{
			name = "instance_tagged",
			risk = "read",
			description = "List instances carrying a CollectionService tag, or list every tag in use.",
			parameters = {
				type = "object",
				properties = {
					tag = { type = "string", description = "Omit to list all tags in the place." },
					limit = { type = "integer", minimum = 1, maximum = 100 },
				},
				required = {},
			},
			run = function(args)
				local service = env.services.CollectionService
				if not args.tag or util.trim(args.tag) == "" then
					local ok, tags = pcall(function() return service:GetAllTags() end)
					if not ok or type(tags) ~= "table" or #tags == 0 then return "No tags are in use here." end
					return util.pluralise(#tags, "tag") .. ": " .. table.concat(tags, ", ")
				end
				local ok, tagged = pcall(function() return service:GetTagged(util.trim(args.tag)) end)
				if not ok or type(tagged) ~= "table" then return H.fail("could not read that tag") end
				if #tagged == 0 then return "Nothing is tagged '" .. util.trim(args.tag) .. "'." end
				return string.format("%d instance(s) tagged '%s':\n%s", #tagged, util.trim(args.tag),
					H.list(tagged, H.limit(args.limit, 25, 100), function(node)
						return H.pathOf(node) .. " [" .. node.ClassName .. "]"
					end))
			end,
		},
	}
end
end)()

