__UAI_MODULES["ui/app"] = (function()
-- The application shell: the ScreenGui, the launcher, the window, navigation, and
-- the wiring between the session and the interface.
--
-- Surfaces here are pure functions of state, which is what makes the rebuild on a
-- layout-mode change safe: the transcript replays from the session log, every
-- panel re-reads config, and nothing is lost by throwing the tree away.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local caps = env.require("runtime/caps")
	local clock = env.require("runtime/clock")
	local log = env.require("runtime/log")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local icons = env.require("ui/icons")
	local dispose = env.require("runtime/dispose")
	local P = env.require("ui/primitives")
	local C = env.require("ui/controls")
	local overlay = env.require("ui/overlay")
	local quickchat = env.require("ui/quickchat")
	local windowModule = env.require("ui/window")
	local sessions = env.require("agent/session")
	local providers = env.require("provider/registry")
	local models = env.require("provider/models")
	local traits = env.require("provider/traits")
	local usage = env.require("agent/usage")

	local PANELS = {
		{ id = "chat", label = "Chat" },
		{ id = "providers", label = "Providers" },
		{ id = "tools", label = "Tools" },
		{ id = "settings", label = "Settings" },
		{ id = "logs", label = "Logs" },
	}

	local M = { panel = "chat", built = false }

	-- Where a client GUI can live. gethui is the sturdiest under an executor
	-- (nothing in the game can see it); CoreGui is next; PlayerGui always works but
	-- is wiped on respawn, so it is the last resort.
	local function parentGui()
		if caps.fn.gethui then
			local ok, container = pcall(caps.fn.gethui)
			if ok and container then return container end
		end
		local okCore, coreGui = pcall(function() return env.services.CoreGui end)
		if okCore and coreGui then return coreGui end
		if env.plr then
			local playerGui = env.plr:FindFirstChild("PlayerGui") or env.plr:WaitForChild("PlayerGui")
			if playerGui then return playerGui end
		end
		return nil
	end

	function M.mount()
		if M.screen and M.screen.Parent then return M end

		local container = parentGui()
		if not container then
			log.error("app", "nowhere to parent the interface")
			return M
		end

		local screen = Instance.new("ScreenGui")
		screen.Name = "UAI_" .. tostring(math.floor(clock.ms() % 100000))
		screen.ResetOnSpawn = false
		screen.IgnoreGuiInset = false
		screen.DisplayOrder = 2147480000
		screen.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
		-- Safe-area handling: on a notched phone the interface must not sit under the
		-- cutout, and on a console it must stay inside the title-safe region.
		pcall(function() screen.ScreenInsets = Enum.ScreenInsets.DeviceSafeInsets end)
		pcall(function() screen.SafeAreaCompatibility = Enum.SafeAreaCompatibility.FullscreenExtension end)
		screen.Parent = container
		M.screen = screen
		env.root = screen

		responsive.init(screen)
		overlay.mount(screen)

		-- Quick chat lives on the overlay layer and outlives every rebuild: it holds no
		-- transcript of its own, only a field, so there is nothing in it to rebuild.
		quickchat.mount(overlay.layer)
		quickchat.bind()

		M.buildLauncher()
		M.buildWindow()

		-- A real layout switch rebuilds; a resize does not. Debounced inside
		-- responsive, so a desktop drag does not thrash. Theme changes (accent,
		-- density, text scale) rebuild too: colours and metrics are read at build time
		-- by design, which keeps every component free of subscription bookkeeping.
		--
		-- Both are registered for disposal, because after an unload a config write must
		-- not rebuild an interface that is no longer there.
		dispose.add(responsive.modeChanged:connect(function()
			M.rebuild("mode")
		end), "app.modeChanged")

		dispose.add(theme.changed:connect(clock.debounce(function()
			M.rebuild("theme")
		end, 0.2)), "app.themeChanged")

		-- Two settings decide what a transcript row *shows* rather than how it looks, so
		-- the theme's token list does not cover them and nothing else would notice they
		-- moved. Every row reads them at build time like everything else here, which
		-- meant the switch did nothing to the rows already on screen: turning reasoning
		-- on left the conversation exactly as it was, which reads as a broken toggle
		-- rather than as a setting that applies from the next turn.
		--
		-- Only these two keys. A nil path and the whole "ui" section already reach
		-- rebuild through theme.changed, and answering both here would rebuild twice.
		local VIEW_KEYS = { ["ui.showReasoning"] = true, ["ui.showToolDetail"] = true }
		local rebuildForView = clock.debounce(function()
			M.rebuild("view setting")
		end, 0.2)
		dispose.add(config.changed:connect(function(path)
			if VIEW_KEYS[tostring(path)] then rebuildForView() end
		end), "app.viewSettings")

		log.info("app", "interface mounted in " .. tostring(container.Name) .. " as " .. responsive.mode)
		return M
	end

	-- Launcher ---------------------------------------------------------------

	function M.buildLauncher()
		if M.launcher and M.launcher.Parent then return end
		local diameter = math.max(theme.size.launcher, responsive.minTarget())

		local button = Instance.new("TextButton", M.screen)
		button.Name = "Launcher"
		button.Text = ""
		button.AutoButtonColor = false
		button.BackgroundColor3 = theme.color.surfaceOverlay
		button.BorderSizePixel = 0
		button.Size = UDim2.fromOffset(diameter, diameter)
		button.AnchorPoint = Vector2.new(1, 1)
		button.ZIndex = theme.z.header
		button.Selectable = true
		P.corner(button, theme.radius.pill)
		local outline = P.stroke(button, theme.color.border)

		if config.get("ui.launcher.placed", false) then
			button.Position = UDim2.new(0, config.get("ui.launcher.x", 0), 0, config.get("ui.launcher.y", 0))
			button.AnchorPoint = Vector2.new(0, 0)
		else
			button.Position = UDim2.new(1, -theme.space.lg, 1, -(theme.space.lg + responsive.bottomInset))
		end

		P.text(button, {
			text = "UAI",
			role = "label",
			color = theme.color.accent,
			align = "Center",
			size = UDim2.fromScale(1, 1),
		})

		local pulse = P.statusDot(button, {
			diameter = 8,
			color = theme.color.accent,
			anchor = Vector2.new(1, 0),
			position = UDim2.new(1, 2, 0, -2),
		})
		pulse.Visible = false

		-- The orb both drags and clicks, and Roblox fires Activated on release even
		-- after a drag, so a moved orb must not also open the window.
		local dragging, moved, origin, startPosition = false, false, nil, nil
		button.InputBegan:Connect(function(input)
			local kind = input.UserInputType
			if kind ~= Enum.UserInputType.MouseButton1 and kind ~= Enum.UserInputType.Touch then return end
			dragging, moved = true, false
			origin = input.Position
			startPosition = button.AbsolutePosition
			local connection
			connection = input.Changed:Connect(function()
				if input.UserInputState == Enum.UserInputState.End then
					dragging = false
					if connection then connection:Disconnect() end
					if moved then
						config.set("ui.launcher.x", math.floor(button.Position.X.Offset), { quiet = true })
						config.set("ui.launcher.y", math.floor(button.Position.Y.Offset), { quiet = true })
						config.set("ui.launcher.placed", true, { quiet = true })
					end
				end
			end)
		end)

		dispose.connection(env.uis.InputChanged:Connect(function(input)
			if not dragging then return end
			local kind = input.UserInputType
			if kind ~= Enum.UserInputType.MouseMovement and kind ~= Enum.UserInputType.Touch then return end
			local delta = input.Position - origin
			if math.abs(delta.X) > 6 or math.abs(delta.Y) > 6 then moved = true end
			local viewport = responsive.viewport
			button.AnchorPoint = Vector2.new(0, 0)
			button.Position = UDim2.fromOffset(
				math.floor(util.clamp(startPosition.X + delta.X, 0, viewport.X - diameter)),
				math.floor(util.clamp(startPosition.Y + delta.Y, responsive.inset.Y, viewport.Y - diameter)))
		end))

		button.MouseEnter:Connect(function()
			env.tween:Create(outline, theme.tween("hover"), { Color = theme.color.accentBorder }):Play()
		end)
		button.MouseLeave:Connect(function()
			env.tween:Create(outline, theme.tween("hover"), { Color = theme.color.border }):Play()
		end)
		button.Activated:Connect(function()
			if moved then
				moved = false
				return
			end
			M.toggle()
		end)

		M.launcher = button
		M.launcherPulse = pulse
	end

	-- A dot named "pulse" that had never pulsed: the only thing on screen saying a
	-- turn is still running with the window closed, and it was a static toggle.
	function M.setLauncherBusy(value)
		if not M.launcherPulse then return end
		local on = value == true
		M.launcherPulse.Visible = on
		if M.launcherTween then
			pcall(function() M.launcherTween:Cancel() end)
			M.launcherTween = nil
		end
		if not on or responsive.reduceMotion then
			M.launcherPulse.BackgroundTransparency = 0
			return
		end
		M.launcherPulse.BackgroundTransparency = 0.6
		M.launcherTween = env.tween:Create(M.launcherPulse, theme.motion.pulse,
			{ BackgroundTransparency = 0 })
		M.launcherTween:Play()
	end

	-- Window -----------------------------------------------------------------

	function M.buildWindow()
		M.window = windowModule.new(M.screen, {
			name = "UAI_Window",
			minWidth = 340,
			minHeight = 300,
		})
		M.buildChrome()
		M.buildBody()
		M.window.onLayout = function()
			M.syncNav()
		end
	end

	function M.buildChrome()
		local header = M.window.header
		local compact = responsive.viewport.X < 640 or responsive.mode == "sheet"

		local left = P.row(header, {
			name = "Left",
			size = UDim2.new(0, 0, 1, 0),
			auto = "X",
			gap = theme.space.sm,
			layoutOrder = 1,
		})

		P.text(left, {
			text = "UAI",
			role = "title",
			color = theme.color.text,
			layoutOrder = 1,
		}).Size = UDim2.fromOffset(40, theme.text.title.size + 4)

		-- The provider chip is the one piece of status worth permanent space: which
		-- endpoint and model a message is about to go to.
		local chip = Instance.new("TextButton", left)
		chip.Text = ""
		chip.AutoButtonColor = false
		chip.BackgroundColor3 = theme.color.surfaceOverlay
		chip.BorderSizePixel = 0
		chip.Size = UDim2.new(0, 0, 0, theme.size.controlSmall)
		chip.AutomaticSize = Enum.AutomaticSize.X
		chip.LayoutOrder = 2
		chip.Selectable = true
		P.corner(chip, theme.radius.pill)
		P.stroke(chip, theme.color.borderSubtle)

		local chipRow = P.row(chip, {
			size = UDim2.new(0, 0, 1, 0),
			auto = "X",
			gap = theme.space.xxs,
			padding = { x = theme.space.sm },
		})
		local chipDot = P.statusDot(chipRow, { diameter = 6, layoutOrder = 1 })
		local chipLabel = P.text(chipRow, {
			text = "no provider",
			role = "caption",
			color = theme.color.textSecondary,
			layoutOrder = 2,
		})
		chipLabel.Size = UDim2.fromOffset(0, theme.text.caption.size + 4)
		chipLabel.AutomaticSize = Enum.AutomaticSize.X

		chip.Activated:Connect(function() M.providerMenu(chip) end)
		M.chip = { button = chip, dot = chipDot, label = chipLabel }

		P.spacer(header, { grow = true, size = UDim2.new(0, 0, 1, 0) }).LayoutOrder = 2

		local right = P.row(header, {
			name = "Right",
			size = UDim2.new(0, 0, 1, 0),
			auto = "X",
			gap = theme.space.xxs,
			layoutOrder = 3,
		})

		if compact then
			local menuButton = P.iconButton(right, {
				name = "Nav",
				icon = "bars",
				diameter = theme.size.control,
				layoutOrder = 1,
			})
			menuButton.instance.LayoutOrder = 1
			menuButton.instance.Activated:Connect(function()
				local options = {}
				for _, entry in ipairs(PANELS) do
					options[#options + 1] = {
						label = entry.label,
						value = entry.id,
						selected = entry.id == M.panel,
					}
				end
				overlay.menu({
					target = menuButton.instance,
					width = 200,
					options = options,
					onSelect = function(value) M.show(value) end,
				})
			end)
		else
			M.nav = C.segmented(right, {
				name = "Nav",
				-- An explicit width, passed in rather than assigned afterwards: `right`
				-- sizes itself to its contents, and a scale-width child contributes
				-- nothing to that, so the nav would collapse to zero without it. Doing
				-- it here means the control also keeps the hit-target height it works
				-- out for the platform.
				width = 360,
				options = PANELS and (function()
					local options = {}
					for _, entry in ipairs(PANELS) do
						options[#options + 1] = { value = entry.id, label = entry.label }
					end
					return options
				end)() or {},
				value = M.panel,
				onChange = function(value) M.show(value) end,
			})
			M.nav.instance.LayoutOrder = 1
		end

		if responsive.mode == "window" then
			local maximise = P.iconButton(right, {
				name = "Maximise",
				icon = M.window.maximised and "minus" or "plus",
				diameter = theme.size.control,
				layoutOrder = 2,
			})
			maximise.instance.LayoutOrder = 2
			maximise.instance.Activated:Connect(function()
				M.window.toggleMaximised()
				M.rebuild("maximise")
			end)
		end

		local close = P.iconButton(right, {
			name = "Close",
			icon = "close",
			diameter = theme.size.control,
			layoutOrder = 3,
			onClick = function() M.hide() end,
		})
		close.instance.LayoutOrder = 3
	end

	-- Content stops widening past this; the window itself does not. Past roughly this
	-- width a transcript line or a log row becomes a single sentence a foot long,
	-- which is unreadable however correct the layout is, and a maximised window at
	-- 1920 is mostly that. The chrome still spans the full width -- it is the reading
	-- column that is measured, and the leftover becomes margin.
	local MAX_CONTENT = 1320

	function M.buildBody()
		M.body = P.frame(M.window.body, {
			name = "Panels",
			size = UDim2.fromScale(1, 1),
			maxSize = Vector2.new(MAX_CONTENT, math.huge),
			anchor = Vector2.new(0.5, 0),
			position = UDim2.fromScale(0.5, 0),
		})
		M.panels = {}
		M.showPanel(M.panel)
	end

	-- Panels -----------------------------------------------------------------

	local function buildChatPanel(parent)
		local panel = {}
		local column = P.column(parent, {
			name = "Chat",
			size = UDim2.fromScale(1, 1),
			gap = 0,
		})

		panel.todos = env.require("ui/chat/todo").new(column, { layoutOrder = 1 })

		local middle = P.frame(column, {
			name = "TranscriptHolder",
			size = UDim2.new(1, 0, 1, 0),
			layoutOrder = 2,
		})
		local flex = Instance.new("UIFlexItem", middle)
		flex.FlexMode = Enum.UIFlexMode.Fill

		panel.view = env.require("ui/chat/view").new(middle, {})

		panel.composer = env.require("ui/chat/composer").new(column, {
			layoutOrder = 3,
			onSend = function(text)
				local session = sessions.current()
				local ok, reason = session.send(text)
				if not ok then overlay.toast(tostring(reason), "warn", 2) end
			end,
			onStop = function()
				sessions.current().abort()
			end,
			onClear = function()
				overlay.confirm({
					title = "Clear this conversation?",
					description = "The transcript and the model's context are both discarded.",
					confirmText = "Clear",
					onConfirm = function() sessions.current().clear() end,
				})
			end,
		})
		panel.composer.shell.LayoutOrder = 3

		function panel.destroy()
			if panel.view then panel.view.destroy() end
			if panel.todos then panel.todos.destroy() end
		end

		return panel
	end

	local BUILDERS = {
		chat = buildChatPanel,
		providers = function(parent) return env.require("ui/panels/providers").new(parent) end,
		tools = function(parent) return env.require("ui/panels/tools").new(parent) end,
		settings = function(parent) return env.require("ui/panels/settings").new(parent) end,
		logs = function(parent) return env.require("ui/panels/logs").new(parent) end,
	}

	function M.showPanel(id)
		if not M.body then return end
		for key, panel in pairs(M.panels or {}) do
			if panel.root then panel.root.Visible = key == id end
		end
		if not M.panels[id] then
			local holder = P.frame(M.body, {
				name = "Panel_" .. id,
				size = UDim2.fromScale(1, 1),
			})
			local ok, panel = pcall(BUILDERS[id] or BUILDERS.chat, holder)
			if not ok then
				log.error("app", "panel '" .. id .. "' failed to build", panel)
				holder:Destroy()
				return
			end
			panel.root = holder
			M.panels[id] = panel
			if id == "chat" then M.chatPanel = panel end
		end
		M.panels[id].root.Visible = true
		M.panel = id
		config.set("ui.panel", id, { quiet = true })
		if id == "chat" then M.attachSession() end
		M.syncNav()
	end

	function M.show(id)
		if not M.screen then M.mount() end
		M.showPanel(id or M.panel)
		M.window.show()
		M.setLauncherBusy(false)
	end

	function M.hide()
		if M.window then M.window.hide() end
	end

	function M.toggle()
		if M.window and M.window.visible then M.hide() else M.show() end
	end

	function M.syncNav()
		if M.nav and M.nav.set then M.nav.set(M.panel) end
		M.syncChip()
	end

	function M.syncChip()
		if not M.chip then return end
		local record = providers.active()
		if not record then
			M.chip.label.Text = "no provider"
			M.chip.dot.BackgroundColor3 = theme.color.danger
			return
		end
		local session = sessions.current()
		M.chip.label.Text = string.format("%s  %s", record.label,
			record.model ~= "" and record.model or "no model")
		M.chip.dot.BackgroundColor3 = session.busy and theme.color.accent
			or (providers.cooling(record) and theme.color.warn or theme.color.success)
	end

	-- Picks a provider, or a model within the active one. Both live behind the same
	-- chip because they are the same decision from the user's point of view. Models
	-- listed here are the ones the endpoint reported plus the ones the user added --
	-- never a guess, so the menu can legitimately be empty until one of those has
	-- happened.
	function M.providerMenu(target)
		local options = {}
		local record = providers.active()
		for _, entry in ipairs(providers.list()) do
			options[#options + 1] = {
				label = entry.label,
				value = "provider:" .. entry.id,
				detail = entry.model ~= "" and entry.model or entry.baseUrl,
				selected = record and record.id == entry.id,
			}
		end
		if record then
			local known = models.list(record)
			for _, id in ipairs(known) do
				-- The window is the one thing about a model worth reading at a glance,
				-- and no endpoint publishes it -- so where it is known, it rides on the
				-- label. The value stays the bare id, which is what goes on the wire.
				local badge = traits.badge(id)
				options[#options + 1] = {
					label = badge and (id .. " (" .. badge .. ")") or id,
					value = "model:" .. id,
					detail = "model on " .. record.label,
					selected = id == record.model,
				}
			end
			options[#options + 1] = {
				label = "Fetch models from /models",
				value = "fetch",
				detail = record.baseUrl .. "/models",
				tone = "info",
			}
			options[#options + 1] = { label = "Add a model by id", value = "addmodel", tone = "info" }
		end
		options[#options + 1] = { label = "Manage providers", value = "manage", tone = "info" }

		overlay.menu({
			target = target,
			width = 320,
			options = options,
			onSelect = function(value)
				if value == "manage" then
					M.show("providers")
				elseif value == "fetch" and record then
					overlay.toast("Fetching models from " .. record.label, "info", 2)
					task.spawn(function()
						local found, note = models.discover(record, { force = true })
						overlay.toast(tostring(note), #found > 0 and "good" or "warn")
						if #found > 0 then M.providerMenu(target) end
					end)
				elseif value == "addmodel" and record then
					overlay.prompt({
						title = "Add a model to " .. record.label,
						description = "Type the id exactly as the provider expects it. It is saved to this provider and selected.",
						placeholder = "model id",
						onConfirm = function(text)
							local ok, result = models.add(record, text)
							if ok then
								overlay.toast("Using " .. tostring(result), "good")
								M.syncChip()
							else
								overlay.toast(tostring(result), "warn")
							end
						end,
					})
				elseif util.startsWith(value, "provider:") then
					providers.setActive(value:sub(10))
					M.syncChip()
				elseif util.startsWith(value, "model:") and record then
					providers.setModel(record.id, value:sub(7))
					M.syncChip()
				end
			end,
		})
	end

	-- Session wiring ---------------------------------------------------------

	function M.attachSession()
		local session = sessions.current()
		if M.chatPanel and M.chatPanel.view then M.chatPanel.view.attach(session) end
		env.require("ui/panels/permission").attach(session)

		if M.sessionUnsubscribe then M.sessionUnsubscribe() end
		M.sessionUnsubscribe = session.events:connect(function(event)
			local panel = M.chatPanel
			if event.kind == "status" then
				if panel and panel.composer then
					panel.composer.setStatus(event.text ~= "Ready" and event.text or usage.line())
					panel.composer.setBusy(session.busy)
				end
				M.syncChip()
			elseif event.kind == "turn:end" or event.kind == "error" or event.kind == "abort" then
				if panel and panel.composer then
					panel.composer.setBusy(false)
					panel.composer.setStatus(usage.line())
				end
				M.syncChip()
				-- A finished turn while the window is closed is worth a hint.
				if not M.window.visible then
					M.setLauncherBusy(true)
				end
			elseif event.kind == "usage" then
				if panel and panel.composer and not session.busy then
					panel.composer.setStatus(usage.line())
				end
			end
		end)

		if M.chatPanel and M.chatPanel.composer then
			M.chatPanel.composer.setBusy(session.busy)
			M.chatPanel.composer.setStatus(usage.line())
		end
	end

	-- Rebuild ----------------------------------------------------------------

	-- Throws the tree away and builds it again for the current mode and tokens.
	-- Cheap enough to be the answer to every discrete change, and it means no
	-- component has to know how to re-theme itself in place.
	function M.rebuild(reason)
		if not M.screen then return end
		local wasVisible = M.window and M.window.visible
		local panel = M.panel

		if M.sessionUnsubscribe then
			M.sessionUnsubscribe()
			M.sessionUnsubscribe = nil
		end
		for _, existing in pairs(M.panels or {}) do
			if existing.destroy then pcall(existing.destroy) end
		end
		M.panels = {}
		M.chatPanel = nil
		M.nav = nil
		M.chip = nil
		if M.window then M.window.destroy() end
		if M.launcher then
			M.launcher:Destroy()
			M.launcher = nil
		end

		M.panel = panel
		M.buildLauncher()
		M.buildWindow()
		if wasVisible then M.window.show() end
		log.debug("app", "rebuilt for " .. tostring(reason) .. " as " .. responsive.mode)
	end

	return M
end
end)()

-- ==========================================================================
-- ui/chat/composer
-- ==========================================================================
__UAI_MODULES["ui/chat/composer"] = (function()
-- The composer: prompt field, send/stop, and the row of affordances under it.
--
-- Send behaviour differs by platform on purpose. With a keyboard, Enter sends --
-- that is what everyone expects and reaching for a button breaks the typing rhythm.
-- On touch there is no Enter worth the name, so the button is the primary action and
-- the field grows instead. The expand toggle switches to a multi-line field where
-- Enter inserts a newline and only the button sends.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local icons = env.require("ui/icons")
	local P = env.require("ui/primitives")
	local C = env.require("ui/controls")

	local M = {}

	function M.new(parent, props)
		props = props or {}

		-- The shell is left bare so the rule can reach both edges; the padding lives on
		-- the content column below it. A UIListLayout owns the position of every child
		-- it is given, so a rule that anchored itself to the top edge would be moved
		-- off that edge and become a layout row regardless -- better to be one on
		-- purpose, in a stack with no gap, than to be one by accident.
		local shell = P.column(parent, {
			name = "Composer",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			bg = theme.color.surface,
			gap = 0,
			zIndex = theme.z.raised,
		})
		P.frame(shell, {
			name = "TopRule",
			size = UDim2.new(1, 0, 0, 1),
			bg = theme.color.borderSubtle,
			layoutOrder = 1,
		})
		local content = P.column(shell, {
			name = "Content",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.xs,
			padding = { x = theme.space.md, top = theme.space.sm, bottom = theme.space.sm },
			layoutOrder = 2,
		})

		local composer = { expanded = false, busy = false }

		local inputRow = P.row(content, {
			name = "InputRow",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.xs,
			alignY = "Bottom",
			layoutOrder = 1,
		})

		local fieldHolder = P.frame(inputRow, {
			name = "FieldHolder",
			-- Fills rather than reserving control + xs: the send button is sized to
			-- max(control, minTarget()), which is 44 on touch, so the reserve came up
			-- twelve pixels short on exactly the platform the minimum is there for.
			size = UDim2.new(0, 0, 0, 0),
			auto = "Y",
			flex = "Fill",
			layoutOrder = 1,
		})

		local function submit()
			local text = util.trim(composer.field.get())
			if text == "" then return end
			composer.field.clear()
			if props.onSend then props.onSend(text) end
		end

		composer.field = P.field(fieldHolder, {
			name = "Prompt",
			placeholder = props.placeholder or "Ask, or tell it what to change",
			multiline = false,
			onSubmit = function()
				if not composer.expanded then submit() end
			end,
		})

		local sendButton = P.iconButton(inputRow, {
			name = "Send",
			icon = "send",
			variant = "primary",
			diameter = theme.size.control,
			layoutOrder = 2,
			onClick = function()
				if composer.busy then
					if props.onStop then props.onStop() end
				else
					submit()
				end
			end,
		})
		sendButton.instance.LayoutOrder = 2

		-- The affordance row below carries the things a user needs occasionally: how
		-- the model will be reached, what mode permissions are in, and the two
		-- toggles that change how much the transcript shows.
		local metaRow = P.row(content, {
			name = "Meta",
			size = UDim2.new(1, 0, 0, theme.text.caption.size + 8),
			gap = theme.space.xs,
			layoutOrder = 2,
		})

		local statusLabel = P.text(metaRow, {
			text = "",
			role = "caption",
			color = theme.color.textTertiary,
			truncate = true,
			layoutOrder = 1,
		})
		statusLabel.Size = UDim2.new(1, -140, 1, 0)

		local expandButton = P.button(metaRow, {
			name = "Expand",
			text = "multiline",
			variant = "ghost",
			size = "sm",
			tight = true,
			layoutOrder = 2,
			onClick = function()
				composer.setExpanded(not composer.expanded)
			end,
		})
		expandButton.instance.LayoutOrder = 2

		local clearButton = P.button(metaRow, {
			name = "Clear",
			text = "clear",
			variant = "ghost",
			size = "sm",
			tight = true,
			layoutOrder = 3,
			onClick = function()
				if props.onClear then props.onClear() end
			end,
		})
		clearButton.instance.LayoutOrder = 3

		-- Rebuilding the field is the honest way to switch MultiLine: changing the
		-- property on a live TextBox leaves its alignment and height wrong.
		function composer.setExpanded(value)
			composer.expanded = value == true
			local carried = composer.field.get()
			pcall(function() composer.field.shell:Destroy() end)
			composer.field = P.field(fieldHolder, {
				name = "Prompt",
				placeholder = props.placeholder or "Ask, or tell it what to change",
				multiline = composer.expanded,
				height = composer.expanded and (theme.size.control * 3) or nil,
				text = carried,
				onSubmit = function()
					if not composer.expanded then submit() end
				end,
			})
			expandButton.setText(composer.expanded and "single line" or "multiline")
		end

		function composer.setBusy(value)
			composer.busy = value == true
			-- ClearAllChildren would take the UICorner that P.button attached along
			-- with the icon, and since this runs once at build time that is why the
			-- send button has been square from the moment it existed. Only the drawn
			-- content is replaced.
			for _, child in ipairs(sendButton.instance:GetChildren()) do
				if child:IsA("GuiObject") then child:Destroy() end
			end
			-- The primary action becomes Stop while a turn is running, in place
			-- rather than as a second control, so there is only ever one thing to
			-- press.
			local content = P.row(sendButton.instance, {
				size = UDim2.fromScale(1, 1),
				alignX = "Center",
			})
			local holder = P.frame(content, {
				size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
			})
			if composer.pulse then
				pcall(function() composer.pulse:Cancel() end)
				composer.pulse = nil
			end
			if composer.busy then
				icons.stop(holder, theme.size.icon, theme.color.textOnAccent)
				-- setVariant tweens the background over 0.12s, so assigning
				-- BackgroundColor3 here as well only started a race the tween won.
				sendButton.setVariant("danger")
				-- A breathing outline. It is the one piece of motion visible with the
				-- transcript scrolled away, which is where a long turn is usually spent.
				if not responsive.reduceMotion then
					composer.busyStroke = composer.busyStroke
						or P.stroke(sendButton.instance, theme.color.danger, theme.stroke.focus)
					composer.busyStroke.Color = theme.color.danger
					composer.busyStroke.Transparency = 0.7
					composer.pulse = env.tween:Create(composer.busyStroke, theme.motion.pulse,
						{ Transparency = 0.05 })
					composer.pulse:Play()
				end
			else
				icons.send(holder, theme.size.icon, theme.color.textOnAccent)
				sendButton.setVariant("primary")
				if composer.busyStroke then composer.busyStroke.Transparency = 1 end
			end
		end

		function composer.setStatus(text)
			statusLabel.Text = tostring(text or "")
		end

		function composer.focus()
			composer.field.focus()
		end

		-- The keyboard covering the field is the classic mobile bug. The window moves
		-- itself; this only has to stop showing the meta row when there is no height
		-- left for it.
		responsive.changed:connect(function()
			metaRow.Visible = not responsive.isCompactHeight()
		end)
		metaRow.Visible = not responsive.isCompactHeight()

		composer.shell = shell
		composer.setBusy(false)
		return composer
	end

	return M
end
end)()

-- ==========================================================================
-- ui/chat/message
-- ==========================================================================
__UAI_MODULES["ui/chat/message"] = (function()
-- Transcript message renderers.
--
-- Each kind of thing that can appear in a conversation gets its own builder, and
-- each returns a handle so the view can update it later -- a tool call is created
-- when the model asks for it and completed when the result arrives, which means the
-- row has to be mutable rather than a one-shot render.
return function(env)
	local util = env.require("runtime/util")
	local clock = env.require("runtime/clock")
	local config = env.require("runtime/config")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local markdown = env.require("ui/markdown")
	local icons = env.require("ui/icons")
	local P = env.require("ui/primitives")
	local C = env.require("ui/controls")
	local usage = env.require("agent/usage")

	local CODE_LINES = 40
	local ARG_PREVIEW = 90

	local M = {}

	-- Bubble width. A message that reaches the far edge reads as a wall; leaving a
	-- gutter on the opposite side is what makes the two speakers legible as a
	-- conversation. The agent gets more room than the user because its replies are
	-- longer and often contain code.
	local function widthFor(kind)
		if responsive.mode == "sheet" then
			return kind == "user" and 0.86 or 0.96
		end
		return kind == "user" and 0.76 or 0.94
	end

	local function wrapper(parent, props)
		return P.frame(parent, {
			name = props.name or "Message",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			layoutOrder = props.layoutOrder or 0,
		})
	end

	-- Code block: monospace on the darkest surface, with the language and a copy
	-- control. Over-long blocks are cut with an explicit count rather than silently.
	function M.codeBlock(parent, props)
		local caps = env.require("runtime/caps")
		local lines = util.lines(props.text)
		local shown = lines
		local omitted = 0
		if #lines > CODE_LINES then
			shown = util.slice(lines, 1, CODE_LINES)
			omitted = #lines - CODE_LINES
		end

		local card = P.column(parent, {
			name = "Code",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			bg = theme.color.codeSurface,
			radius = theme.radius.md,
			gap = 0,
			layoutOrder = props.layoutOrder,
			clip = true,
		})
		P.stroke(card, theme.color.codeBorder)

		local bar = P.row(card, {
			name = "Bar",
			size = UDim2.new(1, 0, 0, theme.size.controlSmall),
			bg = theme.color.surfaceRaised,
			gap = theme.space.xs,
			padding = { x = theme.space.sm },
			layoutOrder = 1,
		})
		local label = P.text(bar, {
			text = (props.lang and props.lang:lower() or "code") .. (props.unterminated and " (incomplete)" or ""),
			role = "caption",
			color = theme.color.textTertiary,
			-- Fills rather than reserving controlSmall: the copy button is sized to
			-- max(controlSmall, minTarget()), which is 44 on touch, so the reserve was
			-- twelve pixels short on exactly the platform the minimum exists for.
			size = UDim2.new(0, 0, 1, 0),
			flex = "Fill",
			layoutOrder = 1,
		})

		if caps.clipboard then
			local copy = P.iconButton(bar, {
				name = "Copy",
				icon = "copy",
				diameter = theme.size.controlSmall,
				variant = "ghost",
				layoutOrder = 2,
				onClick = function(handle)
					pcall(caps.fn.clipboard, props.text)
					env.require("ui/overlay").toast("Copied to clipboard", "good", 2)
				end,
			})
			copy.instance.LayoutOrder = 2
		end

		local body = P.text(card, {
			text = table.concat(shown, "\n"),
			role = "mono",
			color = theme.color.text,
			wrap = true,
			auto = "Y",
			alignY = "Top",
			layoutOrder = 2,
			padding = { x = theme.space.md, y = theme.space.sm },
		})
		body.Size = UDim2.new(1, 0, 0, 0)

		if omitted > 0 then
			P.text(card, {
				text = string.format("%d more line%s not shown", omitted, omitted == 1 and "" or "s"),
				role = "caption",
				color = theme.color.textTertiary,
				layoutOrder = 3,
				padding = { x = theme.space.md, bottom = theme.space.sm },
				auto = "Y",
			})
		end

		return card
	end

	-- Renders markdown blocks into an existing column. Returned so a streaming or
	-- edited message can clear and re-render.
	function M.renderBlocks(column, text)
		for _, child in ipairs(column:GetChildren()) do
			if not child:IsA("UIListLayout") and not child:IsA("UIPadding") then child:Destroy() end
		end

		local blocks = markdown.blocks(text)
		if #blocks == 0 then
			P.text(column, { text = "", role = "body", wrap = true, auto = "Y" })
			return
		end

		for index, block in ipairs(blocks) do
			if block.kind == "code" then
				M.codeBlock(column, {
					text = block.text,
					lang = block.lang,
					unterminated = block.unterminated,
					layoutOrder = index,
				})
			elseif block.kind == "heading" then
				local label = P.text(column, {
					text = markdown.inline(block.text),
					role = block.level == 1 and "title" or "heading",
					rich = true,
					wrap = true,
					auto = "Y",
					layoutOrder = index,
				})
				label.Size = UDim2.new(1, 0, 0, 0)
			elseif block.kind == "rule" then
				P.divider(column, { layoutOrder = index })
			elseif block.kind == "bullets" then
				local list = P.column(column, {
					size = UDim2.new(1, 0, 0, 0),
					auto = "Y",
					gap = theme.space.xxs,
					layoutOrder = index,
				})
				for position, item in ipairs(block.items) do
					local row = P.row(list, {
						size = UDim2.new(1, 0, 0, 0),
						auto = "Y",
						gap = theme.space.xs,
						alignY = "Top",
						layoutOrder = position,
					})
					local dot = P.frame(row, {
						size = UDim2.fromOffset(theme.space.sm, theme.text.body.size + 2),
						layoutOrder = 1,
					})
					P.statusDot(dot, {
						diameter = 4,
						color = theme.color.textTertiary,
						anchor = Vector2.new(0.5, 0.5),
						position = UDim2.fromScale(0.5, 0.5),
					})
					local text = P.text(row, {
						text = markdown.inline(item),
						role = "body",
						rich = true,
						wrap = true,
						auto = "Y",
						layoutOrder = 2,
					})
					text.Size = UDim2.new(1, -(theme.space.sm + theme.space.xs), 0, 0)
				end
			else
				local label = P.text(column, {
					text = markdown.inline(block.text),
					role = "body",
					rich = true,
					wrap = true,
					auto = "Y",
					layoutOrder = index,
				})
				label.Size = UDim2.new(1, 0, 0, 0)
			end
		end
	end

	function M.user(parent, text, order)
		local holder = wrapper(parent, { name = "User", layoutOrder = order })
		local bubble = P.column(holder, {
			name = "Bubble",
			size = UDim2.new(widthFor("user"), 0, 0, 0),
			auto = "Y",
			anchor = Vector2.new(1, 0),
			position = UDim2.fromScale(1, 0),
			bg = theme.color.bubbleUser,
			radius = theme.radius.lg,
			gap = theme.space.xxs,
			padding = { x = theme.space.md, y = theme.space.sm },
		})
		P.stroke(bubble, theme.color.bubbleUserBorder)
		local label = P.text(bubble, {
			text = tostring(text),
			role = "body",
			wrap = true,
			auto = "Y",
		})
		label.Size = UDim2.new(1, 0, 0, 0)
		return { root = holder, label = label }
	end

	function M.agent(parent, text, order)
		local holder = wrapper(parent, { name = "Agent", layoutOrder = order })
		local column = P.column(holder, {
			name = "Body",
			size = UDim2.new(widthFor("agent"), 0, 0, 0),
			auto = "Y",
			-- Paragraphs need more than eight pixels between them or a long reply
			-- arrives as one grey slab with no shape to it.
			gap = theme.space.md,
		})
		local handle = { root = holder, column = column }
		function handle.setText(value)
			M.renderBlocks(column, value)
		end
		handle.setText(text or "")
		return handle
	end

	-- Reasoning is collapsed by default: it is interesting once and noise
	-- afterwards, and on a phone it would push the answer off screen.
	function M.reasoning(parent, text, order)
		local holder = wrapper(parent, { name = "Reasoning", layoutOrder = order })
		local card = P.column(holder, {
			size = UDim2.new(widthFor("agent"), 0, 0, 0),
			auto = "Y",
			bg = theme.color.surface,
			radius = theme.radius.md,
			gap = theme.space.xs,
			padding = { x = theme.space.sm, y = theme.space.xs },
		})
		P.stroke(card, theme.color.borderSubtle)

		local header = Instance.new("TextButton", card)
		header.Text = ""
		header.AutoButtonColor = false
		header.BackgroundTransparency = 1
		header.Size = UDim2.new(1, 0, 0, theme.text.label.size + 6)
		header.LayoutOrder = 1
		header.Selectable = true

		local row = P.row(header, { size = UDim2.fromScale(1, 1), gap = theme.space.xs })
		local caret = P.frame(row, {
			size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
			layoutOrder = 1,
		})
		icons.chevron(caret, theme.size.icon, theme.color.textTertiary, "right")
		local title = P.text(row, {
			text = "reasoning",
			role = "label",
			color = theme.color.textTertiary,
			size = UDim2.new(0, 0, 1, 0),
			flex = "Fill",
			layoutOrder = 2,
		})
		-- How much of it there is, in the unit it is billed in. A card that says only
		-- "reasoning" gives no grounds for opening it or for leaving it shut, and this
		-- is the one part of a turn whose size is otherwise invisible: reasoning is
		-- charged as output and never appears in the reply.
		P.text(row, {
			text = "~" .. util.formatNumber(usage.estimateText(text)) .. " tokens",
			role = "caption",
			color = theme.color.textTertiary,
			align = "Right",
			auto = "X",
			layoutOrder = 3,
		})

		local body = P.text(card, {
			text = markdown.plain(text),
			role = "small",
			color = theme.color.textSecondary,
			wrap = true,
			auto = "Y",
			layoutOrder = 2,
		})
		body.Size = UDim2.new(1, 0, 0, 0)

		-- Open on arrival. The thinking is what explains the answer, and a card that
		-- hides it by default reads as though there were nothing inside; the header
		-- still folds a long one away once it has been read.
		local open = true
		caret.Rotation = 90
		local function toggle()
			open = not open
			body.Visible = open
			caret.Rotation = open and 90 or 0
		end
		header.Activated:Connect(toggle)
		-- The wrapper, not the card: hiding the card alone left its frame in the list
		-- layout, so a hidden reasoning row still pushed the reply down by its padding.
		if config.get("ui.showReasoning", true) == false then holder.Visible = false end

		return { root = holder, body = body }
	end

	-- A tool call row: risk dot, name, argument preview, timing, and an expandable
	-- detail pane holding the full arguments and the result.
	function M.toolCall(parent, info, order)
		local holder = wrapper(parent, { name = "Tool", layoutOrder = order })
		local card = P.column(holder, {
			size = UDim2.new(widthFor("agent"), 0, 0, 0),
			auto = "Y",
			bg = theme.color.bubbleTool,
			radius = theme.radius.md,
			gap = 0,
			clip = true,
		})
		P.stroke(card, theme.color.borderSubtle)

		local header = Instance.new("TextButton", card)
		header.Text = ""
		header.AutoButtonColor = false
		header.BackgroundTransparency = 1
		header.Size = UDim2.new(1, 0, 0, math.max(theme.size.row - 4, responsive.minTarget() - 8))
		header.LayoutOrder = 1
		header.Selectable = true

		local row = P.row(header, {
			size = UDim2.fromScale(1, 1),
			gap = theme.space.xs,
			padding = { x = theme.space.sm },
		})

		local spinner = C.spinner(row, { diameter = theme.size.icon - 2, layoutOrder = 1 })
		local dot = P.statusDot(row, {
			color = theme.riskColor(info.risk),
			diameter = 7,
			layoutOrder = 1,
		})
		dot.Visible = false

		local name = P.text(row, {
			text = tostring(info.name or "tool"),
			role = "monoSmall",
			color = theme.color.text,
			layoutOrder = 2,
		})
		name.Size = UDim2.fromOffset(0, theme.text.monoSmall.size + 4)
		name.AutomaticSize = Enum.AutomaticSize.X

		local preview = P.text(row, {
			text = util.ellipsis(tostring(info.arguments or ""):gsub("[\n\r]", " "), ARG_PREVIEW),
			role = "caption",
			color = theme.color.textTertiary,
			truncate = true,
			-- Takes whatever is left rather than reserving a guess. The guess was
			-- icon + 90, but the row also has to fit an auto-width tool name, so it
			-- over-committed by the width of that name and pushed `timing` out past
			-- the card's clip -- which is why a tool call never showed how long it took.
			size = UDim2.new(0, 0, 1, 0),
			flex = "Fill",
			layoutOrder = 3,
		})

		local timing = P.text(row, {
			text = "",
			role = "caption",
			color = theme.color.textTertiary,
			align = "Right",
			layoutOrder = 4,
		})
		timing.Size = UDim2.fromOffset(52, theme.text.caption.size + 4)

		local detail = P.column(card, {
			name = "Detail",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.xs,
			padding = { x = theme.space.sm, bottom = theme.space.sm },
			layoutOrder = 2,
			visible = config.get("ui.showToolDetail", false) == true,
		})

		local argsLabel = P.text(detail, {
			text = "arguments\n" .. tostring(info.arguments or "{}"),
			role = "monoSmall",
			color = theme.color.textTertiary,
			wrap = true,
			auto = "Y",
			layoutOrder = 1,
		})
		argsLabel.Size = UDim2.new(1, 0, 0, 0)

		local resultLabel = P.text(detail, {
			text = "",
			role = "monoSmall",
			color = theme.color.textSecondary,
			wrap = true,
			auto = "Y",
			layoutOrder = 3,
			visible = false,
		})
		resultLabel.Size = UDim2.new(1, 0, 0, 0)

		local open = detail.Visible
		header.Activated:Connect(function()
			open = not open
			detail.Visible = open
		end)

		local handle = { root = holder, card = card }
		local nested

		-- Where a tool that runs an agent of its own puts its live feed. Sits between the
		-- arguments and the result, which is the order it happens in, and forces the
		-- detail pane open: a row with something moving inside it should not be the one
		-- thing hiding it.
		function handle.nest()
			if not nested then
				nested = P.column(detail, {
					name = "Nested",
					size = UDim2.new(1, 0, 0, 0),
					auto = "Y",
					gap = theme.space.xs,
					layoutOrder = 2,
				})
			end
			open = true
			detail.Visible = true
			return nested
		end

		function handle.progress(text)
			preview.Text = util.ellipsis(tostring(text), ARG_PREVIEW)
		end

		function handle.finish(result)
			spinner:Destroy()
			dot.Visible = true
			if result.ok then
				dot.BackgroundColor3 = theme.riskColor(info.risk)
			else
				dot.BackgroundColor3 = result.denied and theme.color.warn or theme.color.danger
			end
			timing.Text = result.ms and util.formatDuration(result.ms) or ""
			local text = tostring(result.text or "")
			preview.Text = util.ellipsis(text:gsub("[\n\r]+", " "), ARG_PREVIEW)
			preview.TextColor3 = result.ok and theme.color.textTertiary or theme.color.danger
			resultLabel.Text = "result\n" .. text
			resultLabel.Visible = true
			if result.truncated then
				resultLabel.Text = resultLabel.Text .. "\n[result was trimmed before the model saw it]"
			end
		end

		return handle
	end

	-- A subagent's live feed.
	--
	-- The parent pays for one paragraph of report, but the user should still be able to
	-- watch the work. From outside, a delegated task is a spinner on a row that says
	-- nothing, which is indistinguishable from a hang -- and three of them at once are
	-- indistinguishable from each other. So each dispatch gets a card that fills in as
	-- its child works: every tool it calls, what it said between calls, the report at
	-- the end.
	--
	-- Driven by events forwarded onto the parent's stream rather than by reaching into
	-- the child session, so it replays from the log like every other row. Switching
	-- panel mid-dispatch and coming back shows the same feed, not an empty box.
	function M.subagent(parent, info, order, opts)
		opts = opts or {}
		local holder = wrapper(parent, { name = "Subagent", layoutOrder = order })
		local card = P.column(holder, {
			size = opts.nested and UDim2.new(1, 0, 0, 0) or UDim2.new(widthFor("agent"), 0, 0, 0),
			auto = "Y",
			bg = opts.nested and theme.color.surface or theme.color.bubbleTool,
			radius = theme.radius.md,
			gap = 0,
			clip = true,
		})
		P.stroke(card, theme.color.borderSubtle)

		local header = Instance.new("TextButton", card)
		header.Text = ""
		header.AutoButtonColor = false
		header.BackgroundTransparency = 1
		header.Size = UDim2.new(1, 0, 0, math.max(theme.size.row - 4, responsive.minTarget() - 8))
		header.LayoutOrder = 1
		header.Selectable = true

		local row = P.row(header, {
			size = UDim2.fromScale(1, 1),
			gap = theme.space.xs,
			padding = { x = theme.space.sm },
		})

		local spinner = C.spinner(row, { diameter = theme.size.icon - 2, layoutOrder = 1 })
		local dot = P.statusDot(row, { color = theme.color.accent, diameter = 7, layoutOrder = 1 })
		dot.Visible = false

		local kindLabel = P.text(row, {
			text = "agent",
			role = "monoSmall",
			color = theme.color.accent,
			layoutOrder = 2,
		})
		kindLabel.Size = UDim2.fromOffset(0, theme.text.monoSmall.size + 4)
		kindLabel.AutomaticSize = Enum.AutomaticSize.X
		local title = P.text(row, {
			text = tostring(info.label or "task"),
			role = "caption",
			color = theme.color.textSecondary,
			truncate = true,
			size = UDim2.new(0, 0, 1, 0),
			flex = "Fill",
			layoutOrder = 3,
		})

		local meta = P.text(row, {
			text = "",
			role = "caption",
			color = theme.color.textTertiary,
			align = "Right",
			layoutOrder = 4,
		})
		meta.Size = UDim2.fromOffset(88, theme.text.caption.size + 4)

		local feed = P.column(card, {
			name = "Feed",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.xxs,
			padding = { x = theme.space.sm, bottom = theme.space.sm },
			layoutOrder = 2,
		})

		local status = P.text(feed, {
			text = "Starting",
			role = "caption",
			color = theme.color.textTertiary,
			wrap = true,
			auto = "Y",
			layoutOrder = 1,
		})
		status.Visible = false
		status.Size = UDim2.new(1, 0, 0, 0)

		-- The feed is open while the work happens, which is the whole point of it. The
		-- header still toggles, because a finished subagent's feed is history and a
		-- conversation with six of them in it should be collapsible.
		local open = true
		header.Activated:Connect(function()
			open = not open
			feed.Visible = open
		end)
		local rows = {}
		local slot = 1
		local function nextSlot()
			slot = slot + 1
			return slot
		end

		local function line(text, colour, role)
			local label = P.text(feed, {
				text = tostring(text),
				role = role or "caption",
				color = colour or theme.color.textTertiary,
				wrap = true,
				auto = "Y",
				layoutOrder = nextSlot(),
			})
			label.Size = UDim2.new(1, 0, 0, 0)
			return label
		end

		local started = clock.ms()
		local calls, finished, finalMs = 0, 0, nil

		local function paintMeta()
			local bits = {}
			if calls > 0 then bits[#bits + 1] = string.format("%d/%d", finished, calls) end
			local waited = finalMs or clock.since(started)
			if waited >= 1000 then bits[#bits + 1] = util.formatDuration(waited) end
			meta.Text = table.concat(bits, "  ")
		end

		-- One timer for the clock, stopped when the subagent reports back. Same reason
		-- the working row has one: a number that moves is what separates "this is taking
		-- a while" from "this is stuck", and a subagent takes minutes.
		local stop = clock.interval(0.5, function()
			if not finalMs then paintMeta() end
		end)
		holder.Destroying:Connect(function() pcall(stop) end)
		local handle = { root = holder, card = card }

		function handle.status(event)
			local text = util.trim(tostring(event.text or ""))
			if text == "" or text == "Ready" then return end
			status.Visible = true
			status.Text = text
			status.TextColor3 = event.bad and theme.color.danger or theme.color.textTertiary
		end

		function handle.say(event)
			local text = util.trim(tostring(event.text or ""))
			if text == "" then return end
			line(text, theme.color.textSecondary, "small")
		end

		-- One line per tool the child calls, keyed by the child's own call id so the
		-- result can land on the row that asked for it. The arguments are replaced by a
		-- one-line summary of what came back, which is as much of a subagent's tool
		-- output as belongs in the parent's transcript.
		function handle.tool(event)
			calls = calls + 1
			local toolRow = P.row(feed, {
				size = UDim2.new(1, 0, 0, theme.text.monoSmall.size + 6),
				gap = theme.space.xs,
				layoutOrder = nextSlot(),
			})
			P.statusDot(toolRow, { color = theme.riskColor(event.risk), diameter = 5, layoutOrder = 1 })
			local name = P.text(toolRow, {
				text = tostring(event.name or "tool"),
				role = "monoSmall",
				color = theme.color.textSecondary,
				layoutOrder = 2,
			})
			name.Size = UDim2.fromOffset(0, theme.text.monoSmall.size + 4)
			name.AutomaticSize = Enum.AutomaticSize.X
			local args = P.text(toolRow, {
				text = tostring(event.arguments or ""),
				role = "caption",
				color = theme.color.textTertiary,
				truncate = true,
				size = UDim2.new(0, 0, 1, 0),
				flex = "Fill",
				layoutOrder = 3,
			})
			local timing = P.text(toolRow, {
				text = "",
				role = "caption",
				color = theme.color.textTertiary,
				align = "Right",
				layoutOrder = 4,
			})
			timing.Size = UDim2.fromOffset(46, theme.text.caption.size + 4)
			rows[tostring(event.callId or calls)] = { args = args, timing = timing }
			paintMeta()
		end
		function handle.toolDone(event)
			finished = finished + 1
			local entry = rows[tostring(event.callId or "")]
			if entry then
				entry.timing.Text = event.ms and util.formatDuration(event.ms) or ""
				local summary = util.trim(tostring(event.summary or ""))
				if summary ~= "" then entry.args.Text = summary end
				if not event.ok then entry.args.TextColor3 = theme.color.danger end
			end
			paintMeta()
		end

		function handle.finish(event)
			finalMs = event.ms or clock.since(started)
			pcall(stop)
			pcall(function() spinner:Destroy() end)
			dot.Visible = true
			if event.aborted then
				dot.BackgroundColor3 = theme.color.warn
			elseif event.ok == false then
				dot.BackgroundColor3 = theme.color.danger
			else
				dot.BackgroundColor3 = theme.color.accent
			end
			paintMeta()
			status.Visible = true
