-- the log explains everything else.
return function(env)
	local util = env.require("runtime/util")
	local caps = env.require("runtime/caps")
	local theme = env.require("ui/theme")
	local P = env.require("ui/primitives")
	local C = env.require("ui/controls")
	local overlay = env.require("ui/overlay")
	local http = env.require("net/http")
	local log = env.require("runtime/log")

	local M = {}

	local LEVEL_TONE = { debug = "info", info = "info", warn = "warn", error = "bad" }

	function M.new(parent)
		local panel = { view = "requests" }

		local column = P.column(parent, {
			name = "LogsPanel",
			size = UDim2.new(1, 0, 1, 0),
			gap = 0,
		})

		local head = P.column(column, {
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.sm,
			padding = { x = theme.space.md, top = theme.space.md, bottom = theme.space.sm },
			layoutOrder = 1,
		})

		local tabs
		local scroll
		local function render() end

		tabs = C.segmented(head, {
			options = {
				{ value = "requests", label = "Requests" },
				{ value = "log", label = "Log" },
			},
			value = panel.view,
			onChange = function(value)
				panel.view = value
				render()
			end,
		})

		local actions = P.row(head, { size = UDim2.new(1, 0, 0, 0), auto = "Y", gap = theme.space.xs })
		local countLabel = P.text(actions, {
			text = "",
			role = "caption",
			color = theme.color.textTertiary,
			layoutOrder = 1,
		})
		countLabel.Size = UDim2.fromOffset(0, theme.text.caption.size + 6)
		countLabel.AutomaticSize = Enum.AutomaticSize.X
		-- A growing spacer rather than a hardcoded reserve on the label: the buttons
		-- are auto-width and grow with the text scale, so any fixed number is either
		-- short of the right edge or overlapping them.
		P.spacer(actions, { grow = true, size = UDim2.new(0, 0, 0, 1), layoutOrder = 2 })

		if caps.clipboard then
			local copy = P.button(actions, {
				text = "Copy",
				variant = "ghost",
				size = "sm",
				layoutOrder = 3,
				onClick = function()
					pcall(caps.fn.clipboard, log.export())
					overlay.toast("Log copied", "good", 2)
				end,
			})
			copy.instance.LayoutOrder = 3
		end
		local clear = P.button(actions, {
			text = "Clear",
			variant = "ghost",
			size = "sm",
			layoutOrder = 4,
			onClick = function()
				if panel.view == "requests" then http.clearHistory() else log.clear() end
				render()
			end,
		})
		clear.instance.LayoutOrder = 4

		scroll = P.scroll(column, {
			name = "LogList",
			size = UDim2.new(1, 0, 1, 0),
			-- Tight, because the rows now carry their own banding and padding; a six
			-- pixel gap between banded rows reads as a gap in the data.
			gap = 2,
			padding = { x = theme.space.md, bottom = theme.space.md },
			layoutOrder = 2,
		})
		local flex = Instance.new("UIFlexItem", scroll.instance)
		flex.FlexMode = Enum.UIFlexMode.Fill

		local function requestRow(entry, order)
			local tone = "good"
			if entry.error then
				tone = "bad"
			elseif entry.status >= 400 then
				tone = entry.status == 429 and "warn" or "bad"
			elseif entry.status == 0 then
				tone = "warn"
			end

			local card = P.card(scroll.instance, {
				layoutOrder = order,
				gap = theme.space.xxs,
				padding = theme.space.sm,
			})
			local top = P.row(card, { size = UDim2.new(1, 0, 0, 0), auto = "Y", gap = theme.space.xs })
			P.statusDot(top, { color = theme.toneColor(tone), diameter = 7, layoutOrder = 1 })
			local title = P.text(top, {
				text = string.format("%s %s", entry.method, entry.tag or ""),
				role = "monoSmall",
				-- Fills rather than reserving 150 for a dot and a 96px meta column,
				-- which left thirty-five pixels stranded on every card.
				size = UDim2.new(0, 0, 0, theme.text.monoSmall.height),
				flex = "Fill",
				layoutOrder = 2,
			})
			local meta = P.text(top, {
				text = string.format("%s %s", entry.status > 0 and tostring(entry.status) or "-",
					util.formatDuration(entry.ms or 0)),
				role = "caption",
				color = theme.color.textTertiary,
				align = "Right",
				layoutOrder = 3,
			})
			meta.Size = UDim2.fromOffset(96, theme.text.caption.size + 4)

			local url = P.text(card, {
				text = entry.url,
				role = "caption",
				color = theme.color.textSecondary,
				wrap = true,
				auto = "Y",
			})
			url.Size = UDim2.new(1, 0, 0, 0)

			local bits = {
				entry.via or "?",
				string.format("%s bytes", util.formatNumber(entry.bytes or 0)),
				entry.identity or "claude",
			}
			if entry.identity ~= "none" and not entry.uaSent then
				bits[#bits + 1] = "user-agent dropped by transport"
			end
			if entry.droppedHeaders and #entry.droppedHeaders > 0 then
				bits[#bits + 1] = "dropped: " .. table.concat(entry.droppedHeaders, ", ")
			end
			if entry.attempt and entry.attempt > 1 then
				bits[#bits + 1] = "attempt " .. tostring(entry.attempt)
			end
			-- The evidence for a bodyless refusal. `server` and a trace id say the
			-- response came from an edge rather than from the API, and `cf-mitigated`
			-- says so outright, which is the difference between a key problem and a
			-- filter problem.
			if entry.server then bits[#bits + 1] = "server " .. tostring(entry.server) end
			if entry.mitigated then bits[#bits + 1] = "mitigated " .. tostring(entry.mitigated) end
			if entry.trace then bits[#bits + 1] = tostring(entry.trace) end
			if entry.status >= 400 and (entry.bytes or 0) == 0 then
				bits[#bits + 1] = "empty body"
			end
			local detail = P.text(card, {
				text = table.concat(bits, "  |  "),
				role = "caption",
				color = theme.color.textTertiary,
				wrap = true,
				auto = "Y",
			})
			detail.Size = UDim2.new(1, 0, 0, 0)

			if entry.error then
				local err = P.text(card, {
					text = tostring(entry.error),
					role = "caption",
					color = theme.color.danger,
					wrap = true,
					auto = "Y",
				})
				err.Size = UDim2.new(1, 0, 0, 0)
			end
			return card
		end

		-- Column reserves, named once so the body's remainder cannot drift out of step
		-- with them. They were 58 and 74 for an eight-character timestamp and a
		-- four-letter source, which left about sixty pixels of nothing on every row.
		local STAMP_WIDTH = 46
		local SOURCE_WIDTH = 44
		local DOT_WIDTH = 6

		local function logRow(entry, order)
			local row = P.row(scroll.instance, {
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				gap = theme.space.xs,
				-- Alternating bands, because twenty-four transparent rows four pixels
				-- apart read as one block of text rather than as a table.
				bg = (order % 2 == 0) and theme.color.surfaceRaised or nil,
				radius = theme.radius.sm,
				padding = { x = theme.space.xs, y = 2 },
				-- Top-aligned put the 6px dot's centre four pixels above the text's,
				-- so every dot in the list rode high. The message can wrap to a second
				-- line, so the meta columns are given the row's height and centre their
				-- own text instead.
				alignY = "Top",
				layoutOrder = order,
			})
			-- The dot gets a slot the height of one text line and centres itself in
			-- that, rather than anchoring inside the row: the row is laid out by a
			-- UIListLayout, which owns its children's positions, and a bare 6px dot
			-- against 14px labels rode four pixels high on every line in the list.
			local dotSlot = P.frame(row, {
				name = "Level",
				size = UDim2.fromOffset(DOT_WIDTH, theme.text.caption.size + 4),
				layoutOrder = 1,
			})
			P.statusDot(dotSlot, {
				color = theme.toneColor(LEVEL_TONE[entry.level] or "info"),
				diameter = DOT_WIDTH,
				anchor = Vector2.new(0.5, 0.5),
				position = UDim2.fromScale(0.5, 0.5),
			})
			local stamp = P.text(row, {
				text = entry.stamp or "",
				role = "caption",
				color = theme.color.textTertiary,
				layoutOrder = 2,
			})
			stamp.Size = UDim2.fromOffset(STAMP_WIDTH, theme.text.caption.size + 4)
			local source = P.text(row, {
				text = entry.source,
				role = "caption",
				color = theme.color.textTertiary,
				layoutOrder = 3,
				truncate = true,
			})
			source.Size = UDim2.fromOffset(SOURCE_WIDTH, theme.text.caption.size + 4)
			local body = P.text(row, {
				text = entry.message .. (entry.detail and ("  " .. entry.detail) or ""),
				role = "monoSmall",
				color = entry.level == "error" and theme.color.danger or theme.color.textSecondary,
				wrap = true,
				auto = "Y",
				layoutOrder = 4,
			})
			body.Size = UDim2.new(1, -(STAMP_WIDTH + SOURCE_WIDTH + DOT_WIDTH + theme.space.xs * 3), 0, 0)
			return row
		end

		render = function()
			scroll.clear()
			if panel.view == "requests" then
				local entries = util.reverse(http.history)
				countLabel.Text = util.pluralise(#entries, "request") .. " kept"
				if #entries == 0 then
					C.emptyState(scroll.instance, {
						title = "No requests yet",
						description = "Every outbound call lands here with its status, timing and whether the client identity made it onto the wire.",
						layoutOrder = 1,
					})
					return
				end
				for index, entry in ipairs(entries) do requestRow(entry, index) end
			else
				local entries = util.reverse(log.entries)
				countLabel.Text = util.pluralise(#entries, "line") .. " kept"
				if #entries == 0 then
					C.emptyState(scroll.instance, { title = "Log is empty", layoutOrder = 1 })
					return
				end
				for index, entry in ipairs(entries) do logRow(entry, index) end
			end
		end

		render()
		panel.refresh = render
		-- Live, but throttled: a burst of log lines must not rebuild the list per
		-- line while the user is reading it.
		local clock = env.require("runtime/clock")
		local throttled = clock.throttle(render, 0.4)
		panel.unsubscribeLog = log.changed:connect(function()
			if panel.view == "log" then throttled() end
		end)
		panel.unsubscribeHttp = http.changed:connect(function()
			if panel.view == "requests" then throttled() end
		end)
		return panel
	end

	return M
end
end)()

-- ==========================================================================
-- ui/panels/permission
-- ==========================================================================
__UAI_MODULES["ui/panels/permission"] = (function()
-- The permission prompt.
--
-- The loop blocks on a thread while this is open, so it has to be reliable: one
-- prompt at a time, queued, and always resolved -- closing it counts as a refusal.
-- An unresolved prompt would park the agent until its own timeout.
return function(env)
	local util = env.require("runtime/util")
	local theme = env.require("ui/theme")
	local P = env.require("ui/primitives")
	local C = env.require("ui/controls")
	local overlay = env.require("ui/overlay")

	local M = { queue = {}, showing = false }

	local RISK_TONE = { read = "info", write = "warn", danger = "bad" }

	local RISK_TEXT = {
		read = "This only reads. Nothing changes.",
		write = "This changes something in the game or on disk.",
		danger = "This runs code, deletes data, or reaches the server. It cannot be undone.",
	}

	local function present(request)
		M.showing = true

		local remember = false
		local resolved = false

		local function answer(allowed)
			if resolved then return end
			resolved = true
			pcall(request.resolve, allowed, remember)
			M.showing = false
			-- Drain the next prompt on the same frame so a batch of tool calls does
			-- not make the user wait between decisions.
			local next_request = table.remove(M.queue, 1)
			if next_request then present(next_request) end
		end

		local modal = overlay.modal({
			title = "Allow " .. tostring(request.name) .. "?",
			description = RISK_TEXT[request.risk or "write"] or RISK_TEXT.write,
			width = 400,
			dismissable = true,
			onClose = function() answer(false) end,
		})
		if not modal then
			answer(false)
			return
		end

		P.badge(modal.content, {
			text = tostring(request.risk or "write"),
			tone = RISK_TONE[request.risk or "write"] or "warn",
			layoutOrder = 1,
		})

		if request.description then
			local description = P.text(modal.content, {
				text = tostring(request.description),
				role = "small",
				color = theme.color.textSecondary,
				wrap = true,
				auto = "Y",
				layoutOrder = 2,
			})
			description.Size = UDim2.new(1, 0, 0, 0)
		end

		-- The arguments are the whole point of the prompt: "allow run_luau" means
		-- nothing without seeing the code.
		local argsText = ""
		local ok, encoded = pcall(util.encode, request.args or {})
		if ok then argsText = encoded end
		if util.trim(argsText) ~= "" and argsText ~= "[]" and argsText ~= "{}" then
			local box = P.frame(modal.content, {
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				bg = theme.color.codeSurface,
				radius = theme.radius.md,
				padding = theme.space.sm,
				layoutOrder = 3,
			})
			P.stroke(box, theme.color.codeBorder)
			local label = P.text(box, {
				text = (util.truncate(argsText, 900)),
				role = "monoSmall",
				color = theme.color.textSecondary,
				wrap = true,
				auto = "Y",
			})
			label.Size = UDim2.new(1, 0, 0, 0)
		end

		local rememberRow = P.row(modal.content, {
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.sm,
			layoutOrder = 4,
		})
		local rememberText = P.column(rememberRow, {
			size = UDim2.new(1, -46, 0, 0),
			auto = "Y",
			gap = 0,
			layoutOrder = 1,
		})
		P.text(rememberText, { text = "Remember this answer", role = "small" })
		P.text(rememberText, {
			text = "Applies to every future " .. tostring(request.name) .. " call. Change it later in the Tools panel.",
			role = "caption",
			color = theme.color.textTertiary,
			wrap = true,
			auto = "Y",
		})
		local switch = C.switch(rememberRow, {
			value = false,
			onChange = function(value) remember = value end,
		})
		switch.instance.LayoutOrder = 2

		P.button(modal.footer, {
			text = "Deny",
			variant = "ghost",
			size = "sm",
			layoutOrder = 1,
			onClick = function()
				modal.close()
			end,
		})
		P.button(modal.footer, {
			text = "Allow",
			variant = request.risk == "danger" and "danger" or "primary",
			size = "sm",
			layoutOrder = 2,
			onClick = function()
				answer(true)
				modal.closed = true
				pcall(function() modal.scrim:Destroy() end)
			end,
		})
	end

	-- Subscribes to a session. Safe to call again on a new session; the old
	-- subscription is dropped.
	function M.attach(session)
		if M.unsubscribe then
			M.unsubscribe()
			M.unsubscribe = nil
		end
		if not session then return end
		M.unsubscribe = session.events:connect(function(event)
			if event.kind ~= "permission:ask" then return end
			if M.showing then
				M.queue[#M.queue + 1] = event
			else
				present(event)
			end
		end)
	end

	return M
end
end)()

-- ==========================================================================
-- ui/panels/providers
-- ==========================================================================
__UAI_MODULES["ui/panels/providers"] = (function()
-- Providers panel: the list, the editor, and the connection test.
--
-- This is the screen that makes the client universal, so it is deliberately plain:
-- a base URL, a key, an auth style and a model. Anything that speaks
-- /v1/chat/completions is a first-class citizen here, and the presets are only a
-- way to avoid typing a URL.
return function(env)
	local util = env.require("runtime/util")
	local clock = env.require("runtime/clock")
	local log = env.require("runtime/log")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local P = env.require("ui/primitives")
	local C = env.require("ui/controls")
	local overlay = env.require("ui/overlay")
	local catalog = env.require("provider/catalog")
	local registry = env.require("provider/registry")
	local models = env.require("provider/models")
	local chat = env.require("provider/chat")
	local traits = env.require("provider/traits")

	local M = {}

	local AUTH_OPTIONS = {
		{ value = "bearer", label = "Bearer" },
		{ value = "x-api-key", label = "x-api-key" },
		{ value = "api-key", label = "api-key" },
		{ value = "both", label = "Both" },
		{ value = "none", label = "None" },
	}

	-- Editor -----------------------------------------------------------------

	function M.editor(record, onSaved)
		local editing = util.deepCopy(record)
		local modal = overlay.modal({
			title = (util.trim(editing.id) == "" ) and "Add provider" or ("Edit " .. tostring(editing.label)),
			description = "Any OpenAI-compatible chat completions endpoint.",
			width = 420,
		})
		if not modal then return end

		local body = P.scroll(modal.content, {
			name = "Form",
			size = UDim2.new(1, 0, 0, math.min(responsive.viewport.Y * 0.5, 420)),
			-- Each row is a label, a control and often a hint, so the gap between rows
			-- has to be clearly larger than the gaps inside one or the hint reads as a
			-- caption for the row below it.
			gap = theme.space.lg,
			padding = { right = theme.space.sm },
		})

		local errorLabel

		local function row(label, hint, build)
			local column = P.column(body.instance, {
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				gap = theme.space.xs,
			})
			P.text(column, {
				text = tostring(label):upper(),
				role = "overline",
				color = theme.color.textTertiary,
			})
			local handle = build(column)
			if hint then
				P.text(column, {
					text = hint,
					role = "caption",
					color = theme.color.textTertiary,
					wrap = true,
					auto = "Y",
				})
			end
			return handle
		end

		if util.trim(editing.id) == "" then
			row("Preset", nil, function(column)
				local options = {}
				for _, preset in ipairs(catalog.presets) do
					options[#options + 1] = {
						label = preset.label,
						value = preset.id,
						detail = preset.baseUrl ~= "" and preset.baseUrl or "custom endpoint",
						selected = preset.id == editing.preset,
					}
				end
				local button = P.button(column, {
					text = (catalog.get(editing.preset) or {}).label or "Choose",
					variant = "secondary",
					fill = true,
					align = "Left",
					icon = "chevron",
					iconDirection = "down",
				})
				button.instance.Activated:Connect(function()
					overlay.menu({
						target = button.instance,
						width = 320,
						options = options,
						onSelect = function(value)
							local fresh = registry.blank(value)
							fresh.id = ""
							editing = fresh
							modal.close()
							M.editor(editing, onSaved)
						end,
					})
				end)
				return button
			end)
		end

		local labelField = row("Name", nil, function(column)
			return P.field(column, {
				text = editing.label,
				placeholder = "My provider",
				onChange = function(text) editing.label = text end,
			})
		end)

		local urlField = row("Base URL", "A bare host gets /v1 appended. A URL that already ends in /chat/completions is used as-is.", function(column)
			return P.field(column, {
				text = editing.baseUrl,
				placeholder = "https://api.example.com/v1",
				onChange = function(text) editing.baseUrl = text end,
			})
		end)

		row("API", "Chat completions is the universal one. Anthropic's own Messages API keeps reasoning and tool calls in their real shape instead of translating them twice.", function(column)
			return C.segmented(column, {
				options = chat.STYLES,
				value = chat.styleOf(editing),
				onChange = function(value) editing.api = value end,
			})
		end)

		local keyField = row("API key", "Stored on this device only, and redacted in the log.", function(column)
			return P.field(column, {
				text = editing.apiKey,
				placeholder = (catalog.get(editing.preset) or {}).keyHint or "sk-...",
				onChange = function(text) editing.apiKey = text end,
			})
		end)

		row("Auth header", nil, function(column)
			return C.segmented(column, {
				options = AUTH_OPTIONS,
				value = editing.authStyle,
				onChange = function(value) editing.authStyle = value end,
			})
		end)

		-- The only way to get a long reply out of this client.
		--
		-- No Roblox HTTP transport reads a body incrementally, so an ordinary request
		-- has to sit there until the whole completion exists -- and the host abandons
		-- it after about a minute, which a large reply cannot beat. A socket delivers
		-- the same SSE stream in frames instead, with no single-request deadline. The
		-- field is blank on every record because most endpoints do not offer one; where
		-- one does, this is where it goes.
		row("Socket URL", "Optional. A wss:// endpoint for streamed completions, which is what lifts the one-minute ceiling on a long reply. Left empty, replies arrive over HTTP in one piece.", function(column)
			return P.field(column, {
				text = editing.wsUrl,
				placeholder = "wss://api.example.com/v1",
				onChange = function(text) editing.wsUrl = text end,
			})
		end)

		-- Models. Nothing is pre-filled: the list is whatever the endpoint reports
		-- plus whatever the user types. Both are editable here before the record is
		-- ever saved, so an endpoint with no /models route is still usable.
		row("Models", "Fetch them from the endpoint, or add an id by hand. Tap one to make it the active model.", function(column)
			local fetchRow = P.row(column, { size = UDim2.new(1, 0, 0, 0), auto = "Y", gap = theme.space.xs })
			local fetch = P.button(fetchRow, {
				text = "Fetch from /models",
				variant = "secondary",
				size = "sm",
				layoutOrder = 1,
			})
			local note = P.text(fetchRow, {
				text = "",
				role = "caption",
				color = theme.color.textTertiary,
				wrap = true,
				auto = "Y",
				layoutOrder = 2,
			})
			note.Size = UDim2.new(1, -160, 0, 0)

			local list = P.column(column, {
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				gap = 2,
			})

			local addRow = P.row(column, { size = UDim2.new(1, 0, 0, 0), auto = "Y", gap = theme.space.xs })
			local addField
			local rebuildList

			local function addTyped()
				local ok, result = models.add(editing, addField.get(), { persist = false })
				if not ok then
					note.Text = tostring(result)
					note.TextColor3 = theme.color.warn
					return
				end
				addField.clear()
				note.Text = "added " .. tostring(result)
				note.TextColor3 = theme.color.textTertiary
				rebuildList()
			end

			addField = P.field(addRow, {
				placeholder = "model id, e.g. gpt-4o or llama3.2",
				size = UDim2.new(1, -(80 + theme.space.xs), 0, math.max(theme.size.control, responsive.minTarget())),
				onSubmit = addTyped,
			})
			local addButton = P.button(addRow, {
				text = "Add",
				variant = "secondary",
				size = "md",
				width = 80,
				layoutOrder = 2,
				onClick = addTyped,
			})
			addButton.instance.LayoutOrder = 2

			-- One row per known model: the record's own entries can be removed, and
			-- discovered ones are marked so it is clear where they came from.
			rebuildList = function()
				for _, child in ipairs(list:GetChildren()) do
					if not child:IsA("UIListLayout") and not child:IsA("UIPadding") then child:Destroy() end
				end

				local own = {}
				for _, id in ipairs(editing.models or {}) do own[id] = true end
				local all = models.list(editing)

				if #all == 0 then
					P.text(list, {
						text = "No models known yet. Fetch them, or type one above.",
						role = "caption",
						color = theme.color.textTertiary,
						wrap = true,
						auto = "Y",
					}).Size = UDim2.new(1, 0, 0, 0)
					return
				end

				for index, id in ipairs(all) do
					local selected = id == editing.model
					local entry = Instance.new("TextButton", list)
					entry.Text = ""
					entry.AutoButtonColor = false
					entry.BackgroundColor3 = selected and theme.color.surfaceActive or theme.color.surfaceRaised
					entry.BackgroundTransparency = selected and 0 or 1
					entry.BorderSizePixel = 0
					entry.Size = UDim2.new(1, 0, 0, math.max(theme.size.controlSmall, responsive.minTarget() - 10))
					entry.LayoutOrder = index
					entry.Selectable = true
					P.corner(entry, theme.radius.sm)

					local entryRow = P.row(entry, {
						size = UDim2.fromScale(1, 1),
						gap = theme.space.xs,
						padding = { x = theme.space.sm },
					})
					P.statusDot(entryRow, {
						diameter = 6,
						color = selected and theme.color.accent or theme.color.borderStrong,
						layoutOrder = 1,
					})
					local label = P.text(entryRow, {
						text = id,
						role = "monoSmall",
						color = selected and theme.color.text or theme.color.textSecondary,
						truncate = true,
						layoutOrder = 2,
					})
					label.Size = UDim2.new(1, -(theme.size.controlSmall + 72), 1, 0)
					-- The context window where this client knows it, and whether the id came
					-- from /models rather than from the record. Both are right-aligned facts
					-- about the row, so they share one caption instead of competing for the
					-- same slot.
					local notes = {}
					local badge = traits.badge(id)
					if badge then notes[#notes + 1] = badge end
					if not own[id] then notes[#notes + 1] = "fetched" end
					if #notes > 0 then
						P.text(entryRow, {
							text = table.concat(notes, "  "),
							role = "caption",
							color = theme.color.textTertiary,
							align = "Right",
							layoutOrder = 3,
						}).Size = UDim2.fromOffset(78, theme.text.caption.size + 4)
					end
					if own[id] then
						local remove = P.iconButton(entryRow, {
							name = "Remove",
							icon = "close",
