			local value = P.text(head, {
				text = labels[index],
				role = "label",
				color = theme.color.accent,
				align = "Right",
				auto = "X",
				layoutOrder = 2,
			})

			local feet = P.row(column, { size = UDim2.new(1, 0, 0, 0), auto = "Y", gap = theme.space.xs })
			P.text(feet, {
				text = ends[1],
				role = "caption",
