		-- The three token rows are the only settings here whose sensible value depends
		-- on something outside this client: the window and the output ceiling of
		-- whatever model the active provider is pointed at. They stop where the widest
		-- models of the moment do -- a million in, a hundred and twenty-eight thousand
		-- out -- rather than where a default conversation needs, because a ceiling that
		-- cannot reach the model is indistinguishable from the model not having it.
		local BUDGET_STOPS = {
			4000, 8000, 12000, 16000, 24000, 32000, 48000, 64000, 96000,
			128000, 160000, 200000, 256000, 320000, 400000, 512000, 750000, 1000000,
		}
		local REPLY_STOPS = { 256, 512, 1024, 2048, 4096, 8192, 16000, 24000, 32000, 64000, 96000, 128000 }
		local RESULT_STOPS = { 1000, 2000, 4000, 6000, 8000, 12000, 16000, 24000, 32000, 48000, 64000, 96000, 128000 }

		local agent = section("Agent", "How hard it works before it stops and answers.")
		numberRow(agent, "Step limit", "Tool rounds allowed in one turn.", "agent.maxTurns", 4, 60, 1)
		numberRow(agent, "Parallel tools", "Tool calls run at once within one step.", "agent.toolConcurrency", 1, 8, 1)
		numberRow(agent, "Tool timeout",
			"Seconds before a tool is abandoned. Subagents are exempt: they run to their own budget below.",
			"agent.toolTimeout", 5, 60, 1)
		numberRow(agent, "Subagent budget",
			"Seconds one subagent may work for before it wraps up. The call that dispatched it waits this long plus a minute, so a finished report is never thrown away.",
			"agent.subagentBudget", 30, 900, 30)
		numberRow(agent, "Context budget",
			"Estimated tokens kept before older turns are summarised. Set it against the model's own window, not this client: a million-token model can hold the whole session.",
			"agent.contextTokens", BUDGET_STOPS)
		numberRow(agent, "Reply ceiling",
			"max_tokens sent with each request. A value above the model's own limit is lowered to whatever the provider names in its refusal, once, and remembered.",
			"agent.maxTokens", REPLY_STOPS)
		numberRow(agent, "Tool result cap",
			"Characters kept from one tool result, roughly four per token. This is the floor on how much a file read or a page fetch can actually return, whatever the tool's own limit says.",
			"agent.resultCap", RESULT_STOPS)
		choiceRow(agent, "Effort",
			"How hard a reasoning model works before it answers. Sent as the provider's " ..
			"effort level and clamped to what the chosen model offers; models without one ignore it.",
			"agent.effort",
			{ "low", "medium", "high", "xhigh", "max" },
			{ "Low", "Medium", "High", "Very high", "Max" },
			{ "Faster", "Smarter" })
		numberRow(agent, "Temperature", "Lower is steadier; 0 is as deterministic as the provider allows. The current Claude models reject it, and it is not sent to them.", "agent.temperature", 0, 1.5, 0.05)
		numberRow(agent, "Retries", "Attempts per provider before moving to the next.", "agent.retries", 1, 6, 1)
		toggle(agent, "Ask for streams", "Streamed replies carry reasoning text and usage counts.", "agent.stream")
		toggle(agent, "Summarise old turns", "Keeps a long conversation inside the context budget.", "agent.compaction")
		toggle(agent, "Provider fallback", "Try the next enabled provider when one fails.", "agent.fallback")

		-- Permissions ----------------------------------------------------------
		local permission = section("Permissions", permissions.MODE_HINTS[permissions.mode()])
		local modeOptions = {}
		for _, mode in ipairs(permissions.MODES) do
			modeOptions[#modeOptions + 1] = { value = mode, label = permissions.MODE_LABELS[mode] or mode }
		end
		local modeHint
		C.segmented(permission, {
			options = modeOptions,
			value = permissions.mode(),
			onChange = function(value)
				permissions.setMode(value)
				if modeHint then modeHint.Text = permissions.MODE_HINTS[value] or "" end
			end,
		})
		modeHint = P.text(permission, {
			text = permissions.MODE_HINTS[permissions.mode()] or "",
			role = "caption",
			color = theme.color.textTertiary,
			wrap = true,
			auto = "Y",
		})
		modeHint.Size = UDim2.new(1, 0, 0, 0)

		toggle(permission, "Offer to remember", "Show the remember switch on each prompt.", "permissions.remember")

		local rulesLabel = P.text(permission, {
			text = "",
			role = "caption",
			color = theme.color.textSecondary,
			wrap = true,
			auto = "Y",
		})
		rulesLabel.Size = UDim2.new(1, 0, 0, 0)
		local function refreshRules()
			local rules = permissions.listRules()
			if #rules == 0 then
				rulesLabel.Text = "No per-tool rules saved."
				return
			end
			local parts = {}
			for _, rule in ipairs(rules) do
				parts[#parts + 1] = rule.pattern .. " = " .. rule.verdict
			end
			rulesLabel.Text = util.pluralise(#rules, "saved rule") .. ": " .. table.concat(parts, ", ")
		end
		refreshRules()
		permissions.changed:connect(refreshRules)
		P.button(permission, {
			text = "Clear saved rules",
			variant = "ghost",
			size = "sm",
			onClick = function()
				permissions.clearRules()
				refreshRules()
			end,
		})

		-- Identity -------------------------------------------------------------
		local identity = section("Client identity",
			"Requests are sent as the Claude Code CLI. Gateways that gate on it accept them; others ignore the extra headers.")
		toggle(identity, "Send the Claude Code identity", "Applies to every inference request.", "identity.claudeUa")
		P.field(identity, {
			text = config.get("identity.version", ua.DEFAULT_VERSION),
			placeholder = ua.DEFAULT_VERSION,
			onBlur = function(text)
				config.set("identity.version", util.trim(text) ~= "" and util.trim(text) or ua.DEFAULT_VERSION)
			end,
		})
		local identityBox = P.frame(identity, {
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			bg = theme.color.codeSurface,
			radius = theme.radius.md,
			padding = theme.space.sm,
		})
		P.stroke(identityBox, theme.color.codeBorder)
		local identityText = P.text(identityBox, {
			text = ua.describe(),
			role = "monoSmall",
			color = theme.color.textSecondary,
			wrap = true,
			auto = "Y",
		})
		identityText.Size = UDim2.new(1, 0, 0, 0)
		config.changed:connect(function(path)
			if path == nil or util.startsWith(tostring(path), "identity.") then
				identityText.Text = ua.describe()
			end
		end)

		if not caps.uaSupported then
			local warning = P.text(identity, {
				text = "This host has no executor HTTP function, so Roblox sends its own User-Agent and drops ours. Everything else still works.",
				role = "caption",
				color = theme.color.warn,
				wrap = true,
				auto = "Y",
			})
			warning.Size = UDim2.new(1, 0, 0, 0)
		end

		-- Memory ---------------------------------------------------------------
		local memory = section("Memory", "Facts the agent has chosen to keep between sessions.")
		toggle(memory, "Enabled", "When off, nothing new is stored and nothing is injected.", "memory.enabled")
		local memoryText = P.text(memory, {
			text = "",
			role = "caption",
			color = theme.color.textSecondary,
			wrap = true,
			auto = "Y",
		})
		memoryText.Size = UDim2.new(1, 0, 0, 0)
		local function refreshMemory()
			local list = state.memoryList()
			if #list == 0 then
				memoryText.Text = "Nothing stored."
				return
			end
			local lines = {}
			for _, entry in ipairs(list) do
				lines[#lines + 1] = entry.key .. ": " .. util.ellipsis(entry.value, 120)
			end
			memoryText.Text = table.concat(lines, "\n")
		end
		refreshMemory()
		state.memoryChanged:connect(refreshMemory)
		P.button(memory, {
			text = "Forget everything",
			variant = "ghost",
			size = "sm",
			onClick = function()
				overlay.confirm({
					title = "Clear memory?",
					description = "Every stored fact is deleted.",
					confirmText = "Clear",
					danger = true,
					onConfirm = function()
						state.clearMemory()
						refreshMemory()
					end,
				})
			end,
		})

		-- Session --------------------------------------------------------------
		local session = section("This session", usage.line())
		local usageText = P.text(session, {
			text = usage.line(),
			role = "monoSmall",
			color = theme.color.textSecondary,
			wrap = true,
			auto = "Y",
		})
		usageText.Size = UDim2.new(1, 0, 0, 0)
		usage.changed:connect(function() usageText.Text = usage.line() end)
		P.button(session, {
			text = "Reset counters",
			variant = "ghost",
			size = "sm",
			onClick = function() usage.reset() end,
		})
		P.button(session, {
			text = "Reset all settings",
			variant = "danger",
			size = "sm",
			onClick = function()
				overlay.confirm({
					title = "Reset every setting?",
					description = "Providers, rules and memory are kept. Appearance and agent settings go back to defaults.",
					confirmText = "Reset",
					danger = true,
					onConfirm = function()
						config.reset("ui")
						config.reset("agent")
						overlay.toast("Settings reset", "good")
					end,
				})
			end,
		})

		P.button(session, {
			text = "Unload UAI",
			variant = "danger",
			size = "sm",
			onClick = function()
				overlay.confirm({
					title = "Unload UAI?",
					description = "Stops the current turn, drains every timer and input handler, saves your settings and removes the interface. Run the loader again to come back.",
					confirmText = "Unload",
					danger = true,
					onConfirm = function()
						-- The handle the bootstrap published, which is the only thing
						-- holding the disposer registry and the ScreenGui together.
						local globals = (type(getgenv) == "function") and getgenv() or nil
						local live = globals and globals.UAI
						if live and live.destroy then
							live.destroy()
						else
							-- No global table on this host: do what can be done from here.
							env.require("runtime/dispose").drain()
							pcall(function() env.require("ui/app").screen:Destroy() end)
						end
					end,
				})
			end,
		})

		panel.scroll = scroll
		return panel
	end

	return M
end
end)()

-- ==========================================================================
-- ui/panels/tools
-- ==========================================================================
__UAI_MODULES["ui/panels/tools"] = (function()
-- Tools panel: what the agent can do here, and what it is allowed to do.
--
-- Permission rules live next to the tool they govern rather than in a separate
-- list, because "can it delete files" is a question about file_delete, not about a
-- rules table.
return function(env)
	local util = env.require("runtime/util")
	local caps = env.require("runtime/caps")
	local theme = env.require("ui/theme")
	local P = env.require("ui/primitives")
	local C = env.require("ui/controls")
	local registry = env.require("agent/registry")
	local permissions = env.require("agent/permissions")
	local schema = env.require("agent/schema")

	local M = {}

	local RULE_OPTIONS = {
		{ value = "default", label = "Default" },
		{ value = "allow", label = "Allow" },
		{ value = "ask", label = "Ask" },
		{ value = "deny", label = "Deny" },
	}

	local GROUP_LABELS = {
		agentself = "Agent",
		instance = "Instance tree",
		script = "Code",
		fs = "Files",
		net = "HTTP",
		web = "Web",
		players = "Players",
		character = "Character",
		world = "World",
		remotes = "Remotes",
		gui = "Interface",
		perf = "Diagnostics",
		meta = "Metadata",
	}

	function M.new(parent)
		local panel = {}
		local filter = ""

		local column = P.column(parent, {
			name = "ToolsPanel",
			size = UDim2.new(1, 0, 1, 0),
			gap = 0,
		})

		local head = P.column(column, {
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.sm,
			padding = { x = theme.space.md, top = theme.space.md, bottom = theme.space.sm },
			layoutOrder = 1,
		})

		local stats = registry.stats()
		P.text(head, {
			text = string.format("%d tools in %d groups", stats.total, util.count(stats.byGroup)),
			role = "heading",
		})
		local summary = P.text(head, {
			text = string.format("%d unavailable on this host: %s",
				#stats.unavailable,
				#stats.unavailable > 0 and caps.summary() or "everything is available"),
			role = "caption",
			color = theme.color.textTertiary,
			wrap = true,
			auto = "Y",
		})
		summary.Size = UDim2.new(1, 0, 0, 0)

		local searchField
		local scroll

		local function rebuild()
			scroll.clear()
			local needle = filter:lower()
			local grouped = {}
			for _, tool in ipairs(registry.list()) do
				if needle == ""
					or tool.name:lower():find(needle, 1, true)
					or tostring(tool.description):lower():find(needle, 1, true) then
					grouped[tool.group] = grouped[tool.group] or {}
					table.insert(grouped[tool.group], tool)
				end
			end

			local order = util.keys(grouped, true)
			if #order == 0 then
				C.emptyState(scroll.instance, {
					title = "No tool matches",
					description = "Try a shorter search.",
					layoutOrder = 1,
				})
				return
			end

			local position = 0
			for _, group in ipairs(order) do
				position = position + 1
				P.sectionHeader(scroll.instance, {
					title = GROUP_LABELS[group] or group,
					layoutOrder = position,
				})

				for _, tool in ipairs(grouped[group]) do
					position = position + 1
					local missing = registry.missingCapability(tool)
					local card = P.card(scroll.instance, {
						name = tool.name,
						layoutOrder = position,
						gap = theme.space.xs,
					})

					local top = P.row(card, {
						size = UDim2.new(1, 0, 0, 0),
						auto = "Y",
						gap = theme.space.xs,
						layoutOrder = 1,
					})
					local name = P.text(top, {
						text = tool.name,
						role = "monoSmall",
						color = missing and theme.color.textDisabled or theme.color.text,
						layoutOrder = 1,
					})
					name.Size = UDim2.fromOffset(0, theme.text.monoSmall.size + 4)
					name.AutomaticSize = Enum.AutomaticSize.X

					P.badge(top, {
						text = tool.risk,
						tone = tool.risk == "read" and "info" or (tool.risk == "danger" and "bad" or "warn"),
						layoutOrder = 2,
					})
					if missing then
						P.badge(top, { text = "unavailable", tone = "warn", layoutOrder = 3 })
					end

					local description = P.text(card, {
						text = tostring(tool.description),
						role = "caption",
						color = theme.color.textSecondary,
						wrap = true,
						auto = "Y",
						layoutOrder = 2,
					})
					description.Size = UDim2.new(1, 0, 0, 0)

					local params = P.text(card, {
						text = schema.describe(tool.parameters),
						role = "caption",
						color = theme.color.textTertiary,
						wrap = true,
						auto = "Y",
						layoutOrder = 3,
					})
					params.Size = UDim2.new(1, 0, 0, 0)

					if missing then
						local reason = P.text(card, {
							text = caps.reason(missing),
							role = "caption",
							color = theme.color.warn,
							wrap = true,
							auto = "Y",
							layoutOrder = 4,
						})
						reason.Size = UDim2.new(1, 0, 0, 0)
					else
						C.segmented(card, {
							options = RULE_OPTIONS,
							value = permissions.ruleFor(tool.name) or "default",
							layoutOrder = 4,
							onChange = function(value)
								permissions.setRule(tool.name, value)
							end,
						})
					end
				end
			end
		end

		searchField = P.field(head, {
			placeholder = "Search tools",
			onChange = function(text)
				filter = util.trim(text)
				rebuild()
			end,
		})

		scroll = P.scroll(column, {
			name = "ToolList",
			size = UDim2.new(1, 0, 1, 0),
			gap = theme.space.sm,
			padding = { x = theme.space.md, bottom = theme.space.md },
			layoutOrder = 2,
		})
		local flex = Instance.new("UIFlexItem", scroll.instance)
		flex.FlexMode = Enum.UIFlexMode.Fill

		rebuild()
		panel.refresh = rebuild
		panel.unsubscribe = permissions.changed:connect(rebuild)
		return panel
	end

	return M
end
end)()

-- ==========================================================================
-- ui/primitives
-- ==========================================================================
__UAI_MODULES["ui/primitives"] = (function()
-- Layout and interaction primitives.
--
-- Everything visible is built from these, and they all take the same shape of
-- props table, so a panel reads as a description of what it is rather than a
-- hundred lines of instance plumbing. Three rules are enforced here rather than
-- left to each caller: nothing is positioned by hand-computed offsets, every
-- interactive element has a full state set, and every hit target respects the
-- platform minimum.
return function(env)
	local util = env.require("runtime/util")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")

	local P = {}

	-- Shared helpers ---------------------------------------------------------

	function P.corner(instance, radius)
		local corner = Instance.new("UICorner", instance)
		corner.CornerRadius = UDim.new(0, radius == nil and theme.radius.md or radius)
		return corner
	end

	function P.stroke(instance, colour, thickness)
		local stroke = Instance.new("UIStroke", instance)
		stroke.Color = colour or theme.color.borderSubtle
		stroke.Thickness = thickness or theme.stroke.hair
		stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
		return stroke
	end

	function P.pad(instance, spec)
		local padding = Instance.new("UIPadding", instance)
		if type(spec) == "number" then
			padding.PaddingTop = UDim.new(0, spec)
			padding.PaddingBottom = UDim.new(0, spec)
			padding.PaddingLeft = UDim.new(0, spec)
			padding.PaddingRight = UDim.new(0, spec)
		elseif type(spec) == "table" then
			local x = spec.x or spec.horizontal
			local y = spec.y or spec.vertical
			padding.PaddingTop = UDim.new(0, spec.top or y or 0)
			padding.PaddingBottom = UDim.new(0, spec.bottom or y or 0)
			padding.PaddingLeft = UDim.new(0, spec.left or x or 0)
			padding.PaddingRight = UDim.new(0, spec.right or x or 0)
		end
		return padding
	end

	local AUTO = {
		X = Enum.AutomaticSize.X,
		Y = Enum.AutomaticSize.Y,
		XY = Enum.AutomaticSize.XY,
	}

	-- Applies the props every visual element shares. Kept in one place so adding a
	-- shared concern (a token, an accessibility flag) is one edit.
	local function base(instance, props)
		props = props or {}
		if props.name then instance.Name = props.name end
		instance.BorderSizePixel = 0
		if props.size then instance.Size = props.size end
		if props.position then instance.Position = props.position end
		if props.anchor then instance.AnchorPoint = props.anchor end
		if props.auto then instance.AutomaticSize = AUTO[props.auto] or Enum.AutomaticSize.None end
		if props.zIndex then instance.ZIndex = props.zIndex end
		if props.layoutOrder then instance.LayoutOrder = props.layoutOrder end
		if props.clip ~= nil then instance.ClipsDescendants = props.clip == true end
		if props.visible ~= nil then instance.Visible = props.visible == true end
		if props.rotation then instance.Rotation = props.rotation end

		if props.bg then
			instance.BackgroundColor3 = props.bg
			instance.BackgroundTransparency = props.bgTransparency or 0
		else
			instance.BackgroundTransparency = 1
		end
		if props.radius ~= nil then P.corner(instance, props.radius) end
		if props.stroke then P.stroke(instance, props.strokeColor, props.strokeWidth) end
		if props.padding then P.pad(instance, props.padding) end
		if props.minSize or props.maxSize then
			local constraint = Instance.new("UISizeConstraint", instance)
			if props.minSize then constraint.MinSize = props.minSize end
			if props.maxSize then constraint.MaxSize = props.maxSize end
		end
		if props.aspect then
			Instance.new("UIAspectRatioConstraint", instance).AspectRatio = props.aspect
		end
		if props.flex then
			local item = Instance.new("UIFlexItem", instance)
			item.FlexMode = Enum.UIFlexMode[props.flex] or Enum.UIFlexMode.Fill
		end
		return instance
	end

	function P.frame(parent, props)
		local frame = Instance.new("Frame", parent)
		return base(frame, props)
	end

	local function stack(parent, props, direction)
		props = props or {}
		local frame = P.frame(parent, props)
		local layout = Instance.new("UIListLayout", frame)
		layout.FillDirection = direction
		layout.SortOrder = Enum.SortOrder.LayoutOrder
		layout.Padding = UDim.new(0, props.gap or theme.space.sm)
		layout.HorizontalAlignment = Enum.HorizontalAlignment[props.alignX or "Left"]
		layout.VerticalAlignment = Enum.VerticalAlignment[props.alignY or "Top"]
		if props.wrap then layout.Wraps = true end
		if props.stretch then layout.ItemLineAlignment = Enum.ItemLineAlignment.Stretch end
		return frame, layout
	end

	function P.column(parent, props)
		return stack(parent, props, Enum.FillDirection.Vertical)
	end

	function P.row(parent, props)
		props = props or {}
		props.alignY = props.alignY or "Center"
		return stack(parent, props, Enum.FillDirection.Horizontal)
	end

	function P.spacer(parent, props)
		props = props or {}
		local frame = P.frame(parent, {
			name = "Spacer",
			size = props.size or UDim2.new(1, 0, 0, props.height or theme.space.sm),
			layoutOrder = props.layoutOrder,
		})
		if props.grow then
			local item = Instance.new("UIFlexItem", frame)
			item.FlexMode = Enum.UIFlexMode.Grow
		end
		return frame
	end

	function P.divider(parent, props)
		props = props or {}
		return P.frame(parent, {
			name = "Divider",
			size = props.vertical and UDim2.new(0, 1, 1, 0) or UDim2.new(1, 0, 0, 1),
			bg = props.color or theme.color.borderSubtle,
			layoutOrder = props.layoutOrder,
		})
	end

	-- Text -------------------------------------------------------------------

	-- `size` is the UDim2 every element shares; the font size comes from the role,
	-- or from `textSize` when one label genuinely has to differ. Overloading `size`
	-- for both would assign a number to Size, which Roblox rejects outright.
	function P.text(parent, props)
		props = props or {}
		local role = theme.textRole(props.role or "body")
		local label = Instance.new("TextLabel", parent)
		base(label, props)
		label.Text = tostring(props.text or "")
		label.TextColor3 = props.color or theme.color.text
		label.Font = props.font or role.font
		label.TextSize = props.textSize or role.size
		label.LineHeight = props.line or role.line
		label.TextXAlignment = Enum.TextXAlignment[props.align or "Left"]
		label.TextYAlignment = Enum.TextYAlignment[props.alignY or "Center"]
		label.TextWrapped = props.wrap == true
		label.RichText = props.rich == true
		if props.transparency then label.TextTransparency = props.transparency end
		if props.truncate then label.TextTruncate = Enum.TextTruncate.AtEnd end
		-- A label with no explicit size collapses to nothing inside a list layout,
		-- which is the single most common way an interface silently loses text.
		-- `auto` only covers the axes it names, so it does not save us here: with
		-- `auto = "Y"` the width is still ours to set, and a zero-width label does
		-- not vanish so much as wrap to one character per line -- the same bug
		-- wearing a costume that reads as a rendering glitch instead of a layout one.
		-- The caller owns the width only when `auto` includes X.
		if not props.size then
			if props.auto == "X" or props.auto == "XY" then
				label.Size = UDim2.fromOffset(0, 0)
			elseif props.auto == "Y" then
				label.Size = UDim2.new(1, 0, 0, 0)
			else
				-- One rendered line plus a little slack. Sized from the role's line
				-- height, not its font size: at a 1.5 line height the two differ by
				-- seven pixels and the descenders go missing.
				local single = props.textSize and math.ceil(props.textSize * (props.line or role.line))
					or role.height or (role.size + 4)
				label.Size = UDim2.new(1, 0, 0, single + 4)
			end
		end
		return label
	end

	-- A heading with an optional trailing description, which is the pattern every
	-- settings group uses.
	function P.sectionHeader(parent, props)
		local holder = P.column(parent, {
			name = "Section",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.xxs,
			layoutOrder = props.layoutOrder,
		})
		P.text(holder, {
			text = tostring(props.title or ""):upper(),
			role = "overline",
			color = theme.color.textTertiary,
			auto = "Y",
			wrap = true,
		})
		if props.description then
			P.text(holder, {
				text = props.description,
				role = "small",
				color = theme.color.textSecondary,
				wrap = true,
				auto = "Y",
			})
		end
		return holder
	end

	-- Interaction ------------------------------------------------------------

	local VARIANTS = {
		primary = function()
			return {
				bg = theme.color.accent, bgHover = theme.color.accentHot, bgPress = theme.color.accentMuted,
				text = theme.color.textOnAccent, stroke = nil, font = "bodyStrong",
			}
		end,
		secondary = function()
			return {
				bg = theme.color.surfaceRaised, bgHover = theme.color.surfaceHover, bgPress = theme.color.surfaceActive,
				text = theme.color.text, stroke = theme.color.border, font = "bodyStrong",
			}
		end,
		ghost = function()
			return {
				bg = nil, bgHover = theme.color.surfaceHover, bgPress = theme.color.surfaceActive,
				text = theme.color.textSecondary, stroke = nil, font = "body",
			}
		end,
		danger = function()
			return {
				bg = theme.color.dangerSurface, bgHover = theme.color.danger, bgPress = theme.color.dangerSurface,
				text = theme.color.danger, textHover = theme.color.textOnAccent,
				stroke = theme.color.dangerBorder, font = "bodyStrong",
			}
		end,
	}

	local HEIGHTS = { sm = "controlSmall", md = "control", lg = "controlLarge" }

	-- One button implementation with a full state set: rest, hover, press, focus,
	-- disabled and loading. Roblox gives none of that, and a project that hand-rolls
	-- it per call site ends up with buttons that behave differently from each other.
	function P.button(parent, props)
		props = props or {}
		local variant = (VARIANTS[props.variant or "secondary"])()
		local height = math.max(theme.size[HEIGHTS[props.size or "md"]], responsive.minTarget())
		-- A button with neither a fixed width nor fill sizes to its label. That means
		-- the content row has to size to its own children too: AutomaticSize ignores
		-- a child whose width is a scale, so a (1, 0) row inside an auto-width button
		-- collapses the button to nothing.
		local autoWidth = not props.width and not props.fill

		local button = Instance.new("TextButton", parent)
		button.Text = ""
		button.AutoButtonColor = false
		button.Active = true
		button.Selectable = true
		base(button, {
			name = props.name or "Button",
			size = props.width and UDim2.new(0, props.width, 0, height)
				or (props.fill and UDim2.new(1, 0, 0, height) or UDim2.new(0, 0, 0, height)),
			auto = autoWidth and "X" or nil,
			position = props.position,
			anchor = props.anchor,
			layoutOrder = props.layoutOrder,
			bg = variant.bg,
			radius = props.radius or theme.radius.md,
			zIndex = props.zIndex,
		})
		if variant.stroke then P.stroke(button, variant.stroke) end
		if not variant.bg then button.BackgroundTransparency = 1 end

		local content, layout = P.row(button, {
			name = "Content",
			size = autoWidth and UDim2.new(0, 0, 1, 0) or UDim2.new(1, 0, 1, 0),
			auto = autoWidth and "X" or nil,
			gap = theme.space.xs,
			alignX = props.align or "Center",
			alignY = "Center",
			padding = { x = props.tight and theme.space.xs or theme.space.md },
		})
		layout.SortOrder = Enum.SortOrder.LayoutOrder

		local icons = env.require("ui/icons")
		local iconHolder
		if props.icon then
			iconHolder = P.frame(content, {
				name = "IconSlot",
				size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
				layoutOrder = 1,
			})
			icons.draw(props.icon, iconHolder, theme.size.icon, variant.text, props.iconDirection)
		end

		local label
		if props.text and props.text ~= "" then
			label = P.text(content, {
				text = props.text,
				role = variant.font,
				color = variant.text,
				align = "Center",
				auto = "XY",
				layoutOrder = 2,
			})
			label.Size = UDim2.fromOffset(0, 0)
		end

		local handle = { instance = button, label = label, enabled = true, busy = false }

		local function paint(state)
			local target = variant.bg
			local textColour = variant.text
			if not handle.enabled then
				target = theme.color.surfaceRaised
				textColour = theme.color.textDisabled
			elseif state == "hover" then
				target = variant.bgHover or variant.bg
				textColour = variant.textHover or variant.text
			elseif state == "press" then
				target = variant.bgPress or variant.bgHover or variant.bg
				textColour = variant.textHover or variant.text
			end
			if target then
				button.BackgroundTransparency = 0
				env.tween:Create(button, theme.tween("hover"), { BackgroundColor3 = target }):Play()
			else
				env.tween:Create(button, theme.tween("hover"), { BackgroundTransparency = 1 }):Play()
			end
			if label then
				env.tween:Create(label, theme.tween("hover"), { TextColor3 = textColour }):Play()
			end
		end

		button.MouseEnter:Connect(function() if handle.enabled then paint("hover") end end)
		button.MouseLeave:Connect(function() paint("rest") end)
		button.MouseButton1Down:Connect(function() if handle.enabled then paint("press") end end)
		button.MouseButton1Up:Connect(function() if handle.enabled then paint("hover") end end)
		-- Gamepad focus has to look like hover or a console user cannot see where
		-- they are.
		button.SelectionGained:Connect(function() if handle.enabled then paint("hover") end end)
		button.SelectionLost:Connect(function() paint("rest") end)

		button.Activated:Connect(function()
			if not handle.enabled or handle.busy then return end
			if props.onClick then
				local ok, err = pcall(props.onClick, handle)
				if not ok then
					env.require("runtime/log").warn("ui", "button handler failed", err)
				end
			end
		end)

		function handle.setEnabled(value)
			handle.enabled = value ~= false
			button.Active = handle.enabled
			button.Selectable = handle.enabled
			paint("rest")
		end

		function handle.setText(text)
			if label then label.Text = tostring(text) end
		end

		function handle.setVariant(name)
			variant = (VARIANTS[name] or VARIANTS.secondary)()
			paint("rest")
		end

		paint("rest")
		return handle
	end

	function P.iconButton(parent, props)
		props = props or {}
		local size = math.max(props.diameter or theme.size.control, responsive.minTarget())
		local handle = P.button(parent, util.merge(props, {
			variant = props.variant or "ghost",
			text = nil,
			width = size,
			tight = true,
			radius = props.radius or theme.radius.md,
		}))
		handle.instance.Size = UDim2.fromOffset(size, size)
		handle.instance.AutomaticSize = Enum.AutomaticSize.None
		return handle
	end

	-- Input -----------------------------------------------------------------

	-- A text field with a real focus state. The reference client's prompt box gave
	-- no sign it had focus at all, which on a dark panel means typing into nothing;
	-- the border picking up the accent is the whole fix.
	function P.field(parent, props)
		props = props or {}
		local role = theme.textRole(props.role or "body")
		local multiline = props.multiline == true
		local height = multiline
			and (props.height or theme.size.control * 2)
			or math.max(theme.size.control, responsive.minTarget())

		local shell = P.frame(parent, {
			name = props.name or "Field",
			size = props.size or UDim2.new(1, 0, 0, height),
			auto = props.auto,
			layoutOrder = props.layoutOrder,
			bg = props.bg or theme.color.surfaceRaised,
			radius = props.radius or theme.radius.md,
			clip = true,
		})
		local stroke = P.stroke(shell, theme.color.border)

		local box = Instance.new("TextBox", shell)
		box.BackgroundTransparency = 1
		box.Size = UDim2.new(1, 0, 1, 0)
		box.Text = tostring(props.text or "")
		box.PlaceholderText = tostring(props.placeholder or "")
		box.PlaceholderColor3 = theme.color.textTertiary
		box.TextColor3 = theme.color.text
		box.Font = role.font
		box.TextSize = role.size
		box.LineHeight = role.line
		box.ClearTextOnFocus = false
		box.TextXAlignment = Enum.TextXAlignment[props.align or "Left"]
		box.TextYAlignment = multiline and Enum.TextYAlignment.Top or Enum.TextYAlignment.Center
		box.MultiLine = multiline
		box.TextWrapped = multiline
		box.ClipsDescendants = true
		box.Selectable = true
		P.pad(box, { x = props.padX or theme.space.md, y = multiline and theme.space.sm or 0 })

		local handle = { instance = box, shell = shell, stroke = stroke }

		box.Focused:Connect(function()
			env.tween:Create(stroke, theme.tween("hover"), { Color = theme.color.accentBorder }):Play()
			env.tween:Create(shell, theme.tween("hover"), { BackgroundColor3 = theme.color.surfaceOverlay }):Play()
			if props.onFocus then pcall(props.onFocus, handle) end
		end)

		box.FocusLost:Connect(function(enterPressed)
			env.tween:Create(stroke, theme.tween("hover"), { Color = theme.color.border }):Play()
			env.tween:Create(shell, theme.tween("hover"), {
				BackgroundColor3 = props.bg or theme.color.surfaceRaised,
			}):Play()
			-- On a multiline box Enter inserts a newline, so submit is the caller's
			-- job there; on a single line it means "go".
			if enterPressed and not multiline and props.onSubmit then
				pcall(props.onSubmit, box.Text, handle)
			end
			if props.onBlur then pcall(props.onBlur, box.Text, handle) end
		end)

		if props.onChange then
			box:GetPropertyChangedSignal("Text"):Connect(function()
				pcall(props.onChange, box.Text, handle)
			end)
		end

		function handle.get() return box.Text end
		function handle.set(value) box.Text = tostring(value or "") end
		function handle.focus() pcall(function() box:CaptureFocus() end) end
		function handle.clear() box.Text = "" end

		return handle
	end

	-- Containers -------------------------------------------------------------

	function P.card(parent, props)
		props = props or {}
		local card, layout = P.column(parent, {
			name = props.name or "Card",
			size = props.size or UDim2.new(1, 0, 0, 0),
			auto = props.auto or "Y",
			layoutOrder = props.layoutOrder,
			bg = props.bg or theme.color.surfaceRaised,
			radius = props.radius or theme.radius.lg,
			gap = props.gap or theme.space.sm,
			padding = props.padding or theme.space.md,
			clip = props.clip,
		})
		P.stroke(card, props.strokeColor or theme.color.borderSubtle)
		return card, layout
	end

	function P.badge(parent, props)
		props = props or {}
		local tone = props.tone or "info"
		local holder = P.row(parent, {
			name = "Badge",
			size = UDim2.fromOffset(0, theme.size.controlSmall - 6),
			auto = "X",
			bg = props.bg or theme.toneSurface(tone),
			radius = theme.radius.sm,
			gap = theme.space.xxs,
			padding = { x = theme.space.xs },
			layoutOrder = props.layoutOrder,
		})
		if props.dot then
			local dot = P.frame(holder, {
				name = "Dot",
				size = UDim2.fromOffset(6, 6),
				bg = props.dotColor or theme.toneColor(tone),
				radius = theme.radius.pill,
			})
			dot.LayoutOrder = 1
		end
		local label = P.text(holder, {
			text = tostring(props.text or ""),
			role = "label",
			color = props.color or theme.toneColor(tone),
			auto = "XY",
			layoutOrder = 2,
		})
		label.Size = UDim2.fromOffset(0, 0)
		return holder, label
	end

	-- A scroll region with the two things Roblox does not give you: a canvas that
	-- sizes itself from its contents, and edge fades so a long list reads as
	-- continuing rather than as ending at a hard line.
	function P.scroll(parent, props)
		props = props or {}
		local scroll = Instance.new("ScrollingFrame", parent)
		base(scroll, {
			name = props.name or "Scroll",
			size = props.size or UDim2.new(1, 0, 1, 0),
			position = props.position,
			layoutOrder = props.layoutOrder,
			bg = props.bg,
			clip = true,
		})
		scroll.ScrollBarThickness = props.bar or theme.size.scrollbar
		scroll.ScrollBarImageColor3 = theme.color.border
		scroll.ScrollBarImageTransparency = 0.2
		scroll.BorderSizePixel = 0
		scroll.CanvasSize = UDim2.new(0, 0, 0, 0)
		scroll.AutomaticCanvasSize = props.horizontal and Enum.AutomaticSize.X or Enum.AutomaticSize.Y
		scroll.ScrollingDirection = props.horizontal and Enum.ScrollingDirection.X or Enum.ScrollingDirection.Y
		scroll.ElasticBehavior = Enum.ElasticBehavior.WhenScrollable
		scroll.Selectable = false

		local layout = Instance.new("UIListLayout", scroll)
		layout.FillDirection = props.horizontal and Enum.FillDirection.Horizontal or Enum.FillDirection.Vertical
		layout.SortOrder = Enum.SortOrder.LayoutOrder
		layout.Padding = UDim.new(0, props.gap or theme.space.sm)
		if props.alignX then layout.HorizontalAlignment = Enum.HorizontalAlignment[props.alignX] end

		if props.padding then P.pad(scroll, props.padding) end

		local handle = { instance = scroll, layout = layout }

		function handle.toBottom()
			scroll.CanvasPosition = Vector2.new(0, math.max(scroll.AbsoluteCanvasSize.Y, 1e6))
		end

		function handle.atBottom(slack)
			local visible = scroll.AbsoluteWindowSize.Y
			local total = scroll.AbsoluteCanvasSize.Y
			if total <= visible then return true end
			return (total - visible - scroll.CanvasPosition.Y) <= (slack or 48)
		end

		function handle.clear()
			for _, child in ipairs(scroll:GetChildren()) do
				if not child:IsA("UIListLayout") and not child:IsA("UIPadding") then child:Destroy() end
			end
		end

		if props.fade then
			for _, spec in ipairs({
				{ name = "FadeTop", anchor = Vector2.new(0, 0), position = UDim2.fromScale(0, 0), rotation = 90 },
				{ name = "FadeBottom", anchor = Vector2.new(0, 1), position = UDim2.fromScale(0, 1), rotation = -90 },
			}) do
				local fade = P.frame(parent, {
					name = spec.name,
					size = UDim2.new(1, 0, 0, theme.space.xl),
					anchor = spec.anchor,
					position = spec.position,
					bg = props.fadeColor or theme.color.surface,
					zIndex = (props.zIndex or 1) + 5,
				})
				local gradient = Instance.new("UIGradient", fade)
				gradient.Rotation = spec.rotation
				gradient.Transparency = NumberSequence.new({
					NumberSequenceKeypoint.new(0, 0),
					NumberSequenceKeypoint.new(1, 1),
				})
			end
		end

		return handle
	end

	-- A small coloured dot used for provider health and busy state. Separate from
	-- badge because it is used inline in dense rows where a pill is too heavy.
	function P.statusDot(parent, props)
		props = props or {}
		return P.frame(parent, {
			name = "Status",
			size = UDim2.fromOffset(props.diameter or 7, props.diameter or 7),
			bg = props.color or theme.color.textTertiary,
			radius = theme.radius.pill,
			layoutOrder = props.layoutOrder,
			anchor = props.anchor,
			position = props.position,
		})
	end

	return P
end
end)()

-- ==========================================================================
-- ui/quickchat
-- ==========================================================================
__UAI_MODULES["ui/quickchat"] = (function()
-- Quick chat: one keypress, one message, gone again.
--
-- The window is the place to read a conversation; this is the place to start one
-- without leaving what you were doing. It floats in the middle of the screen, takes
-- a single line, sends to the same session the Chat panel shows -- so whatever is
-- typed here appears there -- and dismisses itself. Nothing about it is a second
-- transcript.
--
-- The key is captured rather than typed into a field: a user thinks "this key", not
-- "Enum.KeyCode.Semicolon", and capturing it also sidesteps mapping characters to
-- key codes across keyboard layouts.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local clock = env.require("runtime/clock")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local dispose = env.require("runtime/dispose")
	local P = env.require("ui/primitives")
	local sessions = env.require("agent/session")

	local M = { visible = false, mounted = false }

	local DEFAULT_KEY = "Semicolon"

	-- The bound key as an EnumItem, or nil when the stored name no longer exists.
	function M.keyCode()
		local name = tostring(config.get("ui.quickKey", DEFAULT_KEY))
		local ok, item = pcall(function() return Enum.KeyCode[name] end)
		if ok and item then return item end
		return Enum.KeyCode.Semicolon
	end

	function M.keyName()
		return tostring(config.get("ui.quickKey", DEFAULT_KEY))
	end

	function M.setKey(keyCode)
		local name = keyCode and keyCode.Name or DEFAULT_KEY
		config.set("ui.quickKey", name)
		return name
	end

	function M.mount(layer)
		if M.mounted and M.root and M.root.Parent then return M.root end

		M.root = P.frame(layer, {
			name = "QuickChat",
			size = UDim2.fromScale(1, 1),
			zIndex = theme.z.quick,
			visible = false,
		})
		M.root.Active = false

		-- A scrim, so the rest of the screen recedes and a click outside dismisses.
		local scrim = Instance.new("TextButton", M.root)
		scrim.Name = "QuickScrim"
		scrim.Text = ""
		scrim.AutoButtonColor = false
		scrim.BorderSizePixel = 0
		scrim.Size = UDim2.fromScale(1, 1)
		scrim.BackgroundColor3 = theme.color.scrim
		scrim.BackgroundTransparency = 1
		scrim.ZIndex = theme.z.quick
		M.scrim = scrim

		local card = P.column(M.root, {
			name = "QuickCard",
			size = UDim2.new(0, math.min(math.max(responsive.viewport.X * 0.5, 360), 720), 0, 0),
			auto = "Y",
			anchor = Vector2.new(0.5, 0.5),
			position = UDim2.fromScale(0.5, 0.42),
			bg = theme.color.surface,
			radius = theme.radius.xl,
			gap = theme.space.xs,
			padding = theme.space.md,
			zIndex = theme.z.quick + 1,
		})
		P.stroke(card, theme.color.accentBorder)
		M.card = card
		M.scale = Instance.new("UIScale", card)
		M.scale.Scale = 0.96

		M.field = P.field(card, {
			name = "QuickPrompt",
			placeholder = "Ask, or tell it what to change",
			layoutOrder = 1,
			onSubmit = function(text) M.submit(text) end,
		})

		M.hint = P.text(card, {
			text = "",
			role = "caption",
			color = theme.color.textTertiary,
			layoutOrder = 2,
		})

		M.mounted = true
		return M.root
	end

	local function refreshHint()
		if not M.hint then return end
		local providers = env.require("provider/registry")
		local record = providers.active()
		M.hint.Text = record
			and string.format("Enter to send to %s  ·  Esc to close  ·  %s reopens",
				tostring(record.label), M.keyName())
			or "No provider configured yet -- open the window and add one."
	end

	function M.show()
		if not M.mounted or M.visible then return end
		M.visible = true
		refreshHint()
		M.field.set("")
		M.root.Visible = true
		if responsive.reduceMotion then
			M.scale.Scale = 1
			M.scrim.BackgroundTransparency = 0.5
		else
			M.scale.Scale = 0.96
			M.scrim.BackgroundTransparency = 1
			env.tween:Create(M.scale, theme.tween("enter"), { Scale = 1 }):Play()
			env.tween:Create(M.scrim, theme.tween("enter"), { BackgroundTransparency = 0.5 }):Play()
		end
		-- One frame late: capturing focus in the same frame the surface becomes
		-- visible is unreliable.
		clock.delay(0.05, function()
			if M.visible then M.field.focus() end
		end)
	end

	function M.hide()
		if not M.mounted or not M.visible then return end
		M.visible = false
		pcall(function() M.field.instance:ReleaseFocus() end)
		if responsive.reduceMotion then
			M.root.Visible = false
			return
		end
		env.tween:Create(M.scale, theme.tween("exit"), { Scale = 0.96 }):Play()
		local out = env.tween:Create(M.scrim, theme.tween("exit"), { BackgroundTransparency = 1 })
		out.Completed:Connect(function()
			-- Only hide if nothing reopened it while the tween ran.
			if not M.visible and M.root then M.root.Visible = false end
		end)
		out:Play()
	end

	function M.toggle()
		if M.visible then M.hide() else M.show() end
	end

	function M.submit(text)
		local message = util.trim(tostring(text or ""))
		M.hide()
		if message == "" then return end
		-- The same session the Chat panel is bound to, so the message and its reply
		-- land in the transcript rather than in a parallel conversation.
		local ok, reason = sessions.current().send(message)
		if not ok then
			env.require("ui/overlay").toast(tostring(reason), "warn", 3)
		end
	end

	-- Bound once, on the service, because the point of the shortcut is that it works
	-- when nothing of this interface has focus.
	function M.bind()
		if M.bound then return end
		M.bound = true

		dispose.connection(env.uis.InputBegan:Connect(function(input, processed)
			if input.UserInputType ~= Enum.UserInputType.Keyboard then return end

			if M.visible then
				if input.KeyCode == Enum.KeyCode.Escape then M.hide() end
				return
			end

			-- `processed` means the keystroke already went somewhere -- a text box, a
			-- CoreGui field. Opening on it would fire every time the bound character is
			-- typed into the composer, which is the one thing that would make this
			-- feature intolerable.
			if processed then return end
			local focused = nil
			pcall(function() focused = env.uis:GetFocusedTextBox() end)
			if focused then return end

			if M.capture then
				local pending = M.capture
				M.capture = nil
				pending(input.KeyCode)
				return
			end

			if input.KeyCode == M.keyCode() then M.show() end
		end))

		-- Clicking the scrim dismisses without sending.
		if M.scrim then
			M.scrim.Activated:Connect(function() M.hide() end)
		end
	end

	-- Settings asks for the next keypress rather than parsing a typed character.
	function M.captureNext(callback)
		M.capture = function(keyCode)
			local name = M.setKey(keyCode)
			if callback then pcall(callback, name) end
		end
	end

	function M.cancelCapture()
		M.capture = nil
	end

	return M
end
end)()

-- ==========================================================================
-- ui/responsive
-- ==========================================================================
__UAI_MODULES["ui/responsive"] = (function()
-- Responsiveness.
--
-- The reference client decided phone-or-desktop once at boot from
-- TouchEnabled-and-not-KeyboardEnabled, and baked two tables of pixel metrics off
-- that. It gets the common cases right and everything else wrong: a tablet, a
-- phone that rotates, a desktop window resized to half width, a console, a device
-- with both touch and a keyboard.
--
-- This module holds no metrics. It reports what the viewport is right now and
-- republishes when that changes, so a surface either adapts continuously (scale
-- based layout, list layouts, automatic sizing) or rebuilds itself when the layout
-- mode genuinely changes -- and the second is debounced, because a desktop window
-- drag fires viewport changes every frame.
return function(env)
	local util = env.require("runtime/util")
	local clock = env.require("runtime/clock")
	local signal = env.require("runtime/signal")
	local log = env.require("runtime/log")

	local BREAKPOINTS = {
		{ name = "xs", max = 520 },
		{ name = "sm", max = 900 },
		{ name = "md", max = 1280 },
		{ name = "lg", max = 1700 },
		{ name = "xl", max = math.huge },
	}

	local M = {
		viewport = Vector2.new(1280, 720),
		breakpoint = "md",
		mode = "window",
		orientation = "landscape",
		touch = false,
		pointer = true,
		gamepad = false,
		console = false,
		reduceMotion = false,
		transparency = 1,
		keyboardHeight = 0,
		inset = Vector2.new(0, 0),
		bottomInset = 0,
		changed = signal.new("responsive"),
		modeChanged = signal.new("responsive:mode"),
		ready = false,
	}

	local function breakpointFor(width)
		for _, entry in ipairs(BREAKPOINTS) do
			if width < entry.max then return entry.name end
		end
		return "xl"
	end

	-- Layout mode is the only thing surfaces branch on, and it is derived rather
	-- than configured: a console is gamepad-first regardless of resolution, a
	-- narrow viewport is a sheet whether it is a phone or a small window, and the
	-- user can still pin it by hand in settings.
	--
	-- Orientation matters as much as width. A tablet held portrait is 834 points
	-- wide and 1112 tall; a floating window in that space is a tall thin box, while
	-- a full-height dock reads properly.
	local function modeFor(breakpoint, forced)
		if forced and forced ~= "auto" then return forced end
		if M.console then return "tv" end
		if breakpoint == "xs" then return "sheet" end
		if breakpoint == "sm" then return "panel" end
		if M.orientation == "portrait" then return "panel" end
		return "window"
	end

	local function sample()
		local width, height = 1280, 720

		-- The camera's viewport is the honest number: a ScreenGui's AbsoluteSize is
		-- zero until it renders, and IgnoreGuiInset changes it underneath you.
		local okCamera, camera = pcall(function() return env.services.Workspace.CurrentCamera end)
		if okCamera and camera and camera.ViewportSize and camera.ViewportSize.Y > 0 then
			width, height = camera.ViewportSize.X, camera.ViewportSize.Y
		elseif M.screen and M.screen.AbsoluteSize and M.screen.AbsoluteSize.Y > 0 then
			width, height = M.screen.AbsoluteSize.X, M.screen.AbsoluteSize.Y
		end

		M.viewport = Vector2.new(width, height)
		M.orientation = (height > width) and "portrait" or "landscape"

		local okInput = pcall(function()
			M.touch = env.uis.TouchEnabled == true
			M.pointer = env.uis.MouseEnabled == true
			M.gamepad = env.uis.GamepadEnabled == true
		end)
		if not okInput then M.touch, M.pointer = false, true end

		pcall(function()
			M.console = env.guisvc:IsTenFootInterface() == true
		end)
		pcall(function()
			M.reduceMotion = env.guisvc.ReducedMotionEnabled == true
		end)
		pcall(function()
			local value = tonumber(env.guisvc.PreferredTransparency)
			M.transparency = value and util.clamp(value, 0, 1) or 1
		end)

		-- The topbar overlaps the top of the screen; GetGuiInset reports by how much.
		pcall(function()
			local top = env.guisvc:GetGuiInset()
			if top then M.inset = Vector2.new(top.X, top.Y) end
		end)

		-- Mobile chat and the jump button sit at the bottom on a touch device.
		M.bottomInset = M.touch and 24 or 0

		pcall(function()
			if env.uis.OnScreenKeyboardVisible then
				local size = env.uis.OnScreenKeyboardSize
				M.keyboardHeight = (size and size.Y or 0)
			else
				M.keyboardHeight = 0
			end
		end)

		local config = env.require("runtime/config")
		local previousBreakpoint, previousMode = M.breakpoint, M.mode
		M.breakpoint = breakpointFor(width)
		M.mode = modeFor(M.breakpoint, config.get("ui.layout", "auto"))

		return previousBreakpoint ~= M.breakpoint or previousMode ~= M.mode
	end

	-- Continuous changes fire `changed`; a real mode switch also fires
	-- `modeChanged`, which is the only one that triggers a rebuild.
	local function refresh(reason)
		local switched = sample()
		M.changed:fire({ reason = reason, mode = M.mode, breakpoint = M.breakpoint, viewport = M.viewport })
		if switched then
			log.debug("responsive", string.format("%s -> %s at %dx%d (%s)",
				M.breakpoint, M.mode, M.viewport.X, M.viewport.Y, tostring(reason)))
			M.modeChanged:fire({ mode = M.mode, breakpoint = M.breakpoint })
		end
	end

	local debouncedRefresh

	function M.init(screenGui)
		M.screen = screenGui
		sample()
		M.ready = true

		debouncedRefresh = clock.debounce(function() refresh("viewport") end, 0.12)

		local okCamera, camera = pcall(function() return env.services.Workspace.CurrentCamera end)
		if okCamera and camera then
			camera:GetPropertyChangedSignal("ViewportSize"):Connect(debouncedRefresh)
		end
		-- The camera instance itself is replaced on respawn in some games, so the
		-- workspace is watched too.
		pcall(function()
			env.services.Workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(function()
				local okNew, newCamera = pcall(function() return env.services.Workspace.CurrentCamera end)
				if okNew and newCamera then
					newCamera:GetPropertyChangedSignal("ViewportSize"):Connect(debouncedRefresh)
				end
				refresh("camera")
			end)
		end)

		-- The on-screen keyboard is not a resize: the viewport does not change, so
		-- it has to be watched separately or the composer ends up behind it.
		for _, property in ipairs({ "OnScreenKeyboardVisible", "OnScreenKeyboardSize" }) do
			pcall(function()
				env.uis:GetPropertyChangedSignal(property):Connect(function()
					sample()
					M.changed:fire({ reason = "keyboard", mode = M.mode, breakpoint = M.breakpoint })
				end)
			end)
		end

		for _, property in ipairs({ "ReducedMotionEnabled", "PreferredTransparency" }) do
			pcall(function()
				env.guisvc:GetPropertyChangedSignal(property):Connect(function() refresh(property) end)
			end)
		end

		pcall(function()
			env.uis.LastInputTypeChanged:Connect(function(inputType)
				local name = tostring(inputType and inputType.Name or "")
				local wasGamepad = M.gamepad
				if name:find("Gamepad") then M.gamepad = true end
				if wasGamepad ~= M.gamepad then refresh("input") end
			end)
		end)

		local config = env.require("runtime/config")
		config.changed:connect(function(path)
			if path == "ui.layout" then refresh("setting") end
		end)

		log.info("responsive", string.format("%s / %s at %dx%d, touch %s, gamepad %s",
			M.breakpoint, M.mode, M.viewport.X, M.viewport.Y,
			M.touch and "yes" or "no", M.gamepad and "yes" or "no"))
		return M
	end

	function M.refresh(reason)
		refresh(reason or "manual")
	end

	-- Hit targets. Apple and Google both land on ~44pt for touch; a pointer can be
	-- served by much less, and cramming a mouse interface to 44px wastes the space
	-- a desktop is buying us.
	function M.minTarget()
		if M.console then return 48 end
		return M.touch and 44 or 28
	end

	function M.isNarrow()
		return M.mode == "sheet"
	end

	function M.isCompactHeight()
		return M.viewport.Y < 520 or M.keyboardHeight > 0
	end

	-- Default geometry per mode, in pixels, clamped to the viewport so the window
	-- can never open larger than the screen it is on.
	function M.geometry()
		local width, height = M.viewport.X, M.viewport.Y
		if M.mode == "sheet" then
			return {
				width = width,
				height = math.floor(height * (M.orientation == "portrait" and 0.72 or 0.9)),
				anchored = "bottom",
			}
		end
		if M.mode == "panel" then
			return {
				width = math.floor(util.clamp(width * 0.52, 320, 460)),
				height = math.floor(height - M.inset.Y - 24),
				anchored = "right",
			}
		end
		if M.mode == "tv" then
			return {
				width = math.floor(util.clamp(width * 0.62, 720, 1200)),
				height = math.floor(util.clamp(height * 0.7, 420, 760)),
				anchored = "center",
			}
		end
		return {
			width = math.floor(util.clamp(width * 0.44, 460, 780)),
			height = math.floor(util.clamp(height * 0.68, 360, 620)),
			anchored = "center",
		}
	end

	-- How much of the bottom of the screen is unusable: the on-screen keyboard when
	-- it is up, otherwise the platform's own bottom furniture.
	function M.bottomObstruction()
		if M.keyboardHeight > 0 then return M.keyboardHeight end
		return M.bottomInset
	end

	function M.describe()
		return string.format("%s / %s  %dx%d  %s%s%s",
			M.breakpoint, M.mode, M.viewport.X, M.viewport.Y,
			M.touch and "touch " or "",
			M.gamepad and "gamepad " or "",
			M.reduceMotion and "reduced-motion" or "")
	end

	return M
end
end)()

